1	import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
2	
3	/* ============================================================
4	   REELSMITH — AI short-form video studio (full SaaS app)
5	   Landing → Auth → Dashboard → AI Script → Voice & Captions →
6	   Timeline Editor with live preview → Export (SRT/script) → Billing
7	   ============================================================ */
8	
9	const CSS = `
10	@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400..800&family=Sora:wght@400;500;600;700&display=swap');
