16	  --coral:#ff6250; --yellow:#ffd23f;
17	  --text-dark:#1c1730; --text-mid:#6b6485; --text-inv:#f2eefc; --text-dim:#a79fc7;
18	}
19	.rs-root{font-family:'Sora',ui-sans-serif,system-ui,sans-serif;color:var(--text-dark);-webkit-font-smoothing:antialiased}
