28	.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;font-weight:600;border-radius:.75rem;transition:transform .12s ease, box-shadow .12s ease, opacity .12s ease;cursor:pointer;border:none}
29	.btn:hover{transform:translateY(-1px)} .btn:active{transform:translateY(0)}
30	.btn:focus-visible,.chip:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--yellow);outline-offset:2px}
31	.btn-primary{background:var(--violet);color:#fff;box-shadow:0 8px 24px rgba(108,76,241,.35)}
32	.btn-yellow{background:var(--yellow);color:#1c1730;box-shadow:0 8px 24px rgba(255,210,63,.3)}
