34	.btn-ghost-dark{background:transparent;color:var(--text-dark);border:1px solid #d9d3ea}
35	.chip{border-radius:999px;border:1px solid var(--line);cursor:pointer;transition:all .12s ease}
36	.cap-pop{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;color:#fff;text-shadow:0 2px 0 #000,0 0 14px rgba(0,0,0,.55)}
37	.cap-pop .hot{color:var(--yellow)}
38	.cap-clean{font-weight:600;color:#fff;background:rgba(0,0,0,.55);border-radius:.5rem;padding:.15em .4em}
39	.cap-clean .hot{color:#fff;text-decoration:underline;text-decoration-color:var(--violet);text-decoration-thickness:3px}
40	.cap-neon{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;color:#ffe9fd;text-shadow:0 0 10px #ff4fd8,0 0 22px #ff4fd8}
41	.cap-neon .hot{color:#fff}
42	.cap-mono{font-family:ui-monospace,Menlo,monospace;font-weight:700;color:#d6ffe1;background:rgba(6,20,10,.7);padding:.15em .4em;border-radius:.25rem}
43	.cap-mono .hot{color:var(--yellow)}
44	.phone{aspect-ratio:9/16;border-radius:1.6rem;border:6px solid #2b2344;box-shadow:0 24px 60px rgba(20,12,50,.45);overflow:hidden;position:relative}
45	.scene-grad-0{background:linear-gradient(160deg,#3b2d7a,#12102a)}
46	.scene-grad-1{background:linear-gradient(160deg,#7a2d55,#1c0f22)}
47	.scene-grad-2{background:linear-gradient(160deg,#2d5f7a,#0f1622)}
48	.scene-grad-3{background:linear-gradient(160deg,#7a5a2d,#221a0f)}
49	.scene-grad-4{background:linear-gradient(160deg,#2d7a52,#0f2218)}
50	.scene-grad-5{background:linear-gradient(160deg,#5a2d7a,#180f22)}
51	.playhead{position:absolute;top:0;bottom:0;width:2px;background:var(--yellow);box-shadow:0 0 8px var(--yellow)}
