54	@keyframes rs-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
55	.rise{animation:rs-rise .5s ease both}
56	.rise-1{animation-delay:.08s}.rise-2{animation-delay:.16s}.rise-3{animation-delay:.24s}
57	@media (prefers-reduced-motion:reduce){.rise,.rise-1,.rise-2,.rise-3{animation:none}.btn:hover{transform:none}.tick{animation:none}}
58	.marquee{white-space:nowrap;overflow:hidden}
59	input.rs,textarea.rs,select.rs{background:var(--panel2);border:1px solid var(--line);color:var(--text-inv);border-radius:.7rem;padding:.65rem .85rem;width:100%}
60	input.rs::placeholder,textarea.rs::placeholder{color:#7a719c}
61	.scrollbar-thin::-webkit-scrollbar{height:8px;width:8px}
62	.scrollbar-thin::-webkit-scrollbar-thumb{background:#3a3160;border-radius:4px}
63	`;
