65	/* ---------- constants ---------- */
66	const PLANS = [
67	  { id:"starter", name:"Starter", price:19, videos:30,  blurb:"For your first channel", perks:["30 videos / month","AI scripts & voiceover","4 caption styles","720p exports","Email support"] },
68	  { id:"creator", name:"Creator", price:39, videos:90,  blurb:"Post daily without burning out", perks:["90 videos / month","Everything in Starter","1080p exports","Ranking & list videos","Priority rendering"], featured:true },
69	  { id:"studio",  name:"Studio",  price:79, videos:200, blurb:"Run multiple channels", perks:["200 videos / month","Everything in Creator","3 workspaces","Brand presets","Priority support"] },
