72	const VIDEO_TYPES = [
73	  { id:"story",   name:"Story video",    icon:"📖", desc:"A narrated story with a hook, tension, and payoff. Reddit-style stories, history, true events." },
74	  { id:"ranking", name:"Top-5 ranking",  icon:"🏆", desc:"Count down five ranked picks. Perfect for top lists and comparisons." },
75	  { id:"facts",   name:"Facts & explainers", icon:"💡", desc:"Rapid-fire facts or a single concept explained simply." },
76	];
