78	const TONES = ["Dramatic","Casual","Energetic","Deadpan","Wholesome"];
79	
80	const VOICES = [
81	  { id:"atlas", name:"Atlas",  tag:"Deep · documentary", rate:0.92, pitch:0.8 },
82	  { id:"nova",  name:"Nova",   tag:"Bright · energetic",  rate:1.08, pitch:1.15 },
83	  { id:"ash",   name:"Ash",    tag:"Calm · storyteller",  rate:0.97, pitch:1.0 },
84	  { id:"rumor", name:"Rumor",  tag:"Fast · deadpan",      rate:1.15, pitch:0.9 },
85	];
