87	const CAPTION_STYLES = [
88	  { id:"pop",   name:"Bold Pop",  cls:"cap-pop",   sample:["THIS","IS","THE","HOOK"] },
89	  { id:"clean", name:"Clean",     cls:"cap-clean", sample:["simple","and","readable"] },
90	  { id:"neon",  name:"Neon",      cls:"cap-neon",  sample:["glow","up","your","story"] },
91	  { id:"mono",  name:"Terminal",  cls:"cap-mono",  sample:["facts.","only.","facts."] },
92	];
