94	/* ---------- helpers ---------- */
95	const wordsOf = (t) => (t || "").trim().split(/\s+/).filter(Boolean);
96	const sceneSeconds = (s) => Math.max(2, Math.round(wordsOf(s.narration).length / 2.4));
97	const projSeconds = (p) => p.scenes.reduce((a, s) => a + sceneSeconds(s), 0);
98	const fmtTime = (sec) => `${Math.floor(sec/60)}:${String(Math.round(sec%60)).padStart(2,"0")}`;
99	const uid = () => Math.random().toString(36).slice(2, 9);
100	
101	function toSRT(project){
102	  let t = 0, out = [];
103	  const stamp = (s)=>{ const ms=Math.round((s%1)*1000), ss=Math.floor(s);
104	    return `${String(Math.floor(ss/3600)).padStart(2,"0")}:${String(Math.floor(ss/60)%60).padStart(2,"0")}:${String(ss%60).padStart(2,"0")},${String(ms).padStart(3,"0")}`; };
105	  project.scenes.forEach((sc)=>{
106	    const ws = wordsOf(sc.narration), dur = sceneSeconds(sc), perChunk = 4;
107	    for(let i=0;i<ws.length;i+=perChunk){
108	      const chunk = ws.slice(i,i+perChunk).join(" ");
109	      const st = t + (i/ws.length)*dur, en = t + (Math.min(i+perChunk,ws.length)/ws.length)*dur;
110	      out.push(`${out.length+1}\n${stamp(st)} --> ${stamp(en)}\n${chunk}\n`);
111	    }
112	    t += dur;
113	  });
114	  return out.join("\n");
115	}
116	
117	function download(filename, text){
118	  const a = document.createElement("a");
119	  a.href = URL.createObjectURL(new Blob([text], {type:"text/plain"}));
120	  a.download = filename; a.click(); URL.revokeObjectURL(a.href);
121	}
122	
123	/* ---------- Claude API scriptwriting ---------- */
124	async function generateScript({ type, topic, tone, length }){
125	  const typeBrief = {
126	    story:   "a narrated story video with a strong hook, rising tension, and a payoff ending",
127	    ranking: "a top-5 countdown ranking video: the hook teases the list, then scenes count down #5 to #1, each scene covering one ranked item (name the rank in the narration)",
128	    facts:   "a rapid-fire facts / explainer video where each scene delivers one surprising fact or step",
129	  }[type];
130	  const sceneCount = type === "ranking" ? 6 : length === "short" ? 4 : length === "long" ? 8 : 6;
131	  const prompt = `You are a short-form video scriptwriter for TikTok, Reels, and YouTube Shorts.
132	Write ${typeBrief}. Topic: "${topic}". Tone: ${tone}. Exactly ${sceneCount} scenes; scene 1 is the hook.
133	Each scene's narration is 1-3 punchy spoken sentences (max ~30 words). Also give each scene a short b-roll visual idea.
134	Respond ONLY with valid JSON, no markdown fences, no preamble, exactly:
135	{"title":"...","scenes":[{"narration":"...","visual":"..."}],"hashtags":["...","...","..."]}`;
136	  const res = await fetch("https://api.anthropic.com/v1/messages", {
137	    method:"POST",
138	    headers:{ "Content-Type":"application/json" },
139	    body: JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1000, messages:[{ role:"user", content: prompt }] }),
140	  });
141	  const data = await res.json();
142	  const text = (data.content||[]).map(b=>b.type==="text"?b.text:"").join("").replace(/```json|```/g,"").trim();
143	  const parsed = JSON.parse(text);
144	  if(!parsed.scenes || !parsed.scenes.length) throw new Error("empty script");
145	  return parsed;
146	}
147	
148	/* ---------- speech playback engine ---------- */
149	function useNarrator(){
150	  const [playing, setPlaying] = useState(false);
151	  const [sceneIdx, setSceneIdx] = useState(0);
152	  const [wordIdx, setWordIdx] = useState(-1);
153	  const stopped = useRef(false);
154	
155	  const stop = useCallback(()=>{
156	    stopped.current = true;
157	    try{ window.speechSynthesis.cancel(); }catch(e){}
158	    setPlaying(false); setWordIdx(-1);
159	  },[]);
160	
161	  const play = useCallback((scenes, voice, startAt=0)=>{
162	    if(!("speechSynthesis" in window)){ return false; }
163	    stop(); stopped.current = false; setPlaying(true);
164	    const speakScene = (i)=>{
165	      if(stopped.current || i >= scenes.length){ setPlaying(false); setWordIdx(-1); return; }
166	      setSceneIdx(i); setWordIdx(0);
167	      const text = scenes[i].narration;
168	      const u = new SpeechSynthesisUtterance(text);
169	      u.rate = voice.rate; u.pitch = voice.pitch;
170	      u.onboundary = (e)=>{
171	        if(e.name === "word" || e.charIndex !== undefined){
172	          const upto = text.slice(0, e.charIndex);
173	          setWordIdx(Math.max(0, wordsOf(upto).length));
174	        }
175	      };
176	      u.onend = ()=> speakScene(i+1);
177	      u.onerror = ()=> speakScene(i+1);
178	      window.speechSynthesis.speak(u);
179	    };
180	    speakScene(startAt);
181	    return true;
182	  },[stop]);
183	
184	  useEffect(()=>()=>{ try{ window.speechSynthesis.cancel(); }catch(e){} },[]);
185	  return { playing, sceneIdx, wordIdx, play, stop, setSceneIdx };
186	}
