198	function CaptionLine({ words, hotIdx, styleCls, size="text-xl" }){
199	  return (
200	    <div className={`${styleCls} ${size} text-center leading-tight`} style={{maxWidth:"90%"}}>
201	      {words.map((w,i)=>(
202	        <span key={i} className={i===hotIdx ? "hot" : ""}>{w}{i<words.length-1?" ":""}</span>
