208	function PhonePreview({ scene, sceneIndex, words, hotIdx, captionCls, footer }){
209	  return (
210	    <div className={`phone w-full scene-grad-${sceneIndex % 6}`}>
211	      <div className="absolute inset-0 flex flex-col items-center justify-end pb-16 pt-8 px-3">
