225	/* ============================================================
226	   LANDING
227	   ============================================================ */
228	const DEMO_LINES = [
229	  "You film nothing. You edit nothing.",
230	  "Type an idea. Reelsmith writes the script,",
231	  "voices it, captions it, cuts it.",
232	  "Post four videos before lunch.",
233	];
234	
235	function HeroPhone(){
236	  const [line, setLine] = useState(0);
237	  const [hot, setHot] = useState(0);
238	  const words = wordsOf(DEMO_LINES[line]);
239	  useEffect(()=>{
240	    const iv = setInterval(()=>{
241	      setHot(h=>{
242	        if(h+1 < words.length) return h+1;
243	        setLine(l=>(l+1)%DEMO_LINES.length);
244	        return 0;
245	      });
246	    }, 320);
247	    return ()=>clearInterval(iv);
248	  },[line, words.length]);
249	  return (
250	    <div className="mx-auto w-56 sm:w-64">
251	      <PhonePreview
252	        scene={{}} sceneIndex={line}
253	        words={words} hotIdx={hot} captionCls="cap-pop"
254	        footer={
255	          <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center gap-2">
256	            <span className="bg-coral h-2 w-2 rounded-full tick"></span>
257	            <span className="t-dim text-xs">rendering preview…</span>
258	          </div>
259	        }
260	      />
261	    </div>
262	  );
263	}
264	
265	function Landing({ onStart, onSignIn }){
266	  const faqs = [
267	    ["Do I need editing experience?","No. You type a topic; Reelsmith writes the script, generates the voiceover, times the captions, and assembles the cut. You can adjust anything on the timeline afterwards."],
268	    ["Can it make videos without my face or voice?","Yes. Every video can be fully faceless: AI narration, animated captions, and b-roll suggestions for each scene."],
269	    ["Which platforms does it export for?","Vertical 9:16 exports tuned for TikTok, Instagram Reels, YouTube Shorts, and Facebook."],
270	    ["How many videos can I make?","Starter includes 30 videos a month, Creator 90, and Studio 200. Upgrade or cancel any time — no lock-in."],
271	  ];
272	  const [open, setOpen] = useState(0);
273	  return (
274	    <div className="bg-paper min-h-screen">
275	      {/* nav */}
276	      <nav className="mx-auto flex max-w-6xl items-center justify-between px-5 py-5">
277	        <Logo />
278	        <div className="flex items-center gap-3">
279	          <button className="btn btn-ghost-dark px-4 py-2 text-sm" onClick={onSignIn}>Sign in</button>
280	          <button className="btn btn-primary px-4 py-2 text-sm" onClick={onStart}>Start free</button>
281	        </div>
282	      </nav>
283	
284	      {/* hero */}
285	      <header className="mx-auto grid max-w-6xl items-center gap-10 px-5 pb-20 pt-10 md:grid-cols-2">
286	        <div className="rise">
287	          <p className="t-violet mb-4 text-xs font-bold uppercase tracking-widest">AI video studio for short-form</p>
288	          <h1 className="font-display text-5xl font-extrabold leading-none tracking-tight sm:text-6xl">
289	            The whole edit,<br/>from one <span className="t-coral">sentence.</span>
290	          </h1>
291	          <p className="t-mid mt-5 max-w-md text-lg">
292	            Reelsmith turns an idea into a finished short: AI script, natural voiceover, word-timed captions, and a cut you can tweak on a timeline. Built for TikTok, Reels, and Shorts.
293	          </p>
294	          <div className="mt-7 flex flex-wrap gap-3">
295	            <button className="btn btn-yellow px-6 py-3" onClick={onStart}>Make my first video</button>
296	            <button className="btn btn-ghost-dark px-6 py-3" onClick={onSignIn}>I have an account</button>
297	          </div>
298	          <p className="t-mid mt-4 text-sm">Free to try · no card required · cancel anytime</p>
299	        </div>
300	        <div className="rise rise-2"><HeroPhone /></div>
301	      </header>
302	
303	      {/* how it works */}
304	      <section className="bg-ink py-20">
305	        <div className="mx-auto max-w-6xl px-5">
306	          <h2 className="font-display t-inv text-3xl font-extrabold sm:text-4xl">Idea in. Video out.</h2>
307	          <p className="t-dim mt-2 max-w-lg">Four steps, all inside one tool. No Premiere. No stitching five apps together.</p>
308	          <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
309	            {[
310	              ["Script","Tell it the topic and tone. Claude writes a hook-first script broken into scenes."],
311	              ["Voice","Pick a narrator. Reelsmith reads the script aloud with natural pacing."],
312	              ["Captions","Word-timed karaoke captions in four styles, synced to the voice automatically."],
313	              ["Cut & export","Reorder scenes on the timeline, then export the cut with captions (.srt) ready to post."],
314	            ].map(([t,d],i)=>(
315	              <div key={t} className={`bg-panel rounded-2xl border b-line p-5 rise rise-${i}`}>
316	                <div className="bg-yellow inline-flex h-8 w-8 items-center justify-center rounded-lg font-display font-extrabold" style={{color:"#1c1730"}}>{i+1}</div>
317	                <h3 className="t-inv mt-3 font-display text-lg font-bold">{t}</h3>
318	                <p className="t-dim mt-1 text-sm">{d}</p>
319	              </div>
320	            ))}
321	          </div>
322	        </div>
323	      </section>
324	
325	      {/* formats */}
326	      <section className="mx-auto max-w-6xl px-5 py-20">
327	        <h2 className="font-display text-3xl font-extrabold sm:text-4xl">Every format that performs</h2>
328	        <div className="mt-8 grid gap-4 md:grid-cols-3">
329	          {VIDEO_TYPES.map(v=>(
330	            <div key={v.id} className="bg-card b-soft rounded-2xl border p-6 shadow-sm">
331	              <div className="text-3xl">{v.icon}</div>
332	              <h3 className="font-display mt-3 text-xl font-bold">{v.name}</h3>
333	              <p className="t-mid mt-1 text-sm">{v.desc}</p>
334	            </div>
335	          ))}
336	        </div>
337	      </section>
338	
339	      {/* pricing */}
340	      <section className="bg-violet-soft py-20">
341	        <div className="mx-auto max-w-6xl px-5">
342	          <h2 className="font-display text-3xl font-extrabold sm:text-4xl">Simple plans, real limits up front</h2>
343	          <p className="t-mid mt-2">Monthly video counts are the plan — no hidden throttles, no per-minute surprises.</p>
344	          <div className="mt-10 grid gap-5 md:grid-cols-3">
345	            {PLANS.map(p=>(
346	              <div key={p.id} className={`rounded-2xl border p-6 ${p.featured ? "bg-ink b-line" : "bg-card b-soft"}`}>
347	                {p.featured && <span className="bg-yellow rounded-full px-3 py-1 text-xs font-bold" style={{color:"#1c1730"}}>Most popular</span>}
348	                <h3 className={`font-display mt-3 text-2xl font-extrabold ${p.featured?"t-inv":""}`}>{p.name}</h3>
349	                <p className={`text-sm ${p.featured?"t-dim":"t-mid"}`}>{p.blurb}</p>
350	                <p className={`mt-4 font-display text-4xl font-extrabold ${p.featured?"t-yellow":""}`}>${p.price}<span className={`text-base font-semibold ${p.featured?"t-dim":"t-mid"}`}>/mo</span></p>
351	                <ul className={`mt-4 space-y-2 text-sm ${p.featured?"t-dim":"t-mid"}`}>
352	                  {p.perks.map(x=><li key={x}>✓ {x}</li>)}
353	                </ul>
354	                <button className={`btn mt-6 w-full py-3 ${p.featured?"btn-yellow":"btn-primary"}`} onClick={onStart}>Choose {p.name}</button>
355	              </div>
356	            ))}
357	          </div>
358	        </div>
359	      </section>
360	
361	      {/* faq */}
362	      <section className="mx-auto max-w-3xl px-5 py-20">
363	        <h2 className="font-display text-3xl font-extrabold">Questions, answered</h2>
364	        <div className="mt-6 divide-y" style={{borderColor:"#e6e1f2"}}>
365	          {faqs.map(([q,a],i)=>(
366	            <div key={q} className="py-4">
367	              <button className="flex w-full items-center justify-between text-left font-semibold" onClick={()=>setOpen(open===i?-1:i)} aria-expanded={open===i}>
368	                {q}<span className="t-violet ml-4">{open===i?"–":"+"}</span>
369	              </button>
370	              {open===i && <p className="t-mid mt-2 text-sm">{a}</p>}
371	            </div>
372	          ))}
373	        </div>
374	      </section>
