591	function Studio({ project, onChange, onBack, onExported, remaining }){
592	  const nar = useNarrator();
593	  const [sel, setSel] = useState(0);
594	  const [exporting, setExporting] = useState(false);
595	  const [progress, setProgress] = useState(0);
596	  const [doneOpen, setDoneOpen] = useState(false);
597	  const voice = VOICES.find(v=>v.id===project.voice);
598	  const capCls = CAPTION_STYLES.find(c=>c.id===project.caption).cls;
599	  const activeIdx = nar.playing ? nar.sceneIdx : sel;
600	  const scene = project.scenes[activeIdx] || project.scenes[0];
601	  const words = wordsOf(scene?.narration || "");
602	  const total = projSeconds(project);
603	  const [speechOk, setSpeechOk] = useState(true);
604	
605	  const setScene = (i, patch)=> onChange({ ...project, scenes: project.scenes.map((s,idx)=> idx===i ? {...s, ...patch} : s) });
606	  const move = (i, dir)=>{
607	    const j = i + dir; if(j<0 || j>=project.scenes.length) return;
608	    const sc=[...project.scenes]; [sc[i],sc[j]]=[sc[j],sc[i]];
609	    onChange({...project, scenes:sc}); setSel(j);
610	  };
611	  const removeScene = (i)=>{
612	    if(project.scenes.length<=2) return;
613	    onChange({...project, scenes: project.scenes.filter((_,idx)=>idx!==i)});
614	    setSel(Math.max(0, i-1));
615	  };
616	  const togglePlay = ()=>{
617	    if(nar.playing){ nar.stop(); return; }
618	    const ok = nar.play(project.scenes, voice, sel);
619	    if(ok===false) setSpeechOk(false);
620	  };
621	  const runExport = ()=>{
622	    if(remaining<=0) return;
623	    nar.stop(); setExporting(true); setProgress(0);
624	    const iv = setInterval(()=>{
625	      setProgress(p=>{
626	        if(p>=100){ clearInterval(iv); setExporting(false); setDoneOpen(true); onExported(); return 100; }
627	        return p + Math.random()*9 + 3;
628	      });
629	    }, 180);
630	  };
631	
632	  return (
633	    <div className="mx-auto max-w-6xl px-5 py-6">
634	      <div className="flex flex-wrap items-center justify-between gap-3">
635	        <button className="t-dim text-sm" onClick={()=>{nar.stop(); onBack();}}>← Studio</button>
636	        <input className="rs font-display max-w-md text-center font-bold" value={project.title} onChange={e=>onChange({...project, title:e.target.value})} aria-label="Video title" />
637	        <button className="btn btn-yellow px-5 py-2.5" onClick={runExport} disabled={exporting}
638	          style={remaining<=0?{opacity:.5}:{}}>
639	          {remaining<=0 ? "Plan limit reached" : "Export video"}
640	        </button>
641	      </div>
642	
643	      <div className="mt-6 grid gap-6 lg:grid-cols-5">
644	        {/* preview column */}
