646	          <div className="mx-auto w-52 sm:w-60">
647	            <PhonePreview scene={scene} sceneIndex={activeIdx} words={words}
648	              hotIdx={nar.playing && nar.sceneIdx===activeIdx ? nar.wordIdx : -1} captionCls={capCls}
649	              footer={
650	                <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center">
651	                  <button className="btn btn-yellow h-11 w-11 rounded-full text-lg" onClick={togglePlay} aria-label={nar.playing?"Stop preview":"Play preview"}>
652	                    {nar.playing ? "■" : "▶"}
653	                  </button>
654	                </div>
655	              } />
656	          </div>
657	          {!speechOk && <p className="t-coral mt-3 text-center text-xs">Voice preview isn't available in this browser — captions still preview above.</p>}
658	          <p className="t-dim mt-3 text-center text-xs">Scene {activeIdx+1} of {project.scenes.length} · total {fmtTime(total)}</p>
659	
660	          {/* voice + captions */}
661	          <div className="bg-panel mt-5 rounded-2xl border b-line p-4">
662	            <p className="t-dim text-xs font-bold uppercase tracking-widest">Narrator</p>
663	            <div className="mt-2 grid grid-cols-2 gap-2">
664	              {VOICES.map(v=>(
665	                <button key={v.id} className={`chip p-2.5 text-left ${project.voice===v.id?"bg-panel2":""}`}
666	                  style={project.voice===v.id?{borderColor:"var(--yellow)"}:{}}
667	                  onClick={()=>{nar.stop(); onChange({...project, voice:v.id});}}>
668	                  <span className="t-inv block text-sm font-bold">{v.name}</span>
669	                  <span className="t-dim text-xs">{v.tag}</span>
670	                </button>
671	              ))}
672	            </div>
673	            <p className="t-dim mt-3 text-xs font-bold uppercase tracking-widest">Caption style</p>
674	            <div className="mt-2 grid grid-cols-2 gap-2">
675	              {CAPTION_STYLES.map(c=>(
676	                <button key={c.id} className={`chip flex h-16 flex-col items-center justify-center scene-grad-2 rounded-xl ${project.caption===c.id?"":"opacity-80"}`}
677	                  style={project.caption===c.id?{borderColor:"var(--yellow)",borderWidth:2}:{}}
