import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";

/* ============================================================
   REELSMITH — AI short-form video studio (full SaaS app)
   Landing → Auth → Dashboard → AI Script → Voice & Captions →
   Timeline Editor with live preview → Export (SRT/script) → Billing
   ============================================================ */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400..800&family=Sora:wght@400;500;600;700&display=swap');

:root{
  --ink:#141020; --panel:#1d1730; --panel2:#262040; --line:#332b52;
  --paper:#f6f4fb; --card:#ffffff;
  --violet:#6c4cf1; --violet-soft:#e9e4ff;
  --coral:#ff6250; --yellow:#ffd23f;
  --text-dark:#1c1730; --text-mid:#6b6485; --text-inv:#f2eefc; --text-dim:#a79fc7;
}
.rs-root{font-family:'Sora',ui-sans-serif,system-ui,sans-serif;color:var(--text-dark);-webkit-font-smoothing:antialiased}
.font-display{font-family:'Bricolage Grotesque','Sora',sans-serif}
.bg-ink{background:var(--ink)} .bg-panel{background:var(--panel)} .bg-panel2{background:var(--panel2)}
.bg-paper{background:var(--paper)} .bg-card{background:var(--card)}
.bg-violet{background:var(--violet)} .bg-violet-soft{background:var(--violet-soft)}
.bg-coral{background:var(--coral)} .bg-yellow{background:var(--yellow)}
.t-inv{color:var(--text-inv)} .t-dim{color:var(--text-dim)} .t-mid{color:var(--text-mid)}
.t-violet{color:var(--violet)} .t-coral{color:var(--coral)} .t-yellow{color:var(--yellow)}
.b-line{border-color:var(--line)} .b-soft{border-color:#e6e1f2}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;font-weight:600;border-radius:.75rem;transition:transform .12s ease, box-shadow .12s ease, opacity .12s ease;cursor:pointer;border:none}
.btn:hover{transform:translateY(-1px)} .btn:active{transform:translateY(0)}
.btn:focus-visible,.chip:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--yellow);outline-offset:2px}
.btn-primary{background:var(--violet);color:#fff;box-shadow:0 8px 24px rgba(108,76,241,.35)}
.btn-yellow{background:var(--yellow);color:#1c1730;box-shadow:0 8px 24px rgba(255,210,63,.3)}
.btn-ghost{background:transparent;color:var(--text-inv);border:1px solid var(--line)}
.btn-ghost-dark{background:transparent;color:var(--text-dark);border:1px solid #d9d3ea}
.chip{border-radius:999px;border:1px solid var(--line);cursor:pointer;transition:all .12s ease}
.cap-pop{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;color:#fff;text-shadow:0 2px 0 #000,0 0 14px rgba(0,0,0,.55)}
.cap-pop .hot{color:var(--yellow)}
.cap-clean{font-weight:600;color:#fff;background:rgba(0,0,0,.55);border-radius:.5rem;padding:.15em .4em}
.cap-clean .hot{color:#fff;text-decoration:underline;text-decoration-color:var(--violet);text-decoration-thickness:3px}
.cap-neon{font-family:'Bricolage Grotesque',sans-serif;font-weight:800;color:#ffe9fd;text-shadow:0 0 10px #ff4fd8,0 0 22px #ff4fd8}
.cap-neon .hot{color:#fff}
.cap-mono{font-family:ui-monospace,Menlo,monospace;font-weight:700;color:#d6ffe1;background:rgba(6,20,10,.7);padding:.15em .4em;border-radius:.25rem}
.cap-mono .hot{color:var(--yellow)}
.phone{aspect-ratio:9/16;border-radius:1.6rem;border:6px solid #2b2344;box-shadow:0 24px 60px rgba(20,12,50,.45);overflow:hidden;position:relative}
.scene-grad-0{background:linear-gradient(160deg,#3b2d7a,#12102a)}
.scene-grad-1{background:linear-gradient(160deg,#7a2d55,#1c0f22)}
.scene-grad-2{background:linear-gradient(160deg,#2d5f7a,#0f1622)}
.scene-grad-3{background:linear-gradient(160deg,#7a5a2d,#221a0f)}
.scene-grad-4{background:linear-gradient(160deg,#2d7a52,#0f2218)}
.scene-grad-5{background:linear-gradient(160deg,#5a2d7a,#180f22)}
.playhead{position:absolute;top:0;bottom:0;width:2px;background:var(--yellow);box-shadow:0 0 8px var(--yellow)}
.tick{animation:rs-blink 1s steps(2) infinite}
@keyframes rs-blink{50%{opacity:.25}}
@keyframes rs-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.rise{animation:rs-rise .5s ease both}
.rise-1{animation-delay:.08s}.rise-2{animation-delay:.16s}.rise-3{animation-delay:.24s}
@media (prefers-reduced-motion:reduce){.rise,.rise-1,.rise-2,.rise-3{animation:none}.btn:hover{transform:none}.tick{animation:none}}
.marquee{white-space:nowrap;overflow:hidden}
input.rs,textarea.rs,select.rs{background:var(--panel2);border:1px solid var(--line);color:var(--text-inv);border-radius:.7rem;padding:.65rem .85rem;width:100%}
input.rs::placeholder,textarea.rs::placeholder{color:#7a719c}
.scrollbar-thin::-webkit-scrollbar{height:8px;width:8px}
.scrollbar-thin::-webkit-scrollbar-thumb{background:#3a3160;border-radius:4px}
`;

/* ---------- constants ---------- */
const PLANS = [
  { id:"starter", name:"Starter", price:19, videos:30,  blurb:"For your first channel", perks:["30 videos / month","AI scripts & voiceover","4 caption styles","720p exports","Email support"] },
  { id:"creator", name:"Creator", price:39, videos:90,  blurb:"Post daily without burning out", perks:["90 videos / month","Everything in Starter","1080p exports","Ranking & list videos","Priority rendering"], featured:true },
  { id:"studio",  name:"Studio",  price:79, videos:200, blurb:"Run multiple channels", perks:["200 videos / month","Everything in Creator","3 workspaces","Brand presets","Priority support"] },
];

const VIDEO_TYPES = [
  { id:"story",   name:"Story video",    icon:"📖", desc:"A narrated story with a hook, tension, and payoff. Reddit-style stories, history, true events." },
  { id:"ranking", name:"Top-5 ranking",  icon:"🏆", desc:"Count down five ranked picks. Perfect for top lists and comparisons." },
  { id:"facts",   name:"Facts & explainers", icon:"💡", desc:"Rapid-fire facts or a single concept explained simply." },
];

const TONES = ["Dramatic","Casual","Energetic","Deadpan","Wholesome"];

const VOICES = [
  { id:"atlas", name:"Atlas",  tag:"Deep · documentary", rate:0.92, pitch:0.8 },
  { id:"nova",  name:"Nova",   tag:"Bright · energetic",  rate:1.08, pitch:1.15 },
  { id:"ash",   name:"Ash",    tag:"Calm · storyteller",  rate:0.97, pitch:1.0 },
  { id:"rumor", name:"Rumor",  tag:"Fast · deadpan",      rate:1.15, pitch:0.9 },
];

const CAPTION_STYLES = [
  { id:"pop",   name:"Bold Pop",  cls:"cap-pop",   sample:["THIS","IS","THE","HOOK"] },
  { id:"clean", name:"Clean",     cls:"cap-clean", sample:["simple","and","readable"] },
  { id:"neon",  name:"Neon",      cls:"cap-neon",  sample:["glow","up","your","story"] },
  { id:"mono",  name:"Terminal",  cls:"cap-mono",  sample:["facts.","only.","facts."] },
];

/* ---------- helpers ---------- */
const wordsOf = (t) => (t || "").trim().split(/\s+/).filter(Boolean);
const sceneSeconds = (s) => Math.max(2, Math.round(wordsOf(s.narration).length / 2.4));
const projSeconds = (p) => p.scenes.reduce((a, s) => a + sceneSeconds(s), 0);
const fmtTime = (sec) => `${Math.floor(sec/60)}:${String(Math.round(sec%60)).padStart(2,"0")}`;
const uid = () => Math.random().toString(36).slice(2, 9);

function toSRT(project){
  let t = 0, out = [];
  const stamp = (s)=>{ const ms=Math.round((s%1)*1000), ss=Math.floor(s);
    return `${String(Math.floor(ss/3600)).padStart(2,"0")}:${String(Math.floor(ss/60)%60).padStart(2,"0")}:${String(ss%60).padStart(2,"0")},${String(ms).padStart(3,"0")}`; };
  project.scenes.forEach((sc)=>{
    const ws = wordsOf(sc.narration), dur = sceneSeconds(sc), perChunk = 4;
    for(let i=0;i<ws.length;i+=perChunk){
      const chunk = ws.slice(i,i+perChunk).join(" ");
      const st = t + (i/ws.length)*dur, en = t + (Math.min(i+perChunk,ws.length)/ws.length)*dur;
      out.push(`${out.length+1}\n${stamp(st)} --> ${stamp(en)}\n${chunk}\n`);
    }
    t += dur;
  });
  return out.join("\n");
}

function download(filename, text){
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([text], {type:"text/plain"}));
  a.download = filename; a.click(); URL.revokeObjectURL(a.href);
}

/* ---------- Claude API scriptwriting ---------- */
async function generateScript({ type, topic, tone, length }){
  const typeBrief = {
    story:   "a narrated story video with a strong hook, rising tension, and a payoff ending",
    ranking: "a top-5 countdown ranking video: the hook teases the list, then scenes count down #5 to #1, each scene covering one ranked item (name the rank in the narration)",
    facts:   "a rapid-fire facts / explainer video where each scene delivers one surprising fact or step",
  }[type];
  const sceneCount = type === "ranking" ? 6 : length === "short" ? 4 : length === "long" ? 8 : 6;
  const prompt = `You are a short-form video scriptwriter for TikTok, Reels, and YouTube Shorts.
Write ${typeBrief}. Topic: "${topic}". Tone: ${tone}. Exactly ${sceneCount} scenes; scene 1 is the hook.
Each scene's narration is 1-3 punchy spoken sentences (max ~30 words). Also give each scene a short b-roll visual idea.
Respond ONLY with valid JSON, no markdown fences, no preamble, exactly:
{"title":"...","scenes":[{"narration":"...","visual":"..."}],"hashtags":["...","...","..."]}`;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method:"POST",
    headers:{ "Content-Type":"application/json" },
    body: JSON.stringify({ model:"claude-sonnet-4-6", max_tokens:1000, messages:[{ role:"user", content: prompt }] }),
  });
  const data = await res.json();
  const text = (data.content||[]).map(b=>b.type==="text"?b.text:"").join("").replace(/```json|```/g,"").trim();
  const parsed = JSON.parse(text);
  if(!parsed.scenes || !parsed.scenes.length) throw new Error("empty script");
  return parsed;
}

/* ---------- speech playback engine ---------- */
function useNarrator(){
  const [playing, setPlaying] = useState(false);
  const [sceneIdx, setSceneIdx] = useState(0);
  const [wordIdx, setWordIdx] = useState(-1);
  const stopped = useRef(false);

  const stop = useCallback(()=>{
    stopped.current = true;
    try{ window.speechSynthesis.cancel(); }catch(e){}
    setPlaying(false); setWordIdx(-1);
  },[]);

  const play = useCallback((scenes, voice, startAt=0)=>{
    if(!("speechSynthesis" in window)){ return false; }
    stop(); stopped.current = false; setPlaying(true);
    const speakScene = (i)=>{
      if(stopped.current || i >= scenes.length){ setPlaying(false); setWordIdx(-1); return; }
      setSceneIdx(i); setWordIdx(0);
      const text = scenes[i].narration;
      const u = new SpeechSynthesisUtterance(text);
      u.rate = voice.rate; u.pitch = voice.pitch;
      u.onboundary = (e)=>{
        if(e.name === "word" || e.charIndex !== undefined){
          const upto = text.slice(0, e.charIndex);
          setWordIdx(Math.max(0, wordsOf(upto).length));
        }
      };
      u.onend = ()=> speakScene(i+1);
      u.onerror = ()=> speakScene(i+1);
      window.speechSynthesis.speak(u);
    };
    speakScene(startAt);
    return true;
  },[stop]);

  useEffect(()=>()=>{ try{ window.speechSynthesis.cancel(); }catch(e){} },[]);
  return { playing, sceneIdx, wordIdx, play, stop, setSceneIdx };
}

/* ---------- shared bits ---------- */
function Logo({ dark }){
  return (
    <span className="font-display flex items-center gap-2 text-xl font-extrabold tracking-tight" style={{color: dark ? "var(--text-inv)" : "var(--text-dark)"}}>
      <span className="bg-yellow inline-flex h-7 w-7 items-center justify-center rounded-lg text-sm" style={{color:"#1c1730"}}>▶</span>
      reelsmith
    </span>
  );
}

function CaptionLine({ words, hotIdx, styleCls, size="text-xl" }){
  return (
    <div className={`${styleCls} ${size} text-center leading-tight`} style={{maxWidth:"90%"}}>
      {words.map((w,i)=>(
        <span key={i} className={i===hotIdx ? "hot" : ""}>{w}{i<words.length-1?" ":""}</span>
      ))}
    </div>
  );
}

function PhonePreview({ scene, sceneIndex, words, hotIdx, captionCls, footer }){
  return (
    <div className={`phone w-full scene-grad-${sceneIndex % 6}`}>
      <div className="absolute inset-0 flex flex-col items-center justify-end pb-16 pt-8 px-3">
        <div className="absolute top-3 left-0 right-0 flex justify-center">
          <span className="t-dim text-xs tracking-widest uppercase">{scene?.visual ? "b-roll" : ""}</span>
        </div>
        {scene?.visual && (
          <div className="absolute top-7 left-3 right-3 text-center t-dim text-xs italic opacity-80">{scene.visual}</div>
        )}
        <CaptionLine words={words} hotIdx={hotIdx} styleCls={captionCls} />
      </div>
      {footer}
    </div>
  );
}

/* ============================================================
   LANDING
   ============================================================ */
const DEMO_LINES = [
  "You film nothing. You edit nothing.",
  "Type an idea. Reelsmith writes the script,",
  "voices it, captions it, cuts it.",
  "Post four videos before lunch.",
];

function HeroPhone(){
  const [line, setLine] = useState(0);
  const [hot, setHot] = useState(0);
  const words = wordsOf(DEMO_LINES[line]);
  useEffect(()=>{
    const iv = setInterval(()=>{
      setHot(h=>{
        if(h+1 < words.length) return h+1;
        setLine(l=>(l+1)%DEMO_LINES.length);
        return 0;
      });
    }, 320);
    return ()=>clearInterval(iv);
  },[line, words.length]);
  return (
    <div className="mx-auto w-56 sm:w-64">
      <PhonePreview
        scene={{}} sceneIndex={line}
        words={words} hotIdx={hot} captionCls="cap-pop"
        footer={
          <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center gap-2">
            <span className="bg-coral h-2 w-2 rounded-full tick"></span>
            <span className="t-dim text-xs">rendering preview…</span>
          </div>
        }
      />
    </div>
  );
}

function Landing({ onStart, onSignIn }){
  const faqs = [
    ["Do I need editing experience?","No. You type a topic; Reelsmith writes the script, generates the voiceover, times the captions, and assembles the cut. You can adjust anything on the timeline afterwards."],
    ["Can it make videos without my face or voice?","Yes. Every video can be fully faceless: AI narration, animated captions, and b-roll suggestions for each scene."],
    ["Which platforms does it export for?","Vertical 9:16 exports tuned for TikTok, Instagram Reels, YouTube Shorts, and Facebook."],
    ["How many videos can I make?","Starter includes 30 videos a month, Creator 90, and Studio 200. Upgrade or cancel any time — no lock-in."],
  ];
  const [open, setOpen] = useState(0);
  return (
    <div className="bg-paper min-h-screen">
      {/* nav */}
      <nav className="mx-auto flex max-w-6xl items-center justify-between px-5 py-5">
        <Logo />
        <div className="flex items-center gap-3">
          <button className="btn btn-ghost-dark px-4 py-2 text-sm" onClick={onSignIn}>Sign in</button>
          <button className="btn btn-primary px-4 py-2 text-sm" onClick={onStart}>Start free</button>
        </div>
      </nav>

      {/* hero */}
      <header className="mx-auto grid max-w-6xl items-center gap-10 px-5 pb-20 pt-10 md:grid-cols-2">
        <div className="rise">
          <p className="t-violet mb-4 text-xs font-bold uppercase tracking-widest">AI video studio for short-form</p>
          <h1 className="font-display text-5xl font-extrabold leading-none tracking-tight sm:text-6xl">
            The whole edit,<br/>from one <span className="t-coral">sentence.</span>
          </h1>
          <p className="t-mid mt-5 max-w-md text-lg">
            Reelsmith turns an idea into a finished short: AI script, natural voiceover, word-timed captions, and a cut you can tweak on a timeline. Built for TikTok, Reels, and Shorts.
          </p>
          <div className="mt-7 flex flex-wrap gap-3">
            <button className="btn btn-yellow px-6 py-3" onClick={onStart}>Make my first video</button>
            <button className="btn btn-ghost-dark px-6 py-3" onClick={onSignIn}>I have an account</button>
          </div>
          <p className="t-mid mt-4 text-sm">Free to try · no card required · cancel anytime</p>
        </div>
        <div className="rise rise-2"><HeroPhone /></div>
      </header>

      {/* how it works */}
      <section className="bg-ink py-20">
        <div className="mx-auto max-w-6xl px-5">
          <h2 className="font-display t-inv text-3xl font-extrabold sm:text-4xl">Idea in. Video out.</h2>
          <p className="t-dim mt-2 max-w-lg">Four steps, all inside one tool. No Premiere. No stitching five apps together.</p>
          <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {[
              ["Script","Tell it the topic and tone. Claude writes a hook-first script broken into scenes."],
              ["Voice","Pick a narrator. Reelsmith reads the script aloud with natural pacing."],
              ["Captions","Word-timed karaoke captions in four styles, synced to the voice automatically."],
              ["Cut & export","Reorder scenes on the timeline, then export the cut with captions (.srt) ready to post."],
            ].map(([t,d],i)=>(
              <div key={t} className={`bg-panel rounded-2xl border b-line p-5 rise rise-${i}`}>
                <div className="bg-yellow inline-flex h-8 w-8 items-center justify-center rounded-lg font-display font-extrabold" style={{color:"#1c1730"}}>{i+1}</div>
                <h3 className="t-inv mt-3 font-display text-lg font-bold">{t}</h3>
                <p className="t-dim mt-1 text-sm">{d}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* formats */}
      <section className="mx-auto max-w-6xl px-5 py-20">
        <h2 className="font-display text-3xl font-extrabold sm:text-4xl">Every format that performs</h2>
        <div className="mt-8 grid gap-4 md:grid-cols-3">
          {VIDEO_TYPES.map(v=>(
