/* ============================================================
   AUTH (in-session demo accounts)
   ============================================================ */
function Auth({ mode, onDone, onSwitch, onBack }){
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [pw, setPw] = useState("");
  const [err, setErr] = useState("");
  const signup = mode === "signup";
  const submit = ()=>{
    if(!email.includes("@")) return setErr("Enter a valid email address.");
    if(pw.length < 6) return setErr("Password needs at least 6 characters.");
    if(signup && !name.trim()) return setErr("Add a display name so we know what to call you.");
    onDone({ name: signup ? name.trim() : email.split("@")[0], email });
  };
  return (
    <div className="bg-ink flex min-h-screen items-center justify-center px-5">
      <div className="bg-panel w-full max-w-md rounded-2xl border b-line p-8 rise">
        <Logo dark />
        <h1 className="font-display t-inv mt-6 text-2xl font-extrabold">{signup ? "Create your studio" : "Welcome back"}</h1>
        <p className="t-dim mt-1 text-sm">{signup ? "Free to start — your first videos are on us." : "Sign in to keep forging."}</p>
        <div className="mt-6 space-y-3">
          {signup && <input className="rs" placeholder="Display name" value={name} onChange={e=>setName(e.target.value)} aria-label="Display name" />}
          <input className="rs" placeholder="Email" type="email" value={email} onChange={e=>setEmail(e.target.value)} aria-label="Email" />
          <input className="rs" placeholder="Password" type="password" value={pw} onChange={e=>{setPw(e.target.value); setErr("");}} aria-label="Password" />
          {err && <p className="t-coral text-sm">{err}</p>}
          <button className="btn btn-yellow w-full py-3" onClick={submit}>{signup ? "Create account" : "Sign in"}</button>
        </div>
        <p className="t-dim mt-5 text-sm">
          {signup ? "Already have an account? " : "New here? "}
          <button className="t-yellow font-semibold" onClick={onSwitch}>{signup ? "Sign in" : "Start free"}</button>
          <span className="mx-2">·</span>
          <button className="underline" onClick={onBack}>Back to site</button>
        </p>
        <p className="t-dim mt-3 text-xs">Demo build: accounts live in this session only.</p>
      </div>
    </div>
  );
}

