/* ============================================================
   CREATE WIZARD (type → brief → generating)
   ============================================================ */
function CreateWizard({ onCancel, onCreated }){
  const [step, setStep] = useState(0);
  const [type, setType] = useState(null);
  const [topic, setTopic] = useState("");
  const [tone, setTone] = useState("Dramatic");
  const [length, setLength] = useState("medium");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const go = async ()=>{
    if(topic.trim().length < 3) return setErr("Give the topic a few more words to work with.");
    setErr(""); setBusy(true);
    try{
      const script = await generateScript({ type, topic, tone, length });
      onCreated({
        id: uid(), type, topic, tone,
        title: script.title || topic,
        hashtags: script.hashtags || [],
        scenes: script.scenes.map(s=>({ id: uid(), narration: s.narration, visual: s.visual || "" })),
        voice: "ash", caption: "pop", exported: false,
      });
    }catch(e){
      setErr("Script generation hit a snag — try again in a moment.");
      setBusy(false);
    }
  };

  return (
    <div className="mx-auto max-w-3xl px-5 py-10">
      <button className="t-dim text-sm" onClick={onCancel}>← Back to studio</button>
      {step===0 && (
        <div className="rise">
          <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">What are we making?</h1>
          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            {VIDEO_TYPES.map(v=>(
              <button key={v.id} className={`bg-panel rounded-2xl border p-5 text-left transition ${type===v.id?"border-yellow-400":"b-line hover:border-yellow-400"}`}
                onClick={()=>setType(v.id)} style={type===v.id?{borderColor:"var(--yellow)"}:{}}>
                <div className="text-3xl">{v.icon}</div>
                <h3 className="t-inv mt-2 font-display font-bold">{v.name}</h3>
                <p className="t-dim mt-1 text-xs">{v.desc}</p>
              </button>
            ))}
          </div>
          <button className="btn btn-yellow mt-8 px-6 py-3" disabled={!type} style={!type?{opacity:.4,cursor:"not-allowed"}:{}} onClick={()=>type&&setStep(1)}>Next: the brief</button>
        </div>
      )}
      {step===1 && !busy && (
        <div className="rise">
          <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">Give it the idea</h1>
          <p className="t-dim mt-1">One sentence is enough. Claude writes the full scene-by-scene script.</p>
          <div className="mt-6 space-y-5">
            <textarea className="rs" rows={3} placeholder={type==="ranking" ? "e.g. Top 5 most expensive mistakes in space history" : "e.g. The night a lighthouse keeper vanished without a trace"}
              value={topic} onChange={e=>{setTopic(e.target.value); setErr("");}} aria-label="Video topic" />
            <div>
              <p className="t-dim mb-2 text-xs font-bold uppercase tracking-widest">Tone</p>
              <div className="flex flex-wrap gap-2">
                {TONES.map(t=>(
                  <button key={t} className={`chip px-4 py-1.5 text-sm ${tone===t?"bg-yellow font-bold":"t-dim"}`} style={tone===t?{color:"#1c1730",borderColor:"var(--yellow)"}:{}} onClick={()=>setTone(t)}>{t}</button>
                ))}
              </div>
            </div>
            <div>
              <p className="t-dim mb-2 text-xs font-bold uppercase tracking-widest">Length</p>
              <div className="flex gap-2">
                {[["short","~20s"],["medium","~35s"],["long","~55s"]].map(([id,label])=>(
                  <button key={id} className={`chip px-4 py-1.5 text-sm ${length===id?"bg-yellow font-bold":"t-dim"}`} style={length===id?{color:"#1c1730",borderColor:"var(--yellow)"}:{}} onClick={()=>setLength(id)}>{label}</button>
                ))}
              </div>
            </div>
            {err && <p className="t-coral text-sm">{err}</p>}
            <div className="flex gap-3">
              <button className="btn btn-ghost px-5 py-3" onClick={()=>setStep(0)}>Back</button>
              <button className="btn btn-yellow px-6 py-3" onClick={go}>Write my script ✨</button>
            </div>
          </div>
        </div>
      )}
      {busy && (
        <div className="mt-16 flex flex-col items-center text-center rise">
          <div className="phone w-40 scene-grad-0 flex items-end justify-center pb-10">
            <CaptionLine words={["writing","your","script…"]} hotIdx={Math.floor(Date.now()/400)%3} styleCls="cap-pop" size="text-base" />
          </div>
          <p className="t-inv mt-6 font-display text-xl font-bold">Claude is drafting your scenes</p>
          <p className="t-dim mt-1 text-sm">Hook first, payoff last. A few seconds…</p>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   STUDIO EDITOR (timeline + live preview + export)
   ============================================================ */
function Studio({ project, onChange, onBack, onExported, remaining }){
  const nar = useNarrator();
  const [sel, setSel] = useState(0);
  const [exporting, setExporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [doneOpen, setDoneOpen] = useState(false);
  const voice = VOICES.find(v=>v.id===project.voice);
  const capCls = CAPTION_STYLES.find(c=>c.id===project.caption).cls;
  const activeIdx = nar.playing ? nar.sceneIdx : sel;
  const scene = project.scenes[activeIdx] || project.scenes[0];
  const words = wordsOf(scene?.narration || "");
  const total = projSeconds(project);
  const [speechOk, setSpeechOk] = useState(true);

  const setScene = (i, patch)=> onChange({ ...project, scenes: project.scenes.map((s,idx)=> idx===i ? {...s, ...patch} : s) });
  const move = (i, dir)=>{
    const j = i + dir; if(j<0 || j>=project.scenes.length) return;
    const sc=[...project.scenes]; [sc[i],sc[j]]=[sc[j],sc[i]];
    onChange({...project, scenes:sc}); setSel(j);
  };
  const removeScene = (i)=>{
    if(project.scenes.length<=2) return;
    onChange({...project, scenes: project.scenes.filter((_,idx)=>idx!==i)});
    setSel(Math.max(0, i-1));
  };
  const togglePlay = ()=>{
    if(nar.playing){ nar.stop(); return; }
    const ok = nar.play(project.scenes, voice, sel);
    if(ok===false) setSpeechOk(false);
  };
  const runExport = ()=>{
    if(remaining<=0) return;
    nar.stop(); setExporting(true); setProgress(0);
    const iv = setInterval(()=>{
      setProgress(p=>{
        if(p>=100){ clearInterval(iv); setExporting(false); setDoneOpen(true); onExported(); return 100; }
        return p + Math.random()*9 + 3;
      });
    }, 180);
  };

  return (
    <div className="mx-auto max-w-6xl px-5 py-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <button className="t-dim text-sm" onClick={()=>{nar.stop(); onBack();}}>← Studio</button>
        <input className="rs font-display max-w-md text-center font-bold" value={project.title} onChange={e=>onChange({...project, title:e.target.value})} aria-label="Video title" />
        <button className="btn btn-yellow px-5 py-2.5" onClick={runExport} disabled={exporting}
          style={remaining<=0?{opacity:.5}:{}}>
          {remaining<=0 ? "Plan limit reached" : "Export video"}
        </button>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-5">
        {/* preview column */}
        <div className="lg:col-span-2">
          <div className="mx-auto w-52 sm:w-60">
            <PhonePreview scene={scene} sceneIndex={activeIdx} words={words}
              hotIdx={nar.playing && nar.sceneIdx===activeIdx ? nar.wordIdx : -1} captionCls={capCls}
              footer={
                <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center">
                  <button className="btn btn-yellow h-11 w-11 rounded-full text-lg" onClick={togglePlay} aria-label={nar.playing?"Stop preview":"Play preview"}>
                    {nar.playing ? "■" : "▶"}
                  </button>
                </div>
              } />
          </div>
          {!speechOk && <p className="t-coral mt-3 text-center text-xs">Voice preview isn't available in this browser — captions still preview above.</p>}
          <p className="t-dim mt-3 text-center text-xs">Scene {activeIdx+1} of {project.scenes.length} · total {fmtTime(total)}</p>

          {/* voice + captions */}
          <div className="bg-panel mt-5 rounded-2xl border b-line p-4">
            <p className="t-dim text-xs font-bold uppercase tracking-widest">Narrator</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {VOICES.map(v=>(
                <button key={v.id} className={`chip p-2.5 text-left ${project.voice===v.id?"bg-panel2":""}`}
                  style={project.voice===v.id?{borderColor:"var(--yellow)"}:{}}
                  onClick={()=>{nar.stop(); onChange({...project, voice:v.id});}}>
                  <span className="t-inv block text-sm font-bold">{v.name}</span>
                  <span className="t-dim text-xs">{v.tag}</span>
                </button>
              ))}
            </div>
            <p className="t-dim mt-3 text-xs font-bold uppercase tracking-widest">Caption style</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {CAPTION_STYLES.map(c=>(
                <button key={c.id} className={`chip flex h-16 flex-col items-center justify-center scene-grad-2 rounded-xl ${project.caption===c.id?"":"opacity-80"}`}
                  style={project.caption===c.id?{borderColor:"var(--yellow)",borderWidth:2}:{}}
                  onClick={()=>onChange({...project, caption:c.id})} aria-label={`Caption style ${c.name}`}>
                  <CaptionLine words={c.sample} hotIdx={1} styleCls={c.cls} size="text-xs" />
                  <span className="t-dim mt-1 uppercase tracking-widest" style={{fontSize:10}}>{c.name}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* timeline column */}
        <div className="lg:col-span-3">
          <div className="bg-panel rounded-2xl border b-line p-4">
            <div className="flex items-center justify-between">
              <p className="t-dim text-xs font-bold uppercase tracking-widest">Timeline</p>
              <p className="t-dim text-xs">{project.hashtags?.slice(0,3).map(h=>`#${h.replace(/^#/,"")}`).join("  ")}</p>
            </div>
            {/* strip */}
            <div className="scrollbar-thin relative mt-3 flex gap-1 overflow-x-auto rounded-xl bg-panel2 p-2">
              {project.scenes.map((s,i)=>{
                const w = Math.max(56, sceneSeconds(s)*14);
                return (
                  <button key={s.id} onClick={()=>{nar.stop(); setSel(i);}}
                    className={`scene-grad-${i%6} relative shrink-0 rounded-lg border-2 p-1 text-left`}
                    style={{width:w, height:64, borderColor: i===activeIdx ? "var(--yellow)" : "transparent"}}
                    aria-label={`Scene ${i+1}`}>
                    <span className="cap-pop absolute left-1 top-1" style={{fontSize:10}}>{i+1}</span>
                    <span className="t-inv absolute bottom-1 left-1 right-1 truncate opacity-80" style={{fontSize:10}}>{s.narration}</span>
                  </button>
                );
              })}
            </div>
            {/* scene inspector */}
            <div className="mt-4">
              <div className="flex items-center justify-between">
                <p className="t-inv font-display font-bold">Scene {sel+1}{sel===0?" · Hook":""} <span className="t-dim text-xs font-normal">({sceneSeconds(project.scenes[sel])}s)</span></p>
                <div className="flex gap-1.5">
                  <button className="btn btn-ghost px-2.5 py-1 text-xs" onClick={()=>move(sel,-1)} aria-label="Move scene earlier">←</button>
                  <button className="btn btn-ghost px-2.5 py-1 text-xs" onClick={()=>move(sel,1)} aria-label="Move scene later">→</button>
                  <button className="btn btn-ghost px-2.5 py-1 text-xs t-coral" onClick={()=>removeScene(sel)} aria-label="Delete scene">Delete</button>
                </div>
              </div>
              <textarea className="rs mt-2" rows={3} value={project.scenes[sel].narration}
                onChange={e=>setScene(sel,{narration:e.target.value})} aria-label="Scene narration" />
              <input className="rs mt-2 text-sm" value={project.scenes[sel].visual} placeholder="B-roll / visual idea for this scene"
                onChange={e=>setScene(sel,{visual:e.target.value})} aria-label="Scene visual idea" />
              <button className="btn btn-ghost mt-3 px-4 py-2 text-sm"
                onClick={()=>{ const sc=[...project.scenes]; sc.splice(sel+1,0,{id:uid(),narration:"New scene — write the beat here.",visual:""}); onChange({...project,scenes:sc}); setSel(sel+1); }}>
                + Add scene after
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* export overlay */}
      {(exporting || doneOpen) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-5">
          <div className="bg-panel w-full max-w-md rounded-2xl border b-line p-7 text-center rise">
            {exporting ? (
              <>
                <p className="font-display t-inv text-xl font-extrabold">Rendering your short</p>
                <p className="t-dim mt-1 text-sm">Mixing voiceover, timing captions, cutting scenes…</p>
                <div className="bg-panel2 mt-5 h-3 overflow-hidden rounded-full">
                  <div className="bg-yellow h-full rounded-full" style={{width:`${Math.min(100,progress)}%`, transition:"width .18s linear"}}></div>
                </div>
                <p className="t-yellow mt-2 font-display font-bold">{Math.min(100,Math.floor(progress))}%</p>
              </>
            ) : (
              <>
                <div className="text-4xl">✅</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Export complete</p>
                <p className="t-dim mt-1 text-sm">This demo build exports your production package — script and word-timed captions ready for any editor or scheduler. (Hook up an FFmpeg render worker for MP4s.)</p>
                <div className="mt-5 grid gap-2">
                  <button className="btn btn-yellow py-2.5" onClick={()=>download(`${project.title.replace(/\W+/g,"-").toLowerCase()}.srt`, toSRT(project))}>Download captions (.srt)</button>
                  <button className="btn btn-ghost py-2.5" onClick={()=>download(`${project.title.replace(/\W+/g,"-").toLowerCase()}-script.txt`,
                    `${project.title}\n\n${project.scenes.map((s,i)=>`SCENE ${i+1} (${sceneSeconds(s)}s)\nVO: ${s.narration}\nB-ROLL: ${s.visual}\n`).join("\n")}\nHASHTAGS: ${(project.hashtags||[]).map(h=>"#"+h.replace(/^#/,"")).join(" ")}`)}>Download script (.txt)</button>
                  <button className="btn btn-ghost py-2.5" onClick={()=>setDoneOpen(false)}>Back to editor</button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   BILLING
   ============================================================ */
function Billing({ user, onChangePlan, onBack }){
  return (
    <div className="mx-auto max-w-5xl px-5 py-10">
      <button className="t-dim text-sm" onClick={onBack}>← Back to studio</button>
      <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">Plan & billing</h1>
      <p className="t-dim mt-1">You're on <span className="t-yellow font-bold">{PLANS.find(p=>p.id===user.plan).name}</span> · {user.used} videos used this month. Switch plans any time — changes apply instantly in this demo.</p>
      <div className="mt-8 grid gap-4 md:grid-cols-3">
        {PLANS.map(p=>(
          <div key={p.id} className={`bg-panel rounded-2xl border p-6 ${user.plan===p.id?"":"b-line"}`} style={user.plan===p.id?{borderColor:"var(--yellow)"}:{}}>
            <h3 className="font-display t-inv text-xl font-extrabold">{p.name}</h3>
            <p className="t-yellow font-display mt-2 text-3xl font-extrabold">${p.price}<span className="t-dim text-sm">/mo</span></p>
            <p className="t-dim mt-1 text-sm">{p.videos} videos / month</p>
            <button className={`btn mt-5 w-full py-2.5 ${user.plan===p.id?"btn-ghost":"btn-yellow"}`}
              onClick={()=>onChangePlan(p.id)} disabled={user.plan===p.id}>
              {user.plan===p.id ? "Current plan" : "Switch to " + p.name}
            </button>
          </div>
        ))}
      </div>
      <p className="t-dim mt-6 text-xs">Production note: wire these buttons to Stripe Checkout + a customer portal for real subscriptions.</p>
    </div>
  );
}

/* ============================================================
   APP SHELL + ROOT
   ============================================================ */
export default function ReelsmithApp(){
  const [route, setRoute] = useState("landing"); // landing | signin | signup | app
  const [view, setView] = useState("dash");      // dash | create | studio | billing
  const [user, setUser] = useState(null);
  const [projects, setProjects] = useState([]);
  const [openId, setOpenId] = useState(null);

  const plan = user ? PLANS.find(p=>p.id===user.plan) : null;
  const remaining = user ? plan.videos - user.used : 0;
  const project = projects.find(p=>p.id===openId);

  const signIn = (u)=>{ setUser({ ...u, plan:"starter", used:0 }); setRoute("app"); setView("dash"); };

  if(route==="landing") return (<div className="rs-root"><style>{CSS}</style><Landing onStart={()=>setRoute("signup")} onSignIn={()=>setRoute("signin")} /></div>);
  if(route==="signin"||route==="signup") return (
    <div className="rs-root"><style>{CSS}</style>
      <Auth mode={route==="signup"?"signup":"signin"} onDone={signIn}
        onSwitch={()=>setRoute(route==="signup"?"signin":"signup")} onBack={()=>setRoute("landing")} />
    </div>
  );

  return (
    <div className="rs-root bg-ink min-h-screen">
      <style>{CSS}</style>
      <nav className="border-b b-line">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-3">
          <button onClick={()=>{setView("dash"); setOpenId(null);}}><Logo dark /></button>
          <div className="flex items-center gap-3">
            <span className="t-dim hidden text-sm sm:block">{remaining} videos left · {plan.name}</span>
            <button className="btn btn-ghost px-3 py-1.5 text-sm" onClick={()=>setView("billing")}>Billing</button>
            <button className="btn btn-ghost px-3 py-1.5 text-sm" onClick={()=>{setUser(null); setProjects([]); setRoute("landing");}}>Sign out</button>
          </div>
        </div>
      </nav>

      {view==="dash" && <Dashboard user={user} projects={projects}
        onNew={()=>setView("create")} onBilling={()=>setView("billing")}
        onOpen={(id)=>{setOpenId(id); setView("studio");}} />}

      {view==="create" && <CreateWizard onCancel={()=>setView("dash")}
        onCreated={(p)=>{ setProjects(ps=>[p,...ps]); setOpenId(p.id); setView("studio"); }} />}

      {view==="studio" && project && <Studio project={project} remaining={remaining}
        onChange={(np)=>setProjects(ps=>ps.map(p=>p.id===np.id?np:p))}
        onBack={()=>{setOpenId(null); setView("dash");}}
        onExported={()=>{
          setProjects(ps=>ps.map(p=>p.id===project.id?{...p, exported:true}:p));
          setUser(u=>({...u, used:u.used+1}));
        }} />}

      {view==="billing" && <Billing user={user} onBack={()=>setView("dash")}
        onChangePlan={(id)=>setUser(u=>({...u, plan:id}))} />}
    </div>
  );
}

