@import "tailwindcss";

/* ============================================================
   REELSMITH design system — ported verbatim from the prototype.
   Fonts are loaded via next/font (see app/layout.tsx) and exposed
   as --font-display / --font-body.
   ============================================================ */

:root {
  --ink: #141020;
  --panel: #1d1730;
  --panel2: #262040;
  --line: #332b52;
  --paper: #f6f4fb;
  --card: #ffffff;
  --violet: #6c4cf1;
  --violet-soft: #e9e4ff;
  --coral: #ff6250;
  --yellow: #ffd23f;
  --text-dark: #1c1730;
  --text-mid: #6b6485;
  --text-inv: #f2eefc;
  --text-dim: #a79fc7;
}

body {
  background: var(--paper);
  color: var(--text-dark);
}

.rs-root {
  font-family: var(--font-body), "Sora", ui-sans-serif, system-ui, sans-serif;
  color: var(--text-dark);
  -webkit-font-smoothing: antialiased;
}
.font-display {
  font-family: var(--font-display), "Bricolage Grotesque", "Sora", sans-serif;
}

.bg-ink { background: var(--ink); }
.bg-panel { background: var(--panel); }
.bg-panel2 { background: var(--panel2); }
.bg-paper { background: var(--paper); }
.bg-card { background: var(--card); }
.bg-violet { background: var(--violet); }
.bg-violet-soft { background: var(--violet-soft); }
.bg-coral { background: var(--coral); }
.bg-yellow { background: var(--yellow); }
.t-inv { color: var(--text-inv); }
.t-dim { color: var(--text-dim); }
.t-mid { color: var(--text-mid); }
.t-violet { color: var(--violet); }
.t-coral { color: var(--coral); }
.t-yellow { color: var(--yellow); }
.b-line { border-color: var(--line); }
.b-soft { border-color: #e6e1f2; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  border-radius: 0.75rem;
  transition: transform 0.12s ease, box-shadow 0.12s ease, opacity 0.12s ease;
  cursor: pointer;
  border: none;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn:focus-visible,
.chip:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--yellow);
  outline-offset: 2px;
}
.btn-primary { background: var(--violet); color: #fff; box-shadow: 0 8px 24px rgba(108, 76, 241, 0.35); }
.btn-yellow { background: var(--yellow); color: #1c1730; box-shadow: 0 8px 24px rgba(255, 210, 63, 0.3); }
.btn-ghost { background: transparent; color: var(--text-inv); border: 1px solid var(--line); }
.btn-ghost-dark { background: transparent; color: var(--text-dark); border: 1px solid #d9d3ea; }

.chip {
  border-radius: 999px;
  border: 1px solid var(--line);
  cursor: pointer;
  transition: all 0.12s ease;
}

.cap-pop {
  font-family: var(--font-display), "Bricolage Grotesque", sans-serif;
  font-weight: 800;
  color: #fff;
  text-shadow: 0 2px 0 #000, 0 0 14px rgba(0, 0, 0, 0.55);
}
.cap-pop .hot { color: var(--yellow); }
.cap-clean {
  font-weight: 600;
  color: #fff;
  background: rgba(0, 0, 0, 0.55);
  border-radius: 0.5rem;
  padding: 0.15em 0.4em;
}
.cap-clean .hot {
  color: #fff;
  text-decoration: underline;
  text-decoration-color: var(--violet);
  text-decoration-thickness: 3px;
}
.cap-neon {
  font-family: var(--font-display), "Bricolage Grotesque", sans-serif;
  font-weight: 800;
  color: #ffe9fd;
  text-shadow: 0 0 10px #ff4fd8, 0 0 22px #ff4fd8;
}
.cap-neon .hot { color: #fff; }
.cap-mono {
  font-family: ui-monospace, Menlo, monospace;
  font-weight: 700;
  color: #d6ffe1;
  background: rgba(6, 20, 10, 0.7);
  padding: 0.15em 0.4em;
  border-radius: 0.25rem;
}
.cap-mono .hot { color: var(--yellow); }

.phone {
  aspect-ratio: 9 / 16;
  border-radius: 1.6rem;
  border: 6px solid #2b2344;
  box-shadow: 0 24px 60px rgba(20, 12, 50, 0.45);
  overflow: hidden;
  position: relative;
}
.scene-grad-0 { background: linear-gradient(160deg, #3b2d7a, #12102a); }
.scene-grad-1 { background: linear-gradient(160deg, #7a2d55, #1c0f22); }
.scene-grad-2 { background: linear-gradient(160deg, #2d5f7a, #0f1622); }
.scene-grad-3 { background: linear-gradient(160deg, #7a5a2d, #221a0f); }
.scene-grad-4 { background: linear-gradient(160deg, #2d7a52, #0f2218); }
.scene-grad-5 { background: linear-gradient(160deg, #5a2d7a, #180f22); }

.playhead {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--yellow);
  box-shadow: 0 0 8px var(--yellow);
}
.tick { animation: rs-blink 1s steps(2) infinite; }
@keyframes rs-blink {
  50% { opacity: 0.25; }
}
@keyframes rs-rise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: none; }
}
.rise { animation: rs-rise 0.5s ease both; }
.rise-1 { animation-delay: 0.08s; }
.rise-2 { animation-delay: 0.16s; }
.rise-3 { animation-delay: 0.24s; }
@media (prefers-reduced-motion: reduce) {
  .rise, .rise-1, .rise-2, .rise-3 { animation: none; }
  .btn:hover { transform: none; }
  .tick { animation: none; }
}

.marquee { white-space: nowrap; overflow: hidden; }

input.rs,
textarea.rs,
select.rs {
  background: var(--panel2);
  border: 1px solid var(--line);
  color: var(--text-inv);
  border-radius: 0.7rem;
  padding: 0.65rem 0.85rem;
  width: 100%;
}
input.rs::placeholder,
textarea.rs::placeholder {
  color: #7a719c;
}

.scrollbar-thin::-webkit-scrollbar { height: 8px; width: 8px; }
.scrollbar-thin::-webkit-scrollbar-thumb { background: #3a3160; border-radius: 4px; }

