import type { Metadata } from "next";
import { Bricolage_Grotesque, Sora } from "next/font/google";
import "./globals.css";
import { StoreProvider } from "@/lib/store";

const display = Bricolage_Grotesque({
  variable: "--font-display",
  subsets: ["latin"],
  weight: "variable",
});

const body = Sora({
  variable: "--font-body",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
});

export const metadata: Metadata = {
  title: "Reelsmith — AI short-form video studio",
  description:
    "Turn one sentence into a finished short: AI script, natural voiceover, word-timed captions, and a cut you can tweak on a timeline. Built for TikTok, Reels, and Shorts.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className={`${display.variable} ${body.variable}`}>
      <body className="rs-root min-h-screen">
        <StoreProvider>{children}</StoreProvider>
      </body>
    </html>
  );
}

