import type { Project, Scene } from "./types";

/* Word-timing math lives here and nowhere else (CLAUDE.md convention) —
   reused by the live preview, the SRT export, and later the FFmpeg
   caption burn-in. */

export const wordsOf = (t: string | undefined | null): string[] =>
  (t || "").trim().split(/\s+/).filter(Boolean);

export const sceneSeconds = (s: Pick<Scene, "narration">): number =>
  Math.max(2, Math.round(wordsOf(s.narration).length / 2.4));

export const projSeconds = (p: Pick<Project, "scenes">): number =>
  p.scenes.reduce((a, s) => a + sceneSeconds(s), 0);

export const fmtTime = (sec: number): string =>
  `${Math.floor(sec / 60)}:${String(Math.round(sec % 60)).padStart(2, "0")}`;

export const uid = (): string => Math.random().toString(36).slice(2, 9);

export function toSRT(project: Pick<Project, "scenes">): string {
  let t = 0;
  const out: string[] = [];
  const stamp = (s: number) => {
    const ms = Math.round((s % 1) * 1000);
    const ss = Math.floor(s);
    return `${String(Math.floor(ss / 3600)).padStart(2, "0")}:${String(
      Math.floor(ss / 60) % 60,
    ).padStart(2, "0")}:${String(ss % 60).padStart(2, "0")},${String(ms).padStart(3, "0")}`;
  };
  project.scenes.forEach((sc) => {
    const ws = wordsOf(sc.narration);
    const dur = sceneSeconds(sc);
    const perChunk = 4;
    for (let i = 0; i < ws.length; i += perChunk) {
      const chunk = ws.slice(i, i + perChunk).join(" ");
      const st = t + (i / ws.length) * dur;
      const en = t + (Math.min(i + perChunk, ws.length) / ws.length) * dur;
      out.push(`${out.length + 1}\n${stamp(st)} --> ${stamp(en)}\n${chunk}\n`);
    }
    t += dur;
  });
  return out.join("\n");
}

export function scriptText(project: Project): string {
  return `${project.title}\n\n${project.scenes
    .map(
      (s, i) => `SCENE ${i + 1} (${sceneSeconds(s)}s)\nVO: ${s.narration}\nB-ROLL: ${s.visual}\n`,
    )
    .join("\n")}\nHASHTAGS: ${(project.hashtags || [])
    .map((h) => "#" + h.replace(/^#/, ""))
    .join(" ")}`;
}

export function download(filename: string, text: string): void {
  const a = document.createElement("a");
  a.href = URL.createObjectURL(new Blob([text], { type: "text/plain" }));
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}

export const slugify = (s: string): string => s.replace(/\W+/g, "-").toLowerCase();

