"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { Voice } from "./constants";
import type { Scene } from "./types";
import { wordsOf } from "./timing";

/* Browser speechSynthesis narration with word-boundary caption sync.
   Stays as the free preview once server-side TTS lands (roadmap step 6). */
export function useNarrator() {
  const [playing, setPlaying] = useState(false);
  const [sceneIdx, setSceneIdx] = useState(0);
  const [wordIdx, setWordIdx] = useState(-1);
  const stopped = useRef(false);

  const stop = useCallback(() => {
    stopped.current = true;
    try {
      window.speechSynthesis.cancel();
    } catch {
      /* no speech support */
    }
    setPlaying(false);
    setWordIdx(-1);
  }, []);

  const play = useCallback(
    (scenes: Scene[], voice: Voice, startAt = 0): boolean => {
      if (!("speechSynthesis" in window)) return false;
      stop();
      stopped.current = false;
      setPlaying(true);
      const speakScene = (i: number) => {
        if (stopped.current || i >= scenes.length) {
          setPlaying(false);
          setWordIdx(-1);
          return;
        }
        setSceneIdx(i);
        setWordIdx(0);
        const text = scenes[i].narration;
        const u = new SpeechSynthesisUtterance(text);
        u.rate = voice.rate;
        u.pitch = voice.pitch;
        u.onboundary = (e) => {
          if (e.name === "word" || e.charIndex !== undefined) {
            const upto = text.slice(0, e.charIndex);
            setWordIdx(Math.max(0, wordsOf(upto).length));
          }
        };
        u.onend = () => speakScene(i + 1);
        u.onerror = () => speakScene(i + 1);
        window.speechSynthesis.speak(u);
      };
      speakScene(startAt);
      return true;
    },
    [stop],
  );

  useEffect(
    () => () => {
      try {
        window.speechSynthesis.cancel();
      } catch {
        /* no speech support */
      }
    },
    [],
  );

  return { playing, sceneIdx, wordIdx, play, stop, setSceneIdx };
}

