import type { ReactNode } from "react";
import type { Scene } from "@/lib/types";

export function Logo({ dark }: { dark?: boolean }) {
  return (
    <span
      className="font-display flex items-center gap-2 text-xl font-extrabold tracking-tight"
      style={{ color: dark ? "var(--text-inv)" : "var(--text-dark)" }}
    >
      <span
        className="bg-yellow inline-flex h-7 w-7 items-center justify-center rounded-lg text-sm"
        style={{ color: "#1c1730" }}
      >
        ▶
      </span>
      reelsmith
    </span>
  );
}

export function CaptionLine({
  words,
  hotIdx,
  styleCls,
  size = "text-xl",
}: {
  words: string[];
  hotIdx: number;
  styleCls: string;
  size?: string;
}) {
  return (
    <div className={`${styleCls} ${size} text-center leading-tight`} style={{ maxWidth: "90%" }}>
      {words.map((w, i) => (
        <span key={i} className={i === hotIdx ? "hot" : ""}>
