          {i < words.length - 1 ? " " : ""}
        </span>
      ))}
    </div>
  );
}

export function PhonePreview({
  scene,
  sceneIndex,
  words,
  hotIdx,
  captionCls,
  footer,
}: {
  scene: Partial<Scene> | undefined;
  sceneIndex: number;
  words: string[];
  hotIdx: number;
  captionCls: string;
  footer?: ReactNode;
}) {
  return (
    <div className={`phone w-full scene-grad-${sceneIndex % 6}`}>
      <div className="absolute inset-0 flex flex-col items-center justify-end px-3 pb-16 pt-8">
        <div className="absolute left-0 right-0 top-3 flex justify-center">
          <span className="t-dim text-xs uppercase tracking-widest">
            {scene?.visual ? "b-roll" : ""}
          </span>
        </div>
        {scene?.visual && (
          <div className="t-dim absolute left-3 right-3 top-7 text-center text-xs italic opacity-80">
