"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { CaptionLine, Logo, PhonePreview } from "@/components/shared";
import { PLANS, VIDEO_TYPES } from "@/lib/constants";
import { wordsOf } from "@/lib/timing";

const DEMO_LINES = [
  "You film nothing. You edit nothing.",
  "Type an idea. Reelsmith writes the script,",
  "voices it, captions it, cuts it.",
  "Post four videos before lunch.",
];

function HeroPhone() {
  const [line, setLine] = useState(0);
  const [hot, setHot] = useState(0);
  const words = wordsOf(DEMO_LINES[line]);
  useEffect(() => {
    const iv = setInterval(() => {
      setHot((h) => {
        if (h + 1 < words.length) return h + 1;
        setLine((l) => (l + 1) % DEMO_LINES.length);
        return 0;
      });
    }, 320);
    return () => clearInterval(iv);
  }, [line, words.length]);
  return (
    <div className="mx-auto w-56 sm:w-64">
      <PhonePreview
        scene={{}}
        sceneIndex={line}
        words={words}
        hotIdx={hot}
        captionCls="cap-pop"
        footer={
          <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center gap-2">
            <span className="bg-coral tick h-2 w-2 rounded-full"></span>
            <span className="t-dim text-xs">rendering preview…</span>
          </div>
        }
      />
    </div>
  );
}

const FAQS: [string, string][] = [
  [
    "Do I need editing experience?",
    "No. You type a topic; Reelsmith writes the script, generates the voiceover, times the captions, and assembles the cut. You can adjust anything on the timeline afterwards.",
  ],
  [
    "Can it make videos without my face or voice?",
    "Yes. Every video can be fully faceless: AI narration, animated captions, and b-roll suggestions for each scene.",
  ],
  [
    "Which platforms does it export for?",
    "Vertical 9:16 exports tuned for TikTok, Instagram Reels, YouTube Shorts, and Facebook.",
  ],
  [
    "How many videos can I make?",
    "Starter includes 30 videos a month, Creator 90, and Studio 200. Upgrade or cancel any time — no lock-in.",
  ],
];

export default function Landing() {
  const [open, setOpen] = useState(0);
  return (
    <div className="bg-paper min-h-screen">
      {/* nav */}
      <nav className="mx-auto flex max-w-6xl items-center justify-between px-5 py-5">
        <Logo />
        <div className="flex items-center gap-3">
          <Link href="/login" className="btn btn-ghost-dark px-4 py-2 text-sm">
            Sign in
          </Link>
          <Link href="/login?mode=signup" className="btn btn-primary px-4 py-2 text-sm">
            Start free
          </Link>
        </div>
      </nav>

      {/* hero */}
      <header className="mx-auto grid max-w-6xl items-center gap-10 px-5 pb-20 pt-10 md:grid-cols-2">
        <div className="rise">
          <p className="t-violet mb-4 text-xs font-bold uppercase tracking-widest">
            AI video studio for short-form
          </p>
          <h1 className="font-display text-5xl font-extrabold leading-none tracking-tight sm:text-6xl">
            The whole edit,
            <br />
            from one <span className="t-coral">sentence.</span>
          </h1>
          <p className="t-mid mt-5 max-w-md text-lg">
            Reelsmith turns an idea into a finished short: AI script, natural voiceover, word-timed
            captions, and a cut you can tweak on a timeline. Built for TikTok, Reels, and Shorts.
          </p>
          <div className="mt-7 flex flex-wrap gap-3">
            <Link href="/login?mode=signup" className="btn btn-yellow px-6 py-3">
              Make my first video
            </Link>
            <Link href="/login" className="btn btn-ghost-dark px-6 py-3">
              I have an account
            </Link>
          </div>
          <p className="t-mid mt-4 text-sm">Free to try · no card required · cancel anytime</p>
        </div>
        <div className="rise rise-2">
          <HeroPhone />
        </div>
      </header>

      {/* how it works */}
      <section className="bg-ink py-20">
        <div className="mx-auto max-w-6xl px-5">
          <h2 className="font-display t-inv text-3xl font-extrabold sm:text-4xl">
            Idea in. Video out.
          </h2>
          <p className="t-dim mt-2 max-w-lg">
            Four steps, all inside one tool. No Premiere. No stitching five apps together.
          </p>
          <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {[
              ["Script", "Tell it the topic and tone. Claude writes a hook-first script broken into scenes."],
              ["Voice", "Pick a narrator. Reelsmith reads the script aloud with natural pacing."],
              ["Captions", "Word-timed karaoke captions in four styles, synced to the voice automatically."],
              ["Cut & export", "Reorder scenes on the timeline, then export the cut with captions (.srt) ready to post."],
            ].map(([t, d], i) => (
              <div key={t} className={`bg-panel b-line rounded-2xl border p-5 rise rise-${i}`}>
                <div
                  className="bg-yellow font-display inline-flex h-8 w-8 items-center justify-center rounded-lg font-extrabold"
                  style={{ color: "#1c1730" }}
                >
                  {i + 1}
                </div>
                <h3 className="t-inv font-display mt-3 text-lg font-bold">{t}</h3>
                <p className="t-dim mt-1 text-sm">{d}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* formats */}
      <section className="mx-auto max-w-6xl px-5 py-20">
        <h2 className="font-display text-3xl font-extrabold sm:text-4xl">
          Every format that performs
        </h2>
        <div className="mt-8 grid gap-4 md:grid-cols-3">
          {VIDEO_TYPES.map((v) => (
            <div key={v.id} className="bg-card b-soft rounded-2xl border p-6 shadow-sm">
              <div className="text-3xl">{v.icon}</div>
              <h3 className="font-display mt-3 text-xl font-bold">{v.name}</h3>
              <p className="t-mid mt-1 text-sm">{v.desc}</p>
            </div>
          ))}
        </div>
      </section>

      {/* pricing */}
      <section className="bg-violet-soft py-20">
        <div className="mx-auto max-w-6xl px-5">
          <h2 className="font-display text-3xl font-extrabold sm:text-4xl">
            Simple plans, real limits up front
          </h2>
          <p className="t-mid mt-2">
            Monthly video counts are the plan — no hidden throttles, no per-minute surprises.
          </p>
          <div className="mt-10 grid gap-5 md:grid-cols-3">
            {PLANS.map((p) => (
              <div
                key={p.id}
                className={`rounded-2xl border p-6 ${p.featured ? "bg-ink b-line" : "bg-card b-soft"}`}
              >
                {p.featured && (
                  <span
                    className="bg-yellow rounded-full px-3 py-1 text-xs font-bold"
                    style={{ color: "#1c1730" }}
                  >
                    Most popular
                  </span>
                )}
                <h3
                  className={`font-display mt-3 text-2xl font-extrabold ${p.featured ? "t-inv" : ""}`}
                >
                  {p.name}
                </h3>
                <p className={`text-sm ${p.featured ? "t-dim" : "t-mid"}`}>{p.blurb}</p>
                <p
                  className={`font-display mt-4 text-4xl font-extrabold ${p.featured ? "t-yellow" : ""}`}
                >
                  ${p.price}
                  <span className={`text-base font-semibold ${p.featured ? "t-dim" : "t-mid"}`}>
                    /mo
                  </span>
                </p>
                <ul className={`mt-4 space-y-2 text-sm ${p.featured ? "t-dim" : "t-mid"}`}>
                  {p.perks.map((x) => (
                    <li key={x}>✓ {x}</li>
                  ))}
                </ul>
                <Link
                  href="/login?mode=signup"
                  className={`btn mt-6 w-full py-3 ${p.featured ? "btn-yellow" : "btn-primary"}`}
                >
                  Choose {p.name}
                </Link>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* faq */}
      <section className="mx-auto max-w-3xl px-5 py-20">
        <h2 className="font-display text-3xl font-extrabold">Questions, answered</h2>
        <div className="mt-6 divide-y" style={{ borderColor: "#e6e1f2" }}>
          {FAQS.map(([q, a], i) => (
            <div key={q} className="py-4">
              <button
                className="flex w-full items-center justify-between text-left font-semibold"
                onClick={() => setOpen(open === i ? -1 : i)}
                aria-expanded={open === i}
              >
                {q}
                <span className="t-violet ml-4">{open === i ? "–" : "+"}</span>
              </button>
              {open === i && <p className="t-mid mt-2 text-sm">{a}</p>}
            </div>
          ))}
        </div>
      </section>

      <footer className="bg-ink py-10">
        <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-4 px-5">
          <Logo dark />
          <p className="t-dim text-sm">
            Forge shorts, not excuses. © {new Date().getFullYear()} Reelsmith
          </p>
        </div>
      </footer>
    </div>
  );
}

