"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, type ReactNode } from "react";
import { Logo } from "@/components/shared";
import { PLANS } from "@/lib/constants";
import { useStore } from "@/lib/store";

export default function AppLayout({ children }: { children: ReactNode }) {
  const { ready, user, signOut } = useStore();
  const router = useRouter();

  useEffect(() => {
    if (ready && !user) router.replace("/login");
  }, [ready, user, router]);

  if (!ready || !user) {
    return <div className="bg-ink min-h-screen" />;
  }

  const plan = PLANS.find((p) => p.id === user.plan)!;
  const remaining = plan.videos - user.used;

  return (
    <div className="bg-ink min-h-screen">
      <nav className="b-line border-b">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-3">
          <Link href="/app">
            <Logo dark />
          </Link>
          <div className="flex items-center gap-3">
            <span className="t-dim hidden text-sm sm:block">
              {remaining} videos left · {plan.name}
            </span>
            <Link href="/app/billing" className="btn btn-ghost px-3 py-1.5 text-sm">
              Billing
            </Link>
            <button
              className="btn btn-ghost px-3 py-1.5 text-sm"
              onClick={() => {
                signOut();
                router.push("/");
              }}
            >
              Sign out
            </button>
          </div>
        </div>
      </nav>
      {children}
    </div>
  );
}

