            </div>
            <div>
              <p className="t-dim mb-2 text-xs font-bold uppercase tracking-widest">Length</p>
              <div className="flex gap-2">
                {(
                  [
                    ["short", "~20s"],
                    ["medium", "~35s"],
                    ["long", "~55s"],
