"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import { CaptionLine } from "@/components/shared";
import { TONES, VIDEO_TYPES } from "@/lib/constants";
import { useStore } from "@/lib/store";
import { uid } from "@/lib/timing";
import type { GeneratedScript, VideoLength, VideoType } from "@/lib/types";

async function generateScript(input: {
  type: VideoType;
  topic: string;
  tone: string;
  length: VideoLength;
}): Promise<GeneratedScript> {
  const res = await fetch("/api/script", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  if (!res.ok) throw new Error(`script generation failed (${res.status})`);
  const parsed = (await res.json()) as GeneratedScript;
  if (!parsed.scenes || !parsed.scenes.length) throw new Error("empty script");
  return parsed;
}

function BusyPhone() {
  const [hot, setHot] = useState(0);
  useEffect(() => {
    const iv = setInterval(() => setHot((h) => (h + 1) % 3), 400);
    return () => clearInterval(iv);
  }, []);
  return (
    <div className="phone scene-grad-0 flex w-40 items-end justify-center pb-10">
      <CaptionLine words={["writing", "your", "script…"]} hotIdx={hot} styleCls="cap-pop" size="text-base" />
    </div>
  );
}

export default function CreateWizard() {
  const router = useRouter();
  const { addProject } = useStore();
  const [step, setStep] = useState(0);
  const [type, setType] = useState<VideoType | null>(null);
  const [topic, setTopic] = useState("");
  const [tone, setTone] = useState("Dramatic");
  const [length, setLength] = useState<VideoLength>("medium");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");

  const go = async () => {
    if (!type) return;
    if (topic.trim().length < 3)
      return setErr("Give the topic a few more words to work with.");
    setErr("");
    setBusy(true);
    try {
      const script = await generateScript({ type, topic, tone, length });
      const project = {
        id: uid(),
        type,
        topic,
        tone,
        title: script.title || topic,
        hashtags: script.hashtags || [],
        scenes: script.scenes.map((s) => ({
          id: uid(),
          narration: s.narration,
          visual: s.visual || "",
        })),
        voice: "ash" as const,
        caption: "pop" as const,
        exported: false,
      };
      addProject(project);
      router.push(`/app/studio/${project.id}`);
    } catch {
      setErr("Script generation hit a snag — try again in a moment.");
      setBusy(false);
    }
  };

  return (
    <div className="mx-auto max-w-3xl px-5 py-10">
      <Link href="/app" className="t-dim text-sm">
        ← Back to studio
      </Link>
      {step === 0 && !busy && (
        <div className="rise">
          <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">What are we making?</h1>
          <div className="mt-6 grid gap-4 sm:grid-cols-3">
            {VIDEO_TYPES.map((v) => (
              <button
                key={v.id}
                className={`bg-panel rounded-2xl border p-5 text-left transition ${type === v.id ? "" : "b-line hover:border-yellow-400"}`}
                onClick={() => setType(v.id)}
                style={type === v.id ? { borderColor: "var(--yellow)" } : {}}
              >
                <div className="text-3xl">{v.icon}</div>
                <h3 className="t-inv font-display mt-2 font-bold">{v.name}</h3>
                <p className="t-dim mt-1 text-xs">{v.desc}</p>
              </button>
            ))}
          </div>
          <button
            className="btn btn-yellow mt-8 px-6 py-3"
            disabled={!type}
            style={!type ? { opacity: 0.4, cursor: "not-allowed" } : {}}
            onClick={() => type && setStep(1)}
          >
            Next: the brief
          </button>
        </div>
      )}
      {step === 1 && !busy && (
        <div className="rise">
          <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">Give it the idea</h1>
          <p className="t-dim mt-1">
            One sentence is enough. Claude writes the full scene-by-scene script.
          </p>
          <div className="mt-6 space-y-5">
            <textarea
              className="rs"
              rows={3}
              placeholder={
                type === "ranking"
                  ? "e.g. Top 5 most expensive mistakes in space history"
                  : "e.g. The night a lighthouse keeper vanished without a trace"
              }
              value={topic}
              onChange={(e) => {
                setTopic(e.target.value);
                setErr("");
              }}
              aria-label="Video topic"
            />
            <div>
              <p className="t-dim mb-2 text-xs font-bold uppercase tracking-widest">Tone</p>
              <div className="flex flex-wrap gap-2">
                {TONES.map((t) => (
                  <button
                    key={t}
                    className={`chip px-4 py-1.5 text-sm ${tone === t ? "bg-yellow font-bold" : "t-dim"}`}
                    style={tone === t ? { color: "#1c1730", borderColor: "var(--yellow)" } : {}}
                    onClick={() => setTone(t)}
                  >
                    {t}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <p className="t-dim mb-2 text-xs font-bold uppercase tracking-widest">Length</p>
              <div className="flex gap-2">
                {(
                  [
                    ["short", "~20s"],
                    ["medium", "~35s"],
                    ["long", "~55s"],
                  ] as [VideoLength, string][]
                ).map(([id, label]) => (
                  <button
                    key={id}
                    className={`chip px-4 py-1.5 text-sm ${length === id ? "bg-yellow font-bold" : "t-dim"}`}
                    style={length === id ? { color: "#1c1730", borderColor: "var(--yellow)" } : {}}
                    onClick={() => setLength(id)}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </div>
            {err && <p className="t-coral text-sm">{err}</p>}
            <div className="flex gap-3">
              <button className="btn btn-ghost px-5 py-3" onClick={() => setStep(0)}>
                Back
              </button>
              <button className="btn btn-yellow px-6 py-3" onClick={go}>
                Write my script ✨
              </button>
            </div>
          </div>
        </div>
      )}
      {busy && (
        <div className="mt-16 flex flex-col items-center text-center rise">
