    }
    const ok = nar.play(project.scenes, voice, sel);
    if (!ok) setSpeechOk(false);
  };
  const runExport = () => {
    if (remaining <= 0) return;
    nar.stop();
    setExporting(true);
    setProgress(0);
    const iv = setInterval(() => {
      setProgress((p) => {
        if (p >= 100) {
          clearInterval(iv);
          setExporting(false);
          setDoneOpen(true);
          markExported(project.id);
          return 100;
        }
        return p + Math.random() * 9 + 3;
      });
    }, 180);
  };

  return (
    <div className="mx-auto max-w-6xl px-5 py-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <Link href="/app" className="t-dim text-sm" onClick={() => nar.stop()}>
          ← Studio
        </Link>
        <input
          className="rs font-display max-w-md text-center font-bold"
          value={project.title}
          onChange={(e) => onChange({ ...project, title: e.target.value })}
          aria-label="Video title"
        />
        <button
          className="btn btn-yellow px-5 py-2.5"
          onClick={runExport}
          disabled={exporting}
          style={remaining <= 0 ? { opacity: 0.5 } : {}}
        >
          {remaining <= 0 ? "Plan limit reached" : "Export video"}
        </button>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-5">
        {/* preview column */}
        <div className="lg:col-span-2">
          <div className="mx-auto w-52 sm:w-60">
            <PhonePreview
              scene={scene}
              sceneIndex={activeIdx}
              words={words}
              hotIdx={nar.playing && nar.sceneIdx === activeIdx ? nar.wordIdx : -1}
              captionCls={capCls}
              footer={
                <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center">
                  <button
                    className="btn btn-yellow h-11 w-11 rounded-full text-lg"
                    onClick={togglePlay}
                    aria-label={nar.playing ? "Stop preview" : "Play preview"}
                  >
                    {nar.playing ? "■" : "▶"}
                  </button>
                </div>
              }
            />
          </div>
          {!speechOk && (
            <p className="t-coral mt-3 text-center text-xs">
              Voice preview isn&apos;t available in this browser — captions still preview above.
            </p>
          )}
          <p className="t-dim mt-3 text-center text-xs">
            Scene {activeIdx + 1} of {project.scenes.length} · total {fmtTime(total)}
          </p>

          {/* voice + captions */}
          <div className="bg-panel b-line mt-5 rounded-2xl border p-4">
            <p className="t-dim text-xs font-bold uppercase tracking-widest">Narrator</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {VOICES.map((v) => (
                <button
                  key={v.id}
                  className={`chip p-2.5 text-left ${project.voice === v.id ? "bg-panel2" : ""}`}
                  style={project.voice === v.id ? { borderColor: "var(--yellow)" } : {}}
                  onClick={() => {
                    nar.stop();
                    onChange({ ...project, voice: v.id });
                  }}
                >
                  <span className="t-inv block text-sm font-bold">{v.name}</span>
                  <span className="t-dim text-xs">{v.tag}</span>
                </button>
              ))}
            </div>
            <p className="t-dim mt-3 text-xs font-bold uppercase tracking-widest">Caption style</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {CAPTION_STYLES.map((c) => (
                <button
                  key={c.id}
                  className={`chip scene-grad-2 flex h-16 flex-col items-center justify-center rounded-xl ${project.caption === c.id ? "" : "opacity-80"}`}
                  style={
                    project.caption === c.id
                      ? { borderColor: "var(--yellow)", borderWidth: 2 }
                      : {}
                  }
                  onClick={() => onChange({ ...project, caption: c.id })}
                  aria-label={`Caption style ${c.name}`}
                >
                  <CaptionLine words={c.sample} hotIdx={1} styleCls={c.cls} size="text-xs" />
                  <span className="t-dim mt-1 uppercase tracking-widest" style={{ fontSize: 10 }}>
                    {c.name}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* timeline column */}
        <div className="lg:col-span-3">
          <div className="bg-panel b-line rounded-2xl border p-4">
            <div className="flex items-center justify-between">
              <p className="t-dim text-xs font-bold uppercase tracking-widest">Timeline</p>
              <p className="t-dim text-xs">
                {project.hashtags
                  ?.slice(0, 3)
                  .map((h) => `#${h.replace(/^#/, "")}`)
                  .join("  ")}
              </p>
            </div>
            {/* strip */}
            <div className="scrollbar-thin bg-panel2 relative mt-3 flex gap-1 overflow-x-auto rounded-xl p-2">
              {project.scenes.map((s, i) => {
                const w = Math.max(56, sceneSeconds(s) * 14);
                return (
                  <button
                    key={s.id}
                    onClick={() => {
                      nar.stop();
                      setSel(i);
                    }}
                    className={`scene-grad-${i % 6} relative shrink-0 rounded-lg border-2 p-1 text-left`}
                    style={{
                      width: w,
                      height: 64,
                      borderColor: i === activeIdx ? "var(--yellow)" : "transparent",
                    }}
                    aria-label={`Scene ${i + 1}`}
                  >
                    <span className="cap-pop absolute left-1 top-1" style={{ fontSize: 10 }}>
                      {i + 1}
                    </span>
                    <span
                      className="t-inv absolute bottom-1 left-1 right-1 truncate opacity-80"
                      style={{ fontSize: 10 }}
                    >
                      {s.narration}
                    </span>
                  </button>
                );
              })}
            </div>
            {/* scene inspector */}
            <div className="mt-4">
              <div className="flex items-center justify-between">
                <p className="t-inv font-display font-bold">
                  Scene {sel + 1}
                  {sel === 0 ? " · Hook" : ""}{" "}
                  <span className="t-dim text-xs font-normal">
                    ({sceneSeconds(project.scenes[sel])}s)
                  </span>
                </p>
                <div className="flex gap-1.5">
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, -1)}
                    aria-label="Move scene earlier"
                  >
                    ←
                  </button>
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, 1)}
                    aria-label="Move scene later"
                  >
                    →
                  </button>
                  <button
                    className="btn btn-ghost t-coral px-2.5 py-1 text-xs"
                    onClick={() => removeScene(sel)}
                    aria-label="Delete scene"
                  >
                    Delete
                  </button>
                </div>
              </div>
              <textarea
                className="rs mt-2"
                rows={3}
                value={project.scenes[sel].narration}
                onChange={(e) => setScene(sel, { narration: e.target.value })}
                aria-label="Scene narration"
              />
              <input
                className="rs mt-2 text-sm"
                value={project.scenes[sel].visual}
                placeholder="B-roll / visual idea for this scene"
                onChange={(e) => setScene(sel, { visual: e.target.value })}
                aria-label="Scene visual idea"
              />
              <button
                className="btn btn-ghost mt-3 px-4 py-2 text-sm"
                onClick={() => {
                  const sc = [...project.scenes];
                  sc.splice(sel + 1, 0, {
                    id: uid(),
                    narration: "New scene — write the beat here.",
                    visual: "",
                  });
                  onChange({ ...project, scenes: sc });
                  setSel(sel + 1);
                }}
              >
                + Add scene after
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* export overlay */}
      {(exporting || doneOpen) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-5">
          <div className="bg-panel b-line w-full max-w-md rounded-2xl border p-7 text-center rise">
            {exporting ? (
              <>
                <p className="font-display t-inv text-xl font-extrabold">Rendering your short</p>
                <p className="t-dim mt-1 text-sm">
                  Mixing voiceover, timing captions, cutting scenes…
                </p>
                <div className="bg-panel2 mt-5 h-3 overflow-hidden rounded-full">
                  <div
                    className="bg-yellow h-full rounded-full"
                    style={{ width: `${Math.min(100, progress)}%`, transition: "width .18s linear" }}
                  ></div>
                </div>
                <p className="t-yellow font-display mt-2 font-bold">
                  {Math.min(100, Math.floor(progress))}%
                </p>
              </>
            ) : (
              <>
                <div className="text-4xl">✅</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Export complete</p>
                <p className="t-dim mt-1 text-sm">
                  This demo build exports your production package — script and word-timed captions
                  ready for any editor or scheduler. (Hook up an FFmpeg render worker for MP4s.)
                </p>
                <div className="mt-5 grid gap-2">
                  <button
                    className="btn btn-yellow py-2.5"
                    onClick={() => download(`${slugify(project.title)}.srt`, toSRT(project))}
                  >
                    Download captions (.srt)
                  </button>
                  <button
                    className="btn btn-ghost py-2.5"
                    onClick={() =>
                      download(`${slugify(project.title)}-script.txt`, scriptText(project))
                    }
                  >
                    Download script (.txt)
                  </button>
                  <button className="btn btn-ghost py-2.5" onClick={() => setDoneOpen(false)}>
                    Back to editor
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

