export default function BillingPage() {
  const { user, changePlan } = useStore();
  if (!user) return null;
  const current = PLANS.find((p) => p.id === user.plan)!;

  return (
    <div className="mx-auto max-w-5xl px-5 py-10">
      <Link href="/app" className="t-dim text-sm">
        ← Back to studio
      </Link>
      <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">Plan &amp; billing</h1>
      <p className="t-dim mt-1">
        You&apos;re on <span className="t-yellow font-bold">{current.name}</span> · {user.used}{" "}
        videos used this month. Switch plans any time — changes apply instantly in this demo.
      </p>
      <div className="mt-8 grid gap-4 md:grid-cols-3">
        {PLANS.map((p) => (
          <div
            key={p.id}
            className={`bg-panel rounded-2xl border p-6 ${user.plan === p.id ? "" : "b-line"}`}
            style={user.plan === p.id ? { borderColor: "var(--yellow)" } : {}}
          >
            <h3 className="font-display t-inv text-xl font-extrabold">{p.name}</h3>
            <p className="t-yellow font-display mt-2 text-3xl font-extrabold">
              ${p.price}
              <span className="t-dim text-sm">/mo</span>
            </p>
            <p className="t-dim mt-1 text-sm">{p.videos} videos / month</p>
            <button
              className={`btn mt-5 w-full py-2.5 ${user.plan === p.id ? "btn-ghost" : "btn-yellow"}`}
              onClick={() => changePlan(p.id)}
              disabled={user.plan === p.id}
            >
              {user.plan === p.id ? "Current plan" : "Switch to " + p.name}
            </button>
          </div>
        ))}
      </div>
      <p className="t-dim mt-6 text-xs">
        Production note: these buttons will move to Stripe Checkout + a customer portal (roadmap
        step 5).
      </p>
    </div>
  );
}

