"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import type { Project, User } from "./types";

/* Mock auth + in-browser persistence. This is the prototype's in-session
   store, upgraded to survive reloads via localStorage. Roadmap steps 2–3
   replace it with Postgres + Auth.js. */

const LS_KEY = "reelsmith.v1";

interface StoreState {
  ready: boolean;
  user: User | null;
  projects: Project[];
  signIn: (u: { name: string; email: string }) => void;
  signOut: () => void;
  addProject: (p: Project) => void;
  updateProject: (p: Project) => void;
  markExported: (id: string) => void;
  changePlan: (plan: User["plan"]) => void;
}

const StoreContext = createContext<StoreState | null>(null);

export function StoreProvider({ children }: { children: ReactNode }) {
  const [ready, setReady] = useState(false);
  const [user, setUser] = useState<User | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);

  useEffect(() => {
    try {
      const raw = localStorage.getItem(LS_KEY);
      if (raw) {
        const saved = JSON.parse(raw) as { user: User | null; projects: Project[] };
        setUser(saved.user ?? null);
        setProjects(saved.projects ?? []);
      }
    } catch {
      /* corrupt storage — start fresh */
    }
    setReady(true);
  }, []);

  useEffect(() => {
    if (!ready) return;
    try {
      localStorage.setItem(LS_KEY, JSON.stringify({ user, projects }));
    } catch {
      /* storage full or unavailable — session-only mode */
    }
  }, [ready, user, projects]);

  const signIn = useCallback((u: { name: string; email: string }) => {
    setUser({ ...u, plan: "starter", used: 0 });
  }, []);

  const signOut = useCallback(() => {
    setUser(null);
    setProjects([]);
  }, []);

  const addProject = useCallback((p: Project) => {
    setProjects((ps) => [p, ...ps]);
  }, []);

  const updateProject = useCallback((p: Project) => {
    setProjects((ps) => ps.map((x) => (x.id === p.id ? p : x)));
  }, []);

  const markExported = useCallback((id: string) => {
    setProjects((ps) => ps.map((p) => (p.id === id ? { ...p, exported: true } : p)));
    setUser((u) => (u ? { ...u, used: u.used + 1 } : u));
  }, []);

  const changePlan = useCallback((plan: User["plan"]) => {
    setUser((u) => (u ? { ...u, plan } : u));
  }, []);

  return (
    <StoreContext.Provider
      value={{
        ready,
        user,
        projects,
        signIn,
        signOut,
        addProject,
        updateProject,
        markExported,
        changePlan,
      }}
    >
      {children}
    </StoreContext.Provider>
  );
}

export function useStore(): StoreState {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("useStore must be used within StoreProvider");
  return ctx;
}

