import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { toClientProject } from "@/lib/serialize";
import type { Project } from "@/lib/types";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const projects = await db.project.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
  });
  return NextResponse.json({ projects: projects.map(toClientProject) });
}

export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: Omit<Project, "id" | "exported">;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  if (!body.title || !Array.isArray(body.scenes) || body.scenes.length === 0) {
    return NextResponse.json({ error: "invalid project" }, { status: 400 });
  }

  const project = await db.project.create({
    data: {
      userId: user.id,
      type: body.type,
      topic: body.topic ?? "",
      tone: body.tone ?? "",
      title: body.title,
      hashtags: body.hashtags ?? [],
      scenes: body.scenes,
      voice: body.voice ?? "ash",
      caption: body.caption ?? "pop",
    },
  });
  return NextResponse.json({ project: toClientProject(project) });
}

