      userId: user.id,
      type: body.type,
      topic: body.topic ?? "",
      tone: body.tone ?? "",
      title: body.title,
      hashtags: body.hashtags ?? [],
      scenes: body.scenes,
      voice: body.voice ?? "ash",
      caption: body.caption ?? "pop",
    },
  });
