import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { usageFor } from "@/lib/usage";
import { toClientExport } from "@/lib/serialize";

/** Enqueue a render. The worker container picks up queued Export rows. */
export async function POST(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;

  const project = await db.project.findUnique({ where: { id } });
  if (!project || project.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const { used, limit } = await usageFor(user);
  if (used >= limit) {
    return NextResponse.json(
      { error: `Plan limit reached (${limit} videos this month). Upgrade to keep rendering.` },
      { status: 403 },
    );
  }

  const running = await db.export.findFirst({
    where: { projectId: id, status: { in: ["queued", "processing"] } },
  });
  if (running) return NextResponse.json({ export: toClientExport(running) });

  const exp = await db.export.create({
    data: { projectId: id, userId: user.id },
  });
  return NextResponse.json({ export: toClientExport(exp) });
}

