import { createReadStream, statSync } from "fs";
import path from "path";
import { Readable } from "stream";
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { slugify } from "@/lib/timing";

const DATA_DIR = process.env.RENDER_DATA_DIR || "/data";

/** Streams a rendered artifact (video/SRT) from the shared render volume. */
export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;

  const exp = await db.export.findUnique({
    where: { id },
    include: { project: { select: { title: true } } },
  });
  if (!exp || exp.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const kind = new URL(request.url).searchParams.get("type") || "video";
  const rel = kind === "srt" ? exp.srtPath : exp.videoPath;
  if (!rel) return NextResponse.json({ error: "file not ready" }, { status: 404 });

  // Paths are worker-written, but resolve inside DATA_DIR defensively.
  const abs = path.resolve(DATA_DIR, rel);
  if (!abs.startsWith(path.resolve(DATA_DIR) + path.sep)) {
    return NextResponse.json({ error: "invalid path" }, { status: 400 });
  }

  let size: number;
  try {
    size = statSync(abs).size;
  } catch {
    return NextResponse.json({ error: "file missing" }, { status: 404 });
  }

  const base = slugify(exp.project.title) || "reelsmith-export";
  const filename = kind === "srt" ? `${base}.srt` : `${base}.mp4`;
  const contentType = kind === "srt" ? "text/plain; charset=utf-8" : "video/mp4";

  const stream = Readable.toWeb(createReadStream(abs)) as ReadableStream;
  return new NextResponse(stream, {
    headers: {
      "Content-Type": contentType,
      "Content-Length": String(size),
      "Content-Disposition": `attachment; filename="${filename}"`,
    },
  });
}

