import Anthropic from "@anthropic-ai/sdk";
import { NextResponse } from "next/server";
import type { GeneratedScript, VideoLength, VideoType } from "@/lib/types";

/* Roadmap step 4 (pulled forward from the prototype's client-side fetch):
   the Anthropic key lives server-side only. When ANTHROPIC_API_KEY is not
   set, a deterministic mock script keeps local dev fully usable. */

export const runtime = "nodejs";

// Model from the prototype's generateScript; override via env if needed.
const MODEL = process.env.REELSMITH_SCRIPT_MODEL || "claude-sonnet-4-6";

const TYPE_BRIEFS: Record<VideoType, string> = {
  story: "a narrated story video with a strong hook, rising tension, and a payoff ending",
  ranking:
    "a top-5 countdown ranking video: the hook teases the list, then scenes count down #5 to #1, each scene covering one ranked item (name the rank in the narration)",
  facts: "a rapid-fire facts / explainer video where each scene delivers one surprising fact or step",
};

interface ScriptRequest {
  type: VideoType;
  topic: string;
  tone: string;
  length: VideoLength;
}

function sceneCountFor(type: VideoType, length: VideoLength): number {
  return type === "ranking" ? 6 : length === "short" ? 4 : length === "long" ? 8 : 6;
}

function mockScript(req: ScriptRequest): GeneratedScript {
  const n = sceneCountFor(req.type, req.length);
  return {
    title: `${req.topic} (${req.tone.toLowerCase()} cut)`,
    scenes: Array.from({ length: n }, (_, i) => ({
      narration:
        i === 0
          ? `You won't believe what's behind "${req.topic}". Stay for the ending.`
          : `Beat ${i + 1} of the ${req.tone.toLowerCase()} take on ${req.topic}, keeping the tension moving toward the payoff.`,
      visual: i === 0 ? "Fast zoom on bold title card" : `B-roll idea for beat ${i + 1}`,
    })),
    hashtags: ["reelsmith", "shorts", req.type],
  };
}

export async function POST(request: Request) {
  let body: ScriptRequest;
  try {
    body = (await request.json()) as ScriptRequest;
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }

  const { type, topic, tone, length } = body;
  if (!type || !TYPE_BRIEFS[type] || typeof topic !== "string" || topic.trim().length < 3) {
    return NextResponse.json({ error: "invalid request" }, { status: 400 });
  }

  if (!process.env.ANTHROPIC_API_KEY) {
    return NextResponse.json(mockScript(body));
  }

  const sceneCount = sceneCountFor(type, length);
  const prompt = `You are a short-form video scriptwriter for TikTok, Reels, and YouTube Shorts.
Write ${TYPE_BRIEFS[type]}. Topic: "${topic}". Tone: ${tone}. Exactly ${sceneCount} scenes; scene 1 is the hook.
Each scene's narration is 1-3 punchy spoken sentences (max ~30 words). Also give each scene a short b-roll visual idea.
Respond ONLY with valid JSON, no markdown fences, no preamble, exactly:
{"title":"...","scenes":[{"narration":"...","visual":"..."}],"hashtags":["...","...","..."]}`;

  try {
    const client = new Anthropic();
    const response = await client.messages.create({
      model: MODEL,
      max_tokens: 1500,
      messages: [{ role: "user", content: prompt }],
    });
    const text = response.content
      .map((b) => (b.type === "text" ? b.text : ""))
      .join("")
      .replace(/```json|```/g, "")
      .trim();
    const parsed = JSON.parse(text) as GeneratedScript;
    if (!parsed.scenes || !parsed.scenes.length) throw new Error("empty script");
    return NextResponse.json(parsed);
  } catch (err) {
    console.error("script generation failed:", err);
    return NextResponse.json({ error: "script generation failed" }, { status: 502 });
  }
}

