"use client";

import type { ClientExport } from "./serialize";
import type { Project } from "./types";

/* Thin client for the project/export APIs. */

async function req<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    ...init,
    headers: init?.body ? { "Content-Type": "application/json" } : undefined,
    cache: "no-store",
  });
  if (!res.ok) {
    let msg = `Request failed (${res.status})`;
    try {
      const data = (await res.json()) as { error?: string };
      if (data.error) msg = data.error;
    } catch {
      /* non-JSON error */
    }
    throw new Error(msg);
  }
  return res.json() as Promise<T>;
}

export const api = {
  listProjects: () => req<{ projects: Project[] }>("/api/projects"),
  getProject: (id: string) => req<{ project: Project }>(`/api/projects/${id}`),
  createProject: (p: Omit<Project, "id" | "exported">) =>
    req<{ project: Project }>("/api/projects", { method: "POST", body: JSON.stringify(p) }),
  updateProject: (id: string, patch: Partial<Project>) =>
    req<{ project: Project }>(`/api/projects/${id}`, {
      method: "PUT",
      body: JSON.stringify(patch),
    }),
  deleteProject: (id: string) => req<{ ok: true }>(`/api/projects/${id}`, { method: "DELETE" }),
  startExport: (projectId: string) =>
    req<{ export: ClientExport }>(`/api/projects/${projectId}/export`, { method: "POST" }),
  getExport: (id: string) => req<{ export: ClientExport }>(`/api/exports/${id}`),
};

