"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { Suspense, useState } from "react";
import { Logo } from "@/components/shared";
import { useStore } from "@/lib/store";

function AuthForm() {
  const router = useRouter();
  const params = useSearchParams();
  const { signIn } = useStore();
  const [mode, setMode] = useState<"signin" | "signup">(
    params.get("mode") === "signup" ? "signup" : "signin",
  );
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [pw, setPw] = useState("");
  const [err, setErr] = useState("");
  const signup = mode === "signup";

  const submit = () => {
    if (!email.includes("@")) return setErr("Enter a valid email address.");
    if (pw.length < 6) return setErr("Password needs at least 6 characters.");
    if (signup && !name.trim())
      return setErr("Add a display name so we know what to call you.");
    signIn({ name: signup ? name.trim() : email.split("@")[0], email });
    router.push("/app");
  };

  return (
    <div className="bg-ink flex min-h-screen items-center justify-center px-5">
      <div className="bg-panel b-line w-full max-w-md rounded-2xl border p-8 rise">
        <Logo dark />
        <h1 className="font-display t-inv mt-6 text-2xl font-extrabold">
          {signup ? "Create your studio" : "Welcome back"}
        </h1>
        <p className="t-dim mt-1 text-sm">
          {signup ? "Free to start — your first videos are on us." : "Sign in to keep forging."}
        </p>
        <div className="mt-6 space-y-3">
          {signup && (
            <input
              className="rs"
              placeholder="Display name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              aria-label="Display name"
            />
          )}
          <input
            className="rs"
            placeholder="Email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            aria-label="Email"
          />
          <input
            className="rs"
            placeholder="Password"
            type="password"
            value={pw}
            onChange={(e) => {
              setPw(e.target.value);
              setErr("");
            }}
            aria-label="Password"
          />
          {err && <p className="t-coral text-sm">{err}</p>}
          <button className="btn btn-yellow w-full py-3" onClick={submit}>
            {signup ? "Create account" : "Sign in"}
          </button>
        </div>
        <p className="t-dim mt-5 text-sm">
          {signup ? "Already have an account? " : "New here? "}
          <button
            className="t-yellow font-semibold"
            onClick={() => setMode(signup ? "signin" : "signup")}
          >
            {signup ? "Sign in" : "Start free"}
          </button>
          <span className="mx-2">·</span>
          <Link href="/" className="underline">
            Back to site
          </Link>
        </p>
        <p className="t-dim mt-3 text-xs">
          Demo build: accounts live in this browser only. Real auth lands with Auth.js.
        </p>
      </div>
    </div>
  );
}

export default function LoginPage() {
  return (
    <Suspense>
      <AuthForm />
    </Suspense>
  );
}

