"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { PLANS, VIDEO_TYPES } from "@/lib/constants";
import { useStore, type Usage } from "@/lib/store";
import { fmtTime, projSeconds } from "@/lib/timing";
import type { Project } from "@/lib/types";

function UsageMeter({ planId, usage }: { planId: string; usage: Usage }) {
  const plan = PLANS.find((p) => p.id === planId) ?? PLANS[0];
  const pct = usage.limit ? Math.min(100, Math.round((usage.used / usage.limit) * 100)) : 0;
  return (
    <div className="bg-panel b-line rounded-2xl border p-5">
      <div className="flex items-center justify-between">
        <p className="t-dim text-xs font-bold uppercase tracking-widest">{plan.name} plan</p>
        <p className="t-inv text-sm font-semibold">
          {usage.used} / {usage.limit} videos
        </p>
      </div>
      <div className="bg-panel2 mt-3 h-2 overflow-hidden rounded-full">
        <div
          className="bg-yellow h-full rounded-full"
          style={{ width: `${pct}%`, transition: "width .4s ease" }}
        ></div>
      </div>
      <p className="t-dim mt-2 text-xs">
        Resets on the 1st. Rendered exports count toward your monthly total.
      </p>
    </div>
  );
}

export default function Dashboard() {
  const { user, usage } = useStore();
  const [projects, setProjects] = useState<Project[] | null>(null);
  const [loadErr, setLoadErr] = useState("");

  useEffect(() => {
    if (!user) return;
    api
      .listProjects()
      .then((d) => setProjects(d.projects))
      .catch((e: Error) => setLoadErr(e.message));
  }, [user]);

  if (!user) return null;

  return (
    <div className="mx-auto max-w-6xl px-5 py-8">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="font-display t-inv text-3xl font-extrabold">Your studio</h1>
          <p className="t-dim mt-1">Hey {user.name} — what are we forging today?</p>
        </div>
        <Link href="/app/new" className="btn btn-yellow px-5 py-3">
          + New video
        </Link>
      </div>
      <div className="mt-6 grid gap-4 md:grid-cols-3">
        <div className="md:col-span-2">
          {loadErr ? (
            <div className="bg-panel b-line rounded-2xl border p-8 text-center">
              <p className="t-coral text-sm">{loadErr}</p>
            </div>
          ) : projects === null ? (
            <div
              className="bg-panel b-line flex items-center justify-center rounded-2xl border p-8"
              style={{ minHeight: "16rem" }}
            >
              <p className="t-dim text-sm">Loading your videos…</p>
            </div>
          ) : projects.length === 0 ? (
            <div
              className="bg-panel b-line flex flex-col items-center justify-center rounded-2xl border p-8 text-center"
              style={{ minHeight: "16rem" }}
            >
              <div className="text-4xl">🎬</div>
              <h2 className="font-display t-inv mt-3 text-xl font-bold">No videos yet</h2>
              <p className="t-dim mt-1 max-w-sm text-sm">
                Start with one sentence — a story, a top-5, or a fact you can&apos;t stop thinking
                about. Reelsmith does the rest.
              </p>
              <Link href="/app/new" className="btn btn-primary mt-5 px-5 py-2.5">
                Create your first video
              </Link>
            </div>
          ) : (
            <div className="grid gap-3 sm:grid-cols-2">
              {projects.map((p) => (
                <Link
                  key={p.id}
                  href={`/app/studio/${p.id}`}
                  className="bg-panel b-line rounded-2xl border p-5 text-left transition hover:border-yellow-400"
                >
                  <div className="flex items-center justify-between">
                    <span className="text-2xl">
                      {VIDEO_TYPES.find((t) => t.id === p.type)?.icon}
                    </span>
                    <span
                      className={`rounded-full px-2.5 py-1 text-xs font-bold ${p.exported ? "bg-yellow" : "bg-panel2 t-dim"}`}
                      style={p.exported ? { color: "#1c1730" } : {}}
                    >
                      {p.exported ? "Exported" : "Draft"}
                    </span>
                  </div>
                  <h3 className="t-inv font-display mt-3 font-bold leading-snug">{p.title}</h3>
                  <p className="t-dim mt-1 text-xs">
                    {p.scenes.length} scenes · {fmtTime(projSeconds(p))} · {p.tone}
                  </p>
                </Link>
              ))}
            </div>
          )}
        </div>
        <div className="space-y-4">
          <UsageMeter planId={user.plan} usage={usage} />
          <div className="bg-panel b-line rounded-2xl border p-5">
            <p className="t-dim text-xs font-bold uppercase tracking-widest">Billing</p>
            <p className="t-inv mt-2 text-sm">Need more videos or another workspace?</p>
            <Link href="/app/billing" className="btn btn-ghost mt-3 w-full py-2 text-sm">
              Manage plan
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

