"use client";

import Link from "next/link";
import { use, useCallback, useEffect, useRef, useState } from "react";
import { CaptionLine, PhonePreview } from "@/components/shared";
import { api } from "@/lib/api";
import { CAPTION_STYLES, VOICES } from "@/lib/constants";
import type { ClientExport } from "@/lib/serialize";
import { useStore } from "@/lib/store";
import { useNarrator } from "@/lib/useNarrator";
import {
  download,
  fmtTime,
  projSeconds,
  sceneSeconds,
  scriptText,
  slugify,
  uid,
  wordsOf,
} from "@/lib/timing";
import type { Project, Scene } from "@/lib/types";

export default function StudioPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const { ready, user } = useStore();
  const [project, setProject] = useState<Project | null>(null);
  const [missing, setMissing] = useState(false);

  useEffect(() => {
    if (!ready || !user) return;
    api
      .getProject(id)
      .then((d) => setProject(d.project))
      .catch(() => setMissing(true));
  }, [ready, user, id]);

  if (!ready || !user) return null;
  if (missing) {
    return (
      <div className="mx-auto max-w-3xl px-5 py-16 text-center">
        <p className="t-inv font-display text-xl font-bold">That video isn&apos;t here anymore.</p>
        <Link href="/app" className="btn btn-yellow mt-6 px-5 py-2.5">
          Back to studio
        </Link>
      </div>
    );
  }
  if (!project) {
    return (
      <div className="mx-auto max-w-3xl px-5 py-16 text-center">
        <p className="t-dim text-sm">Loading project…</p>
      </div>
    );
  }
  return <Studio project={project} setProject={setProject} />;
}

function Studio({
  project,
  setProject,
}: {
  project: Project;
  setProject: (p: Project) => void;
}) {
  const { usage, refresh } = useStore();
  const nar = useNarrator();
  const [sel, setSel] = useState(0);
  const [exp, setExp] = useState<ClientExport | null>(null);
  const [exportOpen, setExportOpen] = useState(false);
  const [exportErr, setExportErr] = useState("");
  const [speechOk, setSpeechOk] = useState(true);
  const [saveState, setSaveState] = useState<"saved" | "saving" | "error">("saved");

  const remaining = Math.max(0, usage.limit - usage.used);

  /* --- debounced autosave -------------------------------------- */
  const saveTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const skipFirst = useRef(true);
  useEffect(() => {
    if (skipFirst.current) {
      skipFirst.current = false;
      return;
    }
    setSaveState("saving");
    if (saveTimer.current) clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(() => {
      api
        .updateProject(project.id, {
          title: project.title,
          scenes: project.scenes,
          voice: project.voice,
          caption: project.caption,
        })
        .then(() => setSaveState("saved"))
        .catch(() => setSaveState("error"));
    }, 800);
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current);
    };
  }, [project]);

  /* --- export polling ------------------------------------------ */
  const pollExport = useCallback(
    (id: string) => {
      const iv = setInterval(async () => {
        try {
          const { export: e } = await api.getExport(id);
          setExp(e);
          if (e.status === "done" || e.status === "error") {
            clearInterval(iv);
            if (e.status === "done") {
              setProject({ ...project, exported: true });
              void refresh();
            }
          }
        } catch {
          clearInterval(iv);
        }
      }, 1500);
      return iv;
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [project.id, refresh],
  );

  const runExport = async () => {
    if (remaining <= 0) return;
    nar.stop();
    setExportErr("");
    setExportOpen(true);
    try {
      const { export: e } = await api.startExport(project.id);
      setExp(e);
      if (e.status !== "done" && e.status !== "error") pollExport(e.id);
    } catch (err) {
      setExportErr(err instanceof Error ? err.message : "Export failed to start.");
    }
  };

  const onChange = setProject;
  const voice = VOICES.find((v) => v.id === project.voice) ?? VOICES[0];
  const capCls = (CAPTION_STYLES.find((c) => c.id === project.caption) ?? CAPTION_STYLES[0]).cls;
  const activeIdx = nar.playing ? nar.sceneIdx : sel;
  const scene: Scene | undefined = project.scenes[activeIdx] || project.scenes[0];
  const words = wordsOf(scene?.narration || "");
  const total = projSeconds(project);
  const rendering = exp && (exp.status === "queued" || exp.status === "processing");

  const setScene = (i: number, patch: Partial<Scene>) =>
    onChange({
      ...project,
      scenes: project.scenes.map((s, idx) => (idx === i ? { ...s, ...patch } : s)),
    });
  const move = (i: number, dir: number) => {
    const j = i + dir;
    if (j < 0 || j >= project.scenes.length) return;
    const sc = [...project.scenes];
    [sc[i], sc[j]] = [sc[j], sc[i]];
    onChange({ ...project, scenes: sc });
    setSel(j);
  };
  const removeScene = (i: number) => {
    if (project.scenes.length <= 2) return;
    onChange({ ...project, scenes: project.scenes.filter((_, idx) => idx !== i) });
    setSel(Math.max(0, i - 1));
  };
  const togglePlay = () => {
    if (nar.playing) {
      nar.stop();
      return;
    }
    const ok = nar.play(project.scenes, voice, sel);
    if (!ok) setSpeechOk(false);
  };

  return (
    <div className="mx-auto max-w-6xl px-5 py-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <Link href="/app" className="t-dim text-sm" onClick={() => nar.stop()}>
            ← Studio
          </Link>
          <span className="t-dim text-xs">
            {saveState === "saving" ? "Saving…" : saveState === "error" ? (
              <span className="t-coral">Save failed — edits kept locally</span>
            ) : (
              "Saved"
            )}
          </span>
        </div>
        <input
          className="rs font-display max-w-md text-center font-bold"
          value={project.title}
          onChange={(e) => onChange({ ...project, title: e.target.value })}
          aria-label="Video title"
        />
        <button
          className="btn btn-yellow px-5 py-2.5"
          onClick={runExport}
          disabled={!!rendering}
          style={remaining <= 0 ? { opacity: 0.5 } : {}}
        >
          {remaining <= 0 ? "Plan limit reached" : rendering ? "Rendering…" : "Export video"}
        </button>
      </div>

      <div className="mt-6 grid gap-6 lg:grid-cols-5">
        {/* preview column */}
        <div className="lg:col-span-2">
          <div className="mx-auto w-52 sm:w-60">
            <PhonePreview
              scene={scene}
              sceneIndex={activeIdx}
              words={words}
              hotIdx={nar.playing && nar.sceneIdx === activeIdx ? nar.wordIdx : -1}
              captionCls={capCls}
              footer={
                <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center">
                  <button
                    className="btn btn-yellow h-11 w-11 rounded-full text-lg"
                    onClick={togglePlay}
                    aria-label={nar.playing ? "Stop preview" : "Play preview"}
                  >
                    {nar.playing ? "■" : "▶"}
                  </button>
                </div>
              }
            />
          </div>
          {!speechOk && (
            <p className="t-coral mt-3 text-center text-xs">
              Voice preview isn&apos;t available in this browser — captions still preview above.
            </p>
          )}
          <p className="t-dim mt-3 text-center text-xs">
            Scene {activeIdx + 1} of {project.scenes.length} · total {fmtTime(total)}
          </p>

          {/* voice + captions */}
          <div className="bg-panel b-line mt-5 rounded-2xl border p-4">
            <p className="t-dim text-xs font-bold uppercase tracking-widest">Narrator</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {VOICES.map((v) => (
                <button
                  key={v.id}
                  className={`chip p-2.5 text-left ${project.voice === v.id ? "bg-panel2" : ""}`}
                  style={project.voice === v.id ? { borderColor: "var(--yellow)" } : {}}
                  onClick={() => {
                    nar.stop();
                    onChange({ ...project, voice: v.id });
                  }}
                >
                  <span className="t-inv block text-sm font-bold">{v.name}</span>
                  <span className="t-dim text-xs">{v.tag}</span>
                </button>
              ))}
            </div>
            <p className="t-dim mt-3 text-xs font-bold uppercase tracking-widest">Caption style</p>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {CAPTION_STYLES.map((c) => (
                <button
                  key={c.id}
                  className={`chip scene-grad-2 flex h-16 flex-col items-center justify-center rounded-xl ${project.caption === c.id ? "" : "opacity-80"}`}
                  style={
                    project.caption === c.id
                      ? { borderColor: "var(--yellow)", borderWidth: 2 }
                      : {}
                  }
                  onClick={() => onChange({ ...project, caption: c.id })}
                  aria-label={`Caption style ${c.name}`}
                >
                  <CaptionLine words={c.sample} hotIdx={1} styleCls={c.cls} size="text-xs" />
                  <span className="t-dim mt-1 uppercase tracking-widest" style={{ fontSize: 10 }}>
                    {c.name}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* timeline column */}
        <div className="lg:col-span-3">
          <div className="bg-panel b-line rounded-2xl border p-4">
            <div className="flex items-center justify-between">
              <p className="t-dim text-xs font-bold uppercase tracking-widest">Timeline</p>
              <p className="t-dim text-xs">
                {project.hashtags
                  ?.slice(0, 3)
                  .map((h) => `#${h.replace(/^#/, "")}`)
                  .join("  ")}
              </p>
            </div>
            {/* strip */}
            <div className="scrollbar-thin bg-panel2 relative mt-3 flex gap-1 overflow-x-auto rounded-xl p-2">
              {project.scenes.map((s, i) => {
                const w = Math.max(56, sceneSeconds(s) * 14);
                return (
                  <button
                    key={s.id}
                    onClick={() => {
                      nar.stop();
                      setSel(i);
                    }}
                    className={`scene-grad-${i % 6} relative shrink-0 rounded-lg border-2 p-1 text-left`}
                    style={{
                      width: w,
                      height: 64,
                      borderColor: i === activeIdx ? "var(--yellow)" : "transparent",
                    }}
                    aria-label={`Scene ${i + 1}`}
                  >
                    <span className="cap-pop absolute left-1 top-1" style={{ fontSize: 10 }}>
                      {i + 1}
                    </span>
                    <span
                      className="t-inv absolute bottom-1 left-1 right-1 truncate opacity-80"
                      style={{ fontSize: 10 }}
                    >
                      {s.narration}
                    </span>
                  </button>
                );
              })}
            </div>
            {/* scene inspector */}
            <div className="mt-4">
              <div className="flex items-center justify-between">
                <p className="t-inv font-display font-bold">
                  Scene {sel + 1}
                  {sel === 0 ? " · Hook" : ""}{" "}
                  <span className="t-dim text-xs font-normal">
                    ({sceneSeconds(project.scenes[sel])}s)
                  </span>
                </p>
                <div className="flex gap-1.5">
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, -1)}
                    aria-label="Move scene earlier"
                  >
                    ←
                  </button>
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, 1)}
                    aria-label="Move scene later"
                  >
                    →
                  </button>
                  <button
                    className="btn btn-ghost t-coral px-2.5 py-1 text-xs"
                    onClick={() => removeScene(sel)}
                    aria-label="Delete scene"
                  >
                    Delete
                  </button>
                </div>
              </div>
              <textarea
                className="rs mt-2"
                rows={3}
                value={project.scenes[sel].narration}
                onChange={(e) => setScene(sel, { narration: e.target.value })}
                aria-label="Scene narration"
              />
              <input
                className="rs mt-2 text-sm"
                value={project.scenes[sel].visual}
                placeholder="B-roll / visual idea for this scene"
                onChange={(e) => setScene(sel, { visual: e.target.value })}
                aria-label="Scene visual idea"
              />
              <button
                className="btn btn-ghost mt-3 px-4 py-2 text-sm"
                onClick={() => {
                  const sc = [...project.scenes];
                  sc.splice(sel + 1, 0, {
                    id: uid(),
                    narration: "New scene — write the beat here.",
                    visual: "",
                  });
                  onChange({ ...project, scenes: sc });
                  setSel(sel + 1);
                }}
              >
                + Add scene after
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* export overlay */}
      {exportOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-5">
          <div className="bg-panel b-line w-full max-w-md rounded-2xl border p-7 text-center rise">
            {exportErr ? (
              <>
                <div className="text-4xl">⚠️</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">
                  Couldn&apos;t start the render
                </p>
                <p className="t-coral mt-2 text-sm">{exportErr}</p>
                <button
                  className="btn btn-ghost mt-5 w-full py-2.5"
                  onClick={() => setExportOpen(false)}
                >
                  Back to editor
                </button>
              </>
            ) : !exp || exp.status === "queued" || exp.status === "processing" ? (
              <>
                <p className="font-display t-inv text-xl font-extrabold">Rendering your short</p>
                <p className="t-dim mt-1 text-sm">
                  {exp?.step || "Queued — a render slot opens in a moment…"}
                </p>
                <div className="bg-panel2 mt-5 h-3 overflow-hidden rounded-full">
                  <div
                    className="bg-yellow h-full rounded-full"
                    style={{
                      width: `${Math.min(100, exp?.progress ?? 0)}%`,
                      transition: "width .5s ease",
                    }}
                  ></div>
                </div>
                <p className="t-yellow font-display mt-2 font-bold">
                  {Math.min(100, exp?.progress ?? 0)}%
                </p>
                <p className="t-dim mt-3 text-xs">
                  Real voiceover and captions take a minute or two. You can keep editing — the
                  render uses the version you exported.
                </p>
                <button
                  className="btn btn-ghost mt-4 w-full py-2"
                  onClick={() => setExportOpen(false)}
                >
                  Hide (keeps rendering)
                </button>
              </>
            ) : exp.status === "error" ? (
              <>
                <div className="text-4xl">⚠️</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Render failed</p>
                <p className="t-coral mt-2 text-sm">{exp.error || "Unknown render error."}</p>
                <button
                  className="btn btn-yellow mt-5 w-full py-2.5"
                  onClick={() => {
                    setExp(null);
                    void runExport();
                  }}
                >
                  Try again
                </button>
                <button
                  className="btn btn-ghost mt-2 w-full py-2.5"
                  onClick={() => setExportOpen(false)}
                >
                  Back to editor
                </button>
              </>
            ) : (
              <>
                <div className="text-4xl">✅</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Export complete</p>
                <p className="t-dim mt-1 text-sm">
                  Your 9:16 MP4 with voiceover and burned-in captions is ready, plus word-timed
                  SRT and the script.
                </p>
                <div className="mt-5 grid gap-2">
                  <a className="btn btn-yellow py-2.5" href={`/api/exports/${exp.id}/file?type=video`}>
                    Download video (.mp4)
                  </a>
                  <a className="btn btn-ghost py-2.5" href={`/api/exports/${exp.id}/file?type=srt`}>
                    Download captions (.srt)
                  </a>
                  <button
                    className="btn btn-ghost py-2.5"
                    onClick={() =>
                      download(`${slugify(project.title)}-script.txt`, scriptText(project))
                    }
                  >
                    Download script (.txt)
                  </button>
                  <button className="btn btn-ghost py-2.5" onClick={() => setExportOpen(false)}>
                    Back to editor
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

