"use client";

import Link from "next/link";
import { use, useCallback, useEffect, useRef, useState } from "react";
import { CaptionLine, PhonePreview } from "@/components/shared";
import { api } from "@/lib/api";
import { CAPTION_STYLES, VOICES } from "@/lib/constants";
import type { ClientExport } from "@/lib/serialize";
import { useStore } from "@/lib/store";
import { useNarrator } from "@/lib/useNarrator";
import {
  download,
  fmtTime,
  projSeconds,
  sceneSeconds,
  scriptText,
  slugify,
  uid,
  wordsOf,
} from "@/lib/timing";
import type { Project, Scene } from "@/lib/types";

export default function StudioPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const { ready, user } = useStore();
  const [project, setProject] = useState<Project | null>(null);
  const [missing, setMissing] = useState(false);

  useEffect(() => {
    if (!ready || !user) return;
    api
      .getProject(id)
      .then((d) => setProject(d.project))
      .catch(() => setMissing(true));
  }, [ready, user, id]);

  if (!ready || !user) return null;
  if (missing) {
    return (
      <div className="mx-auto max-w-3xl px-5 py-16 text-center">
        <p className="t-inv font-display text-xl font-bold">That video isn&apos;t here anymore.</p>
        <Link href="/app" className="btn btn-yellow mt-6 px-5 py-2.5">
          Back to studio
        </Link>
      </div>
    );
  }
  if (!project) {
    return (
      <div className="mx-auto max-w-3xl px-5 py-16 text-center">
        <p className="t-dim text-sm">Loading project…</p>
      </div>
    );
  }
  return <Studio project={project} setProject={setProject} />;
}

