                <button
                  key={c.id}
                  className={`chip scene-grad-2 flex h-16 flex-col items-center justify-center rounded-xl ${project.caption === c.id ? "" : "opacity-80"}`}
                  style={
                    project.caption === c.id
                      ? { borderColor: "var(--yellow)", borderWidth: 2 }
                      : {}
                  }
                  onClick={() => onChange({ ...project, caption: c.id })}
                  aria-label={`Caption style ${c.name}`}
                >
                  <CaptionLine words={c.sample} hotIdx={1} styleCls={c.cls} size="text-xs" />
                  <span className="t-dim mt-1 uppercase tracking-widest" style={{ fontSize: 10 }}>
                    {c.name}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* timeline column */}
        <div className="lg:col-span-3">
          <div className="bg-panel b-line rounded-2xl border p-4">
            <div className="flex items-center justify-between">
              <p className="t-dim text-xs font-bold uppercase tracking-widest">Timeline</p>
              <p className="t-dim text-xs">
                {project.hashtags
                  ?.slice(0, 3)
                  .map((h) => `#${h.replace(/^#/, "")}`)
                  .join("  ")}
              </p>
            </div>
            {/* strip */}
            <div className="scrollbar-thin bg-panel2 relative mt-3 flex gap-1 overflow-x-auto rounded-xl p-2">
              {project.scenes.map((s, i) => {
                const w = Math.max(56, sceneSeconds(s) * 14);
                return (
                  <button
                    key={s.id}
                    onClick={() => {
                      nar.stop();
                      setSel(i);
                    }}
                    className={`scene-grad-${i % 6} relative shrink-0 rounded-lg border-2 p-1 text-left`}
                    style={{
                      width: w,
                      height: 64,
                      borderColor: i === activeIdx ? "var(--yellow)" : "transparent",
                    }}
                    aria-label={`Scene ${i + 1}`}
                  >
                    <span className="cap-pop absolute left-1 top-1" style={{ fontSize: 10 }}>
                      {i + 1}
                    </span>
                    <span
                      className="t-inv absolute bottom-1 left-1 right-1 truncate opacity-80"
                      style={{ fontSize: 10 }}
                    >
                      {s.narration}
                    </span>
                  </button>
                );
              })}
            </div>
            {/* scene inspector */}
            <div className="mt-4">
              <div className="flex items-center justify-between">
                <p className="t-inv font-display font-bold">
                  Scene {sel + 1}
                  {sel === 0 ? " · Hook" : ""}{" "}
                  <span className="t-dim text-xs font-normal">
                    ({sceneSeconds(project.scenes[sel])}s)
                  </span>
                </p>
                <div className="flex gap-1.5">
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, -1)}
                    aria-label="Move scene earlier"
                  >
                    ←
                  </button>
                  <button
                    className="btn btn-ghost px-2.5 py-1 text-xs"
                    onClick={() => move(sel, 1)}
                    aria-label="Move scene later"
                  >
                    →
                  </button>
                  <button
                    className="btn btn-ghost t-coral px-2.5 py-1 text-xs"
                    onClick={() => removeScene(sel)}
                    aria-label="Delete scene"
                  >
                    Delete
                  </button>
                </div>
              </div>
              <textarea
                className="rs mt-2"
                rows={3}
                value={project.scenes[sel].narration}
                onChange={(e) => setScene(sel, { narration: e.target.value })}
                aria-label="Scene narration"
              />
              <input
                className="rs mt-2 text-sm"
                value={project.scenes[sel].visual}
                placeholder="B-roll / visual idea for this scene"
                onChange={(e) => setScene(sel, { visual: e.target.value })}
                aria-label="Scene visual idea"
              />
              <button
                className="btn btn-ghost mt-3 px-4 py-2 text-sm"
                onClick={() => {
                  const sc = [...project.scenes];
                  sc.splice(sel + 1, 0, {
                    id: uid(),
                    narration: "New scene — write the beat here.",
                    visual: "",
                  });
                  onChange({ ...project, scenes: sc });
                  setSel(sel + 1);
                }}
              >
                + Add scene after
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* export overlay */}
      {exportOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-5">
          <div className="bg-panel b-line w-full max-w-md rounded-2xl border p-7 text-center rise">
            {exportErr ? (
              <>
                <div className="text-4xl">⚠️</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">
                  Couldn&apos;t start the render
                </p>
                <p className="t-coral mt-2 text-sm">{exportErr}</p>
                <button
                  className="btn btn-ghost mt-5 w-full py-2.5"
                  onClick={() => setExportOpen(false)}
                >
                  Back to editor
                </button>
              </>
            ) : !exp || exp.status === "queued" || exp.status === "processing" ? (
              <>
                <p className="font-display t-inv text-xl font-extrabold">Rendering your short</p>
                <p className="t-dim mt-1 text-sm">
                  {exp?.step || "Queued — a render slot opens in a moment…"}
                </p>
                <div className="bg-panel2 mt-5 h-3 overflow-hidden rounded-full">
                  <div
                    className="bg-yellow h-full rounded-full"
                    style={{
                      width: `${Math.min(100, exp?.progress ?? 0)}%`,
                      transition: "width .5s ease",
                    }}
                  ></div>
                </div>
                <p className="t-yellow font-display mt-2 font-bold">
                  {Math.min(100, exp?.progress ?? 0)}%
                </p>
                <p className="t-dim mt-3 text-xs">
                  Real voiceover and captions take a minute or two. You can keep editing — the
                  render uses the version you exported.
                </p>
                <button
                  className="btn btn-ghost mt-4 w-full py-2"
                  onClick={() => setExportOpen(false)}
                >
                  Hide (keeps rendering)
                </button>
              </>
            ) : exp.status === "error" ? (
              <>
                <div className="text-4xl">⚠️</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Render failed</p>
                <p className="t-coral mt-2 text-sm">{exp.error || "Unknown render error."}</p>
                <button
                  className="btn btn-yellow mt-5 w-full py-2.5"
                  onClick={() => {
                    setExp(null);
                    void runExport();
                  }}
                >
                  Try again
                </button>
                <button
                  className="btn btn-ghost mt-2 w-full py-2.5"
                  onClick={() => setExportOpen(false)}
                >
                  Back to editor
                </button>
              </>
            ) : (
              <>
                <div className="text-4xl">✅</div>
                <p className="font-display t-inv mt-2 text-xl font-extrabold">Export complete</p>
                <p className="t-dim mt-1 text-sm">
                  Your 9:16 MP4 with voiceover and burned-in captions is ready, plus word-timed
                  SRT and the script.
                </p>
                <div className="mt-5 grid gap-2">
                  <a className="btn btn-yellow py-2.5" href={`/api/exports/${exp.id}/file?type=video`}>
                    Download video (.mp4)
                  </a>
                  <a className="btn btn-ghost py-2.5" href={`/api/exports/${exp.id}/file?type=srt`}>
                    Download captions (.srt)
                  </a>
                  <button
                    className="btn btn-ghost py-2.5"
                    onClick={() =>
                      download(`${slugify(project.title)}-script.txt`, scriptText(project))
                    }
                  >
                    Download script (.txt)
                  </button>
                  <button className="btn btn-ghost py-2.5" onClick={() => setExportOpen(false)}>
                    Back to editor
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

