"use client";

import Link from "next/link";
import { useState } from "react";
import { PLANS } from "@/lib/constants";
import { useStore } from "@/lib/store";
import type { PlanId } from "@/lib/types";

export default function BillingPage() {
  const { user, usage, changePlan } = useStore();
  const [busy, setBusy] = useState<PlanId | null>(null);
  const [err, setErr] = useState("");
  if (!user) return null;
  const current = PLANS.find((p) => p.id === user.plan) ?? PLANS[0];

  const switchPlan = async (plan: PlanId) => {
    setBusy(plan);
    setErr("");
    const error = await changePlan(plan);
    if (error) setErr(error);
    setBusy(null);
  };

  return (
    <div className="mx-auto max-w-5xl px-5 py-10">
      <Link href="/app" className="t-dim text-sm">
        ← Back to studio
      </Link>
      <h1 className="font-display t-inv mt-4 text-3xl font-extrabold">Plan &amp; billing</h1>
      <p className="t-dim mt-1">
        You&apos;re on <span className="t-yellow font-bold">{current.name}</span> · {usage.used}{" "}
        videos used this month. Switch plans any time.
      </p>
      {err && <p className="t-coral mt-3 text-sm">{err}</p>}
      <div className="mt-8 grid gap-4 md:grid-cols-3">
        {PLANS.map((p) => (
          <div
            key={p.id}
            className={`bg-panel rounded-2xl border p-6 ${user.plan === p.id ? "" : "b-line"}`}
            style={user.plan === p.id ? { borderColor: "var(--yellow)" } : {}}
          >
            <h3 className="font-display t-inv text-xl font-extrabold">{p.name}</h3>
            <p className="t-yellow font-display mt-2 text-3xl font-extrabold">
              ${p.price}
              <span className="t-dim text-sm">/mo</span>
            </p>
            <p className="t-dim mt-1 text-sm">{p.videos} videos / month</p>
            <button
              className={`btn mt-5 w-full py-2.5 ${user.plan === p.id ? "btn-ghost" : "btn-yellow"}`}
              onClick={() => switchPlan(p.id)}
              disabled={user.plan === p.id || busy !== null}
            >
              {user.plan === p.id
                ? "Current plan"
                : busy === p.id
                  ? "Switching…"
                  : "Switch to " + p.name}
            </button>
          </div>
        ))}
      </div>
      <p className="t-dim mt-6 text-xs">
        Production note: plan switching moves to Stripe Checkout + a customer portal (roadmap
        step 5).
      </p>
    </div>
  );
}

