import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { toClientProject } from "@/lib/serialize";
import type { Project } from "@/lib/types";

async function ownedProject(id: string, userId: string) {
  const project = await db.project.findUnique({ where: { id } });
  if (!project || project.userId !== userId) return null;
  return project;
}

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;
  const project = await ownedProject(id, user.id);
  if (!project) return NextResponse.json({ error: "not found" }, { status: 404 });
  return NextResponse.json({ project: toClientProject(project) });
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;
  const project = await ownedProject(id, user.id);
  if (!project) return NextResponse.json({ error: "not found" }, { status: 404 });

  let body: Partial<Project>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  if (body.scenes && (!Array.isArray(body.scenes) || body.scenes.length === 0)) {
    return NextResponse.json({ error: "invalid scenes" }, { status: 400 });
  }

  const updated = await db.project.update({
    where: { id },
    data: {
      ...(body.title !== undefined ? { title: body.title } : {}),
      ...(body.scenes !== undefined ? { scenes: body.scenes } : {}),
      ...(body.voice !== undefined ? { voice: body.voice } : {}),
      ...(body.caption !== undefined ? { caption: body.caption } : {}),
      ...(body.hashtags !== undefined ? { hashtags: body.hashtags } : {}),
    },
  });
  return NextResponse.json({ project: toClientProject(updated) });
}

export async function DELETE(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;
  const project = await ownedProject(id, user.id);
  if (!project) return NextResponse.json({ error: "not found" }, { status: 404 });
  await db.project.delete({ where: { id } });
  return NextResponse.json({ ok: true });
}

