"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import type { PlanId } from "./types";

/* API-backed auth/session context. Projects are fetched per-page via
   lib/api.ts; this context only tracks who is signed in and their usage. */

export interface SessionUser {
  id: string;
  name: string;
  email: string;
  plan: PlanId;
}

export interface Usage {
  used: number;
  limit: number;
}

interface StoreState {
  ready: boolean;
  user: SessionUser | null;
  usage: Usage;
  refresh: () => Promise<void>;
  register: (input: { name: string; email: string; password: string }) => Promise<string | null>;
  login: (input: { email: string; password: string }) => Promise<string | null>;
  logout: () => Promise<void>;
  changePlan: (plan: PlanId) => Promise<string | null>;
}

const StoreContext = createContext<StoreState | null>(null);

async function jsonOrError(res: Response): Promise<{ data: unknown; error: string | null }> {
  try {
    const data = await res.json();
    if (!res.ok) {
      const err = (data as { error?: string }).error || `Request failed (${res.status})`;
      return { data: null, error: err };
    }
    return { data, error: null };
  } catch {
    return { data: null, error: `Request failed (${res.status})` };
  }
}

export function StoreProvider({ children }: { children: ReactNode }) {
  const [ready, setReady] = useState(false);
  const [user, setUser] = useState<SessionUser | null>(null);
  const [usage, setUsage] = useState<Usage>({ used: 0, limit: 30 });

  const refresh = useCallback(async () => {
    try {
      const res = await fetch("/api/auth/me", { cache: "no-store" });
      if (res.ok) {
        const data = (await res.json()) as { user: SessionUser; usage: Usage };
        setUser(data.user);
        setUsage(data.usage);
      } else {
        setUser(null);
      }
    } catch {
      setUser(null);
    }
    setReady(true);
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const register = useCallback(
    async (input: { name: string; email: string; password: string }) => {
      const res = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      });
      const { error } = await jsonOrError(res);
      if (!error) await refresh();
      return error;
    },
    [refresh],
  );

  const login = useCallback(
    async (input: { email: string; password: string }) => {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(input),
      });
      const { error } = await jsonOrError(res);
      if (!error) await refresh();
      return error;
    },
    [refresh],
  );

  const logout = useCallback(async () => {
    await fetch("/api/auth/logout", { method: "POST" });
    setUser(null);
  }, []);

  const changePlan = useCallback(
    async (plan: PlanId) => {
      const res = await fetch("/api/me/plan", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ plan }),
      });
      const { error } = await jsonOrError(res);
      if (!error) await refresh();
      return error;
    },
    [refresh],
  );

  return (
    <StoreContext.Provider
      value={{ ready, user, usage, refresh, register, login, logout, changePlan }}
    >
      {children}
    </StoreContext.Provider>
  );
}

export function useStore(): StoreState {
  const ctx = useContext(StoreContext);
  if (!ctx) throw new Error("useStore must be used within StoreProvider");
  return ctx;
}

