import nodemailer from "nodemailer";

/* Sends login emails via SMTP when configured. When SMTP env vars are
   absent (dev / not-yet-configured), it logs the code+link to stdout so the
   passwordless flow still works — the server operator reads it from logs. */

const {
  SMTP_HOST,
  SMTP_PORT,
  SMTP_USER,
  SMTP_PASS,
  SMTP_FROM,
  APP_URL,
} = process.env;

const smtpReady = Boolean(SMTP_HOST && SMTP_USER && SMTP_PASS);

const transport = smtpReady
  ? nodemailer.createTransport({
      host: SMTP_HOST,
      port: Number(SMTP_PORT || 587),
      secure: Number(SMTP_PORT) === 465,
      auth: { user: SMTP_USER, pass: SMTP_PASS },
    })
  : null;

export async function sendLoginEmail(
  email: string,
  code: string,
  token: string,
): Promise<{ delivered: boolean }> {
  const link = `${APP_URL || "http://localhost:3000"}/login/verify?token=${token}`;
  if (!transport) {
    // eslint-disable-next-line no-console
    console.log(
      `\n[VidForge login] ${email}\n  code: ${code}\n  link: ${link}\n(SMTP not configured — email not sent)\n`,
    );
    return { delivered: false };
  }
  await transport.sendMail({
    from: SMTP_FROM || SMTP_USER,
    to: email,
    subject: `Your VidForge login code: ${code}`,
    text: `Your code is ${code}. Or log in instantly: ${link}`,
    html: `<p>Your verification code is <b style="font-size:20px">${code}</b>.</p>
           <p>Or <a href="${link}">log in instantly with this link</a>.</p>`,
  });
  return { delivered: true };
}

