import { NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { randomInt, randomUUID } from "crypto";
import { db } from "@/lib/db";
import { sendLoginEmail } from "@/lib/mailer";

const CODE_TTL_MIN = 15;

/** Start passwordless login: create the user if new, issue an OTP + magic
    link, and email them (or log in dev). Always 200 to avoid email
    enumeration. */
export async function POST(request: Request) {
  let body: { email?: string; name?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const email = (body.email || "").trim().toLowerCase();
  if (!email.includes("@")) {
    return NextResponse.json({ error: "Enter a valid email address." }, { status: 400 });
  }

  const user = await db.user.upsert({
    where: { email },
    update: {},
    create: { email, name: body.name?.trim() || null },
  });

  const code = String(randomInt(0, 1_000_000)).padStart(6, "0");
  const token = randomUUID().replace(/-/g, "") + randomUUID().replace(/-/g, "");
  await db.loginCode.create({
    data: {
      userId: user.id,
      codeHash: await bcrypt.hash(code, 10),
      token,
      expiresAt: new Date(Date.now() + CODE_TTL_MIN * 60_000),
    },
  });

  const { delivered } = await sendLoginEmail(email, code, token);
  return NextResponse.json({ ok: true, delivered });
}

