import { NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { db } from "@/lib/db";
import { setSessionCookie } from "@/lib/auth";

/** Complete login via OTP (email + code) or magic link (token). */
export async function POST(request: Request) {
  let body: { email?: string; code?: string; token?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }

  let userId: string | null = null;

  if (body.token) {
    const lc = await db.loginCode.findUnique({ where: { token: body.token } });
    if (lc && !lc.consumed && lc.expiresAt > new Date()) {
      userId = lc.userId;
      await db.loginCode.update({ where: { id: lc.id }, data: { consumed: true } });
    }
  } else if (body.email && body.code) {
    const email = body.email.trim().toLowerCase();
    const user = await db.user.findUnique({ where: { email } });
    if (user) {
      const lc = await db.loginCode.findFirst({
        where: { userId: user.id, consumed: false, expiresAt: { gt: new Date() } },
        orderBy: { createdAt: "desc" },
      });
      if (lc && (await bcrypt.compare(body.code.trim(), lc.codeHash))) {
        userId = user.id;
        await db.loginCode.update({ where: { id: lc.id }, data: { consumed: true } });
      }
    }
  }

  if (!userId) {
    return NextResponse.json(
      { error: "That code or link is invalid or expired." },
      { status: 401 },
    );
  }

  await setSessionCookie(userId);
  const user = await db.user.findUnique({ where: { id: userId } });
  return NextResponse.json({
    user: user && {
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
      plan: user.plan,
    },
  });
}

