  const email = (process.env.ADMIN_EMAIL || "haxkodi@gmail.com").toLowerCase();
  const user = await db.user.upsert({
    where: { email },
    update: { role: "admin", plan: "business" },
    create: { email, name: "Admin", role: "admin", plan: "business", credits: 0 },
  });
  console.log(`Admin account ready: ${user.email} (role=${user.role})`);
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => {
    console.error(e);
    await db.$disconnect();
    process.exit(1);
  });

