"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import Link from "next/link";

export default function LoginPage() {
  const router = useRouter();
  const [step, setStep] = useState<"email" | "code">("email");
  const [email, setEmail] = useState("");
  const [code, setCode] = useState("");
  const [err, setErr] = useState("");
  const [note, setNote] = useState("");
  const [busy, setBusy] = useState(false);

  const requestCode = async () => {
    if (!email.includes("@")) return setErr("Enter a valid email address.");
    setErr("");
    setBusy(true);
    const res = await fetch("/api/auth/request", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email }),
    });
    setBusy(false);
    if (!res.ok) {
      const d = await res.json().catch(() => ({}));
      return setErr(d.error || "Something went wrong.");
    }
    const d = await res.json();
    setNote(
      d.delivered
        ? "Check your email for a 6-digit code and a magic link."
        : "Email isn't configured yet — ask the operator for your code (it's in the server logs).",
    );
    setStep("code");
  };

  const verify = async () => {
    setErr("");
    setBusy(true);
    const res = await fetch("/api/auth/verify", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, code }),
    });
    setBusy(false);
    if (!res.ok) {
      const d = await res.json().catch(() => ({}));
      return setErr(d.error || "Invalid code.");
    }
    router.push("/app");
  };

  return (
    <div className="flex min-h-screen items-center justify-center px-6">
      <div className="card w-full max-w-md p-8">
        <Link href="/" className="font-display text-xl font-bold">
          Vid<span className="t-accent">Forge</span>
        </Link>
        <h1 className="font-display mt-6 text-2xl font-bold">
          {step === "email" ? "Sign in or create your studio" : "Enter your code"}
        </h1>
        <p className="t-dim mt-1 text-sm">
          {step === "email"
            ? "We'll email you a login code — no password needed."
            : note}
        </p>

        <div className="mt-6 space-y-3">
          {step === "email" ? (
            <>
              <input
                className="field"
                type="email"
                placeholder="you@email.com"
                value={email}
                onChange={(e) => {
                  setEmail(e.target.value);
                  setErr("");
                }}
                onKeyDown={(e) => e.key === "Enter" && requestCode()}
                aria-label="Email"
              />
              {err && <p className="text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
              <button className="btn btn-primary w-full py-3" onClick={requestCode} disabled={busy}>
                {busy ? "Sending…" : "Send my code"}
              </button>
            </>
          ) : (
            <>
              <input
                className="field text-center tracking-[0.4em]"
                inputMode="numeric"
                placeholder="000000"
                maxLength={6}
                value={code}
                onChange={(e) => {
                  setCode(e.target.value.replace(/\D/g, ""));
                  setErr("");
                }}
                onKeyDown={(e) => e.key === "Enter" && verify()}
                aria-label="Verification code"
              />
              {err && <p className="text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
              <button className="btn btn-primary w-full py-3" onClick={verify} disabled={busy}>
                {busy ? "Verifying…" : "Verify & continue"}
              </button>
              <button
                className="btn btn-ghost w-full py-2 text-sm"
                onClick={() => {
                  setStep("email");
                  setCode("");
                  setErr("");
                }}
              >
                Use a different email
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

