"use client";

import { useRouter, useSearchParams } from "next/navigation";
import { Suspense, useEffect, useState } from "react";

function Verifier() {
  const router = useRouter();
  const params = useSearchParams();
  const [err, setErr] = useState("");

  useEffect(() => {
    const token = params.get("token");
    if (!token) {
      setErr("Missing login token.");
      return;
    }
    fetch("/api/auth/verify", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ token }),
    }).then(async (res) => {
      if (res.ok) router.replace("/app");
      else {
        const d = await res.json().catch(() => ({}));
        setErr(d.error || "That link is invalid or expired.");
      }
    });
  }, [params, router]);

  return (
    <div className="flex min-h-screen items-center justify-center px-6">
      <div className="card max-w-md p-8 text-center">
        {err ? (
          <>
            <p className="font-display text-xl font-bold">Login link problem</p>
            <p className="t-dim mt-2 text-sm">{err}</p>
            <a href="/login" className="btn btn-primary mt-5 px-5 py-2.5">
              Back to sign in
            </a>
          </>
        ) : (
          <p className="t-dim text-sm">Signing you in…</p>
        )}
      </div>
    </div>
  );
}

export default function VerifyPage() {
  return (
    <Suspense>
      <Verifier />
    </Suspense>
  );
}

