import Link from "next/link";
import { redirect } from "next/navigation";
import { getSessionUser, isAdmin } from "@/lib/auth";
import { TOOLS } from "@/lib/tools";
import LogoutButton from "./logout-button";

export default async function AppLayout({ children }: { children: React.ReactNode }) {
  const user = await getSessionUser();
  if (!user) redirect("/login");
  const admin = isAdmin(user);

  return (
    <div className="flex min-h-screen">
      {/* sidebar */}
      <aside className="surface b-line hidden w-60 shrink-0 border-r md:flex md:flex-col">
        <div className="p-5">
          <Link href="/app" className="font-display text-lg font-bold">
            Vid<span className="t-accent">Forge</span>
          </Link>
        </div>
        <nav className="flex-1 overflow-y-auto px-3 pb-4">
          <p className="t-mute px-2 py-2 text-xs font-bold uppercase tracking-widest">Tools</p>
          {TOOLS.map((t) => (
            <Link
              key={t.id}
              href={t.ready ? `/app/${t.id}` : "/app"}
              className="flex items-center gap-2.5 rounded-lg px-2.5 py-2 text-sm t-dim hover:surface2"
            >
              <span>{t.icon}</span>
              <span>{t.name}</span>
              {!t.ready && (
                <span className="t-mute ml-auto text-[10px] uppercase">soon</span>
              )}
            </Link>
          ))}
        </nav>
        <div className="b-line border-t p-4">
          <p className="truncate text-sm font-semibold">{user.name || user.email}</p>
          <p className="t-mute text-xs">
            {admin ? "Admin · unlimited" : `${user.credits} credits · ${user.plan}`}
          </p>
          <LogoutButton />
        </div>
      </aside>

      <main className="flex-1">{children}</main>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";

export default function LogoutButton() {
  const router = useRouter();
