import { NextResponse } from "next/server";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { clientProject } from "@/lib/serialize";

export async function GET() {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const projects = await db.project.findMany({
    where: { userId: user.id },
    orderBy: { updatedAt: "desc" },
  });
  return NextResponse.json({ projects: projects.map(clientProject) });
}

export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: { type?: string; title?: string; config?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  if (!body.type) return NextResponse.json({ error: "type required" }, { status: 400 });

  const project = await db.project.create({
    data: {
      userId: user.id,
      type: body.type,
      title: body.title?.trim() || "Untitled",
      config: (body.config ?? {}) as Prisma.InputJsonValue,
    },
  });
  return NextResponse.json({ project: clientProject(project) });
}

