import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { canAfford, COSTS, spend } from "@/lib/credits";
import { clientJob } from "@/lib/serialize";

/** Enqueue a render for a project. Charges credits (admins exempt). The
    worker picks up queued RenderJob rows. */
export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;

  const project = await db.project.findUnique({ where: { id } });
  if (!project || project.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const affordable = canAfford(user, COSTS.render);
  if (!affordable.ok) {
    return NextResponse.json({ error: affordable.reason }, { status: 403 });
  }

  // Reuse an in-flight job rather than stacking duplicates.
  const running = await db.renderJob.findFirst({
    where: { projectId: id, status: { in: ["queued", "processing"] } },
  });
  if (running) return NextResponse.json({ job: clientJob(running) });

  const job = await db.renderJob.create({
    data: { projectId: id, userId: user.id },
  });
  await db.project.update({ where: { id }, data: { status: "rendering" } });
  await spend(user, COSTS.render, `render:${project.type}`);

  return NextResponse.json({ job: clientJob(job) });
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { clientJob } from "@/lib/serialize";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;
  const job = await db.renderJob.findUnique({ where: { id }, include: { assets: true } });
  if (!job || job.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  return NextResponse.json({ job: clientJob(job, job.assets) });
}

