    return NextResponse.json({ error: affordable.reason }, { status: 403 });
  }

  // Reuse an in-flight job rather than stacking duplicates.
  const running = await db.renderJob.findFirst({
    where: { projectId: id, status: { in: ["queued", "processing"] } },
  });
  if (running) return NextResponse.json({ job: clientJob(running) });

  const job = await db.renderJob.create({
    data: { projectId: id, userId: user.id },
  });
  await db.project.update({ where: { id }, data: { status: "rendering" } });
  await spend(user, COSTS.render, `render:${project.type}`);

  return NextResponse.json({ job: clientJob(job) });
}

