"use client";

export interface Project {
  id: string;
  type: string;
  title: string;
  config: unknown;
  status: string;
}

export interface Job {
  id: string;
  projectId: string;
  status: string;
  progress: number;
  step: string;
  error: string | null;
  assets: { id: string; kind: string }[];
}

async function req<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, {
    ...init,
    headers: init?.body ? { "Content-Type": "application/json" } : undefined,
    cache: "no-store",
  });
  if (!res.ok) {
    let msg = `Request failed (${res.status})`;
    try {
      const d = (await res.json()) as { error?: string };
      if (d.error) msg = d.error;
    } catch {
      /* non-JSON */
    }
    throw new Error(msg);
  }
  return res.json() as Promise<T>;
}

export const api = {
  createProject: (type: string, title: string, config: unknown) =>
    req<{ project: Project }>("/api/projects", {
      method: "POST",
      body: JSON.stringify({ type, title, config }),
