import Anthropic from "@anthropic-ai/sdk";

/* Provider-agnostic script generation. Uses Anthropic when ANTHROPIC_API_KEY
   is set (the user's chosen provider); otherwise returns deterministic mock
   content so every tool works before a key is added. Server-side only. */

const MODEL = process.env.VIDFORGE_LLM_MODEL || "claude-opus-4-8";
const hasKey = Boolean(process.env.ANTHROPIC_API_KEY);

export const llmReady = hasKey;

async function complete(prompt: string, maxTokens = 1200): Promise<string> {
  const client = new Anthropic();
  const res = await client.messages.create({
    model: MODEL,
    max_tokens: maxTokens,
    messages: [{ role: "user", content: prompt }],
  });
  return res.content.map((b) => (b.type === "text" ? b.text : "")).join("").trim();
}

function parseJson<T>(text: string): T {
  return JSON.parse(text.replace(/```json|```/g, "").trim()) as T;
}

// --- Commentary / story script -------------------------------
export interface Scripted {
  title: string;
  script: string;
}

export async function commentaryScript(topic: string, tone: string): Promise<Scripted> {
  if (!hasKey) {
    return {
      title: topic,
      script:
        `Here's the wild part about ${topic}. Most people scroll right past this, ` +
        `but stay with me — what happens next is the reason this clip has millions of views. ` +
        `Watch closely, because the ending changes everything.`,
    };
  }
  const prompt = `You are a viral short-form video scriptwriter. Write a punchy ${tone} voiceover commentary (60-90 words, spoken, hook-first) for a video about: "${topic}". Respond ONLY with JSON: {"title":"...","script":"..."}`;
  return parseJson<Scripted>(await complete(prompt));
}

// --- Ranking narrations --------------------------------------
export async function rankingNarrations(
  title: string,
  count: number,
  tone: string,
): Promise<string[]> {
  if (!hasKey) {
    return Array.from({ length: count }, (_, i) =>
      `Number ${count - i}: this one earned its spot — watch what happens.`,
    );
  }
  const prompt = `For a countdown video titled "${title}", write ${count} short ${tone} voiceover lines (one per rank, counting down from #${count} to #1, 1-2 sentences each, spoken). Respond ONLY with JSON: {"lines":["...", "..."]}`;
  const out = parseJson<{ lines: string[] }>(await complete(prompt));
  return out.lines.slice(0, count);
}

// --- Text-story conversation ---------------------------------
export interface ChatMessage {
  from: "me" | "them";
  text: string;
}

export async function textStory(prompt_topic: string, tone: string): Promise<ChatMessage[]> {
  if (!hasKey) {
    return [
      { from: "them", text: "you'll never guess what just happened" },
      { from: "me", text: "what?? tell me" },
      { from: "them", text: `it's about ${prompt_topic}` },
      { from: "me", text: "wait no way" },
      { from: "them", text: "i'm dead serious 💀" },
      { from: "me", text: "ok you HAVE to explain right now" },
    ];
  }
  const prompt = `Write a suspenseful ${tone} fake text-message conversation (8-14 messages, alternating) that tells a mini-story about "${prompt_topic}" for a viral screen-recording video. Keep each message short and texty. Respond ONLY with JSON: {"messages":[{"from":"them|me","text":"..."}]}`;
  const out = parseJson<{ messages: ChatMessage[] }>(await complete(prompt));
  return out.messages;
}

