  const prompt = `For a countdown video titled "${title}", write ${count} short ${tone} voiceover lines (one per rank, counting down from #${count} to #1, 1-2 sentences each, spoken). Respond ONLY with JSON: {"lines":["...", "..."]}`;
  const out = parseJson<{ lines: string[] }>(await complete(prompt));
  return out.lines.slice(0, count);
}

// --- Text-story conversation ---------------------------------
export interface ChatMessage {
  from: "me" | "them";
  text: string;
}

export async function textStory(prompt_topic: string, tone: string): Promise<ChatMessage[]> {
  if (!hasKey) {
    return [
      { from: "them", text: "you'll never guess what just happened" },
      { from: "me", text: "what?? tell me" },
      { from: "them", text: `it's about ${prompt_topic}` },
      { from: "me", text: "wait no way" },
      { from: "them", text: "i'm dead serious 💀" },
      { from: "me", text: "ok you HAVE to explain right now" },
    ];
  }
  const prompt = `Write a suspenseful ${tone} fake text-message conversation (8-14 messages, alternating) that tells a mini-story about "${prompt_topic}" for a viral screen-recording video. Keep each message short and texty. Respond ONLY with JSON: {"messages":[{"from":"them|me","text":"..."}]}`;
  const out = parseJson<{ messages: ChatMessage[] }>(await complete(prompt));
  return out.messages;
}

