/** Script/idea generation for the tools. Falls back to mock content when no
    LLM key is configured (llmReady=false). */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: { kind?: string; topic?: string; tone?: string; count?: number };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const tone = body.tone || "dramatic";
  const topic = (body.topic || "").trim();
  if (!topic) return NextResponse.json({ error: "topic required" }, { status: 400 });

  try {
    if (body.kind === "commentary") {
      return NextResponse.json({ result: await commentaryScript(topic, tone), mock: !llmReady });
