import { writeFile, mkdir } from "fs/promises";
import path from "path";
import { randomUUID } from "crypto";
import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth";

const DATA_DIR = process.env.RENDER_DATA_DIR || "/data";
const MAX_BYTES = 512 * 1024 * 1024;
const OK_EXT = new Set([".mp4", ".mov", ".avi", ".webm", ".mkv", ".m4v"]);

/** Stores an uploaded source clip in the shared media volume and returns a
    path the worker can read (relative to RENDER_DATA_DIR). */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const form = await request.formData();
  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "no file" }, { status: 400 });
  }
  if (file.size > MAX_BYTES) {
    return NextResponse.json({ error: "file too large (max 512MB)" }, { status: 413 });
  }
  const ext = path.extname(file.name).toLowerCase();
  if (!OK_EXT.has(ext)) {
    return NextResponse.json({ error: "unsupported format" }, { status: 400 });
  }

  const rel = path.join("uploads", `${randomUUID()}${ext}`);
  const abs = path.join(DATA_DIR, rel);
  await mkdir(path.dirname(abs), { recursive: true });
  await writeFile(abs, Buffer.from(await file.arrayBuffer()));
  return NextResponse.json({ path: rel });
}

