"""Client for the downloader microservice (yt-dlp + POT + cookies)."""

import os
import requests

DOWNLOADER_URL = os.environ.get("DOWNLOADER_URL", "http://downloader:8000")
DATA_DIR = os.environ.get("RENDER_DATA_DIR", "/data")


class DownloadError(Exception):
    pass


def fetch(url: str) -> str:
    """Download a social URL; returns an absolute path on the shared volume."""
    try:
        res = requests.post(f"{DOWNLOADER_URL}/download", json={"url": url}, timeout=300)
    except requests.RequestException as e:
        raise DownloadError(f"downloader unreachable: {e}")
    if res.status_code != 200:
        detail = res.json().get("detail", res.text) if res.content else res.text
        raise DownloadError(detail)
    rel = res.json()["path"]
    return os.path.join(DATA_DIR, "downloads", rel)

