"use client";

import { useRef, useState } from "react";
import { api, type Job } from "@/lib/api";

/** Shared render lifecycle for the creation tools: create project → enqueue
    render → poll job → expose progress + download assets. */
export function useRender() {
  const [job, setJob] = useState<Job | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const poll = useRef<ReturnType<typeof setInterval> | null>(null);

  const start = async (type: string, title: string, config: unknown) => {
    setErr("");
    setBusy(true);
    setJob(null);
    try {
      const { project } = await api.createProject(type, title, config);
      const { job: j } = await api.render(project.id);
      setJob(j);
      poll.current = setInterval(async () => {
        try {
          const { job: cur } = await api.getJob(j.id);
          setJob(cur);
          if (cur.status === "done" || cur.status === "error") {
            if (poll.current) clearInterval(poll.current);
            setBusy(false);
          }
        } catch {
          if (poll.current) clearInterval(poll.current);
          setBusy(false);
        }
      }, 2000);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Failed to start render.");
      setBusy(false);
    }
  };

  return { job, busy, err, setErr, start };
}

export function RenderResult({ job }: { job: Job | null }) {
  if (!job) return null;
  const video = job.assets.find((a) => a.kind === "video");
  const srt = job.assets.find((a) => a.kind === "srt");
  return (
    <div className="card mt-5 p-5 text-center">
      {job.status === "done" && video ? (
        <>
          <p className="font-display text-lg font-bold">✅ Your video is ready</p>
          <div className="mt-4 grid gap-2">
            <a className="btn btn-primary py-2.5" href={`/api/assets/${video.id}`}>
              Download video (.mp4)
            </a>
            {srt && (
              <a className="btn btn-ghost py-2.5" href={`/api/assets/${srt.id}`}>
                Download captions / transcript
              </a>
            )}
          </div>
        </>
      ) : job.status === "error" ? (
        <>
          <p className="font-display text-lg font-bold">⚠️ Render failed</p>
          <p className="mt-2 text-sm" style={{ color: "#ff6b6b" }}>
            {job.error || "Unknown error."}
          </p>
        </>
      ) : (
        <>
          <p className="t-dim text-sm">{job.step}</p>
          <div className="surface2 mt-3 h-2.5 overflow-hidden rounded-full">
            <div
              className="h-full rounded-full"
              style={{
                width: `${job.progress}%`,
                background: "linear-gradient(135deg,var(--accent),var(--accent-2))",
                transition: "width .5s ease",
              }}
            />
          </div>
          <p className="t-accent mt-2 font-bold">{job.progress}%</p>
          <p className="t-mute mt-2 text-xs">Rendering — this takes a minute or two.</p>
        </>
      )}
    </div>
  );
}

