"use client";

import { useState } from "react";
import Link from "next/link";
import { CAPTIONS, VOICES } from "@/lib/presets";

export function ToolHeader({ icon, title, desc }: { icon: string; title: string; desc: string }) {
  return (
    <>
      <Link href="/app" className="t-dim text-sm">
        ← Studio
      </Link>
      <h1 className="font-display mt-3 text-3xl font-bold">
        {icon} {title}
      </h1>
      <p className="t-dim mt-1">{desc}</p>
    </>
  );
}

export function VoicePicker({ value, onChange, label = "Voice" }: {
  value: string;
  onChange: (v: string) => void;
  label?: string;
}) {
  return (
    <div>
      <label className="t-dim text-xs font-bold uppercase tracking-widest">{label}</label>
      <select className="field mt-2" value={value} onChange={(e) => onChange(e.target.value)}>
        {VOICES.map((v) => (
          <option key={v.id} value={v.id}>
            {v.name} — {v.tag}
          </option>
        ))}
      </select>
    </div>
  );
}

export function CaptionPicker({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  return (
    <div>
      <label className="t-dim text-xs font-bold uppercase tracking-widest">Captions</label>
      <select className="field mt-2" value={value} onChange={(e) => onChange(e.target.value)}>
        {CAPTIONS.map((c) => (
          <option key={c.id} value={c.id}>
            {c.name}
          </option>
        ))}
      </select>
    </div>
  );
}

export type Source =
  | { type: "url"; url: string }
  | { type: "upload"; path: string; name: string }
  | null;

export function SourceInput({
  value,
  onChange,
  placeholder = "YouTube / TikTok / Instagram URL",
}: {
  value: Source;
  onChange: (s: Source) => void;
  placeholder?: string;
}) {
  const [uploading, setUploading] = useState(false);
  const [err, setErr] = useState("");

  const upload = async (file: File) => {
    setUploading(true);
    setErr("");
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/upload", { method: "POST", body: fd });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        throw new Error(d.error || "upload failed");
      }
      const { path } = await res.json();
      onChange({ type: "upload", path, name: file.name });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "upload failed");
    }
    setUploading(false);
  };

  return (
    <div>
      <input
        className="field"
        value={value?.type === "url" ? value.url : ""}
        onChange={(e) => onChange(e.target.value ? { type: "url", url: e.target.value } : null)}
        placeholder={placeholder}
      />
      <div className="mt-2 flex items-center gap-3">
        <span className="t-mute text-xs">or</span>
        <label className="btn btn-ghost cursor-pointer px-3 py-1.5 text-xs">
          {uploading
            ? "Uploading…"
            : value?.type === "upload"
              ? `📎 ${value.name}`
              : "Upload a clip"}
          <input
            type="file"
            accept="video/*"
            className="hidden"
            onChange={(e) => e.target.files?.[0] && upload(e.target.files[0])}
          />
        </label>
      </div>
      {err && <p className="mt-1 text-xs" style={{ color: "#ff6b6b" }}>{err}</p>}
    </div>
  );
}

/** AI-generate a script/idea via /api/generate. Returns text or throws. */
export async function generate(kind: string, topic: string, tone: string, count?: number) {
  const res = await fetch("/api/generate", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ kind, topic, tone, count }),
  });
  if (!res.ok) throw new Error("generation failed");
  return res.json() as Promise<{ result: unknown; mock: boolean }>;
}

