import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth";

const DOWNLOADER_URL = process.env.DOWNLOADER_URL || "http://downloader:8000";

/** Content research: search YouTube for high-performing clips in a niche,
    ranked by views (outliers first). Backed by yt-dlp (no API key needed). */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: { query?: string; shorts?: boolean; limit?: number };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const query = (body.query || "").trim();
  if (!query) return NextResponse.json({ error: "query required" }, { status: 400 });

  try {
    const res = await fetch(`${DOWNLOADER_URL}/search`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ query, shorts: body.shorts ?? true, limit: body.limit ?? 20 }),
    });
    const data = await res.json();
    if (!res.ok) {
      return NextResponse.json({ error: data.detail || "search failed" }, { status: 502 });
    }
    return NextResponse.json(data);
  } catch {
    return NextResponse.json({ error: "research service unreachable" }, { status: 502 });
  }
}

