import { NextResponse } from "next/server";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { canAfford, COSTS, spend } from "@/lib/credits";

const DOWNLOADER_URL = process.env.DOWNLOADER_URL || "http://downloader:8000";

/** Standalone downloader tool: fetch a social URL and expose it as a
    downloadable asset. Charges a small credit cost (admins exempt). */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: { url?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const url = (body.url || "").trim();
  if (!url) return NextResponse.json({ error: "url required" }, { status: 400 });

  const affordable = canAfford(user, COSTS.download);
  if (!affordable.ok) return NextResponse.json({ error: affordable.reason }, { status: 403 });

  let dl: { path: string; title?: string; platform?: string };
  try {
    const res = await fetch(`${DOWNLOADER_URL}/download`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ url }),
    });
    const data = await res.json();
    if (!res.ok) return NextResponse.json({ error: data.detail || "download failed" }, { status: 502 });
    dl = data;
  } catch {
    return NextResponse.json({ error: "downloader unreachable" }, { status: 502 });
  }

  const project = await db.project.create({
    data: {
      userId: user.id,
      type: "downloader",
      title: dl.title || url,
      config: { url } as Prisma.InputJsonValue,
      status: "done",
    },
  });
  const asset = await db.asset.create({
    data: { projectId: project.id, kind: "video", path: `downloads/${dl.path}` },
  });
  await spend(user, COSTS.download, `download:${dl.platform || "url"}`);

  return NextResponse.json({ assetId: asset.id, title: dl.title || url });
}

