"use client";

import { useState } from "react";
import { RenderResult, useRender } from "@/lib/useRender";
import { CaptionPicker, SourceInput, ToolHeader, VoicePicker, type Source } from "@/components/tool-ui";

export default function SplitScreenBuilder() {
  const { job, busy, err, setErr, start } = useRender();
  const [top, setTop] = useState<Source>(null);
  const [bottom, setBottom] = useState<Source>(null);
  const [seconds, setSeconds] = useState(15);
  const [script, setScript] = useState("");
  const [voice, setVoice] = useState("atlas");
  const [caption, setCaption] = useState("pop");

  const run = () => {
    if (!top || !bottom) return setErr("Add both a top and bottom clip.");
    start("split_screen", "Split screen", {
      top: top.type === "url" ? { type: "url", url: top.url } : { type: "upload", path: top.path },
      bottom:
        bottom.type === "url"
          ? { type: "url", url: bottom.url }
          : { type: "upload", path: bottom.path },
      seconds,
      script,
      voice,
      caption,
    });
  };

  return (
    <div className="mx-auto max-w-3xl px-6 py-8">
      <ToolHeader
        icon="🔲"
        title="Split Screen"
        desc="Stack a content clip over satisfying gameplay. Add a voiceover to narrate over both."
