        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">
            Bottom clip (gameplay / b-roll)
          </label>
          <div className="mt-2">
            <SourceInput value={bottom} onChange={setBottom} />
          </div>
        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">
            Length (seconds, when no voiceover)
