"use client";

import { useState } from "react";
import { ToolHeader } from "@/components/tool-ui";

export default function DownloaderTool() {
  const [url, setUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [result, setResult] = useState<{ assetId: string; title: string } | null>(null);

  const run = async () => {
    if (!url.trim()) return setErr("Paste a video URL.");
    setErr("");
    setBusy(true);
    setResult(null);
    try {
      const res = await fetch("/api/download", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "download failed");
      setResult(d);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "download failed");
    }
    setBusy(false);
  };

  return (
    <div className="mx-auto max-w-2xl px-6 py-8">
      <ToolHeader
        icon="⬇️"
        title="Video Downloader"
        desc="Download any public video from YouTube, TikTok, or Instagram."
      />
      <div className="card mt-6 p-5">
        <input
          className="field"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && run()}
          placeholder="https://…"
        />
        {err && <p className="mt-3 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
        <button className="btn btn-primary mt-4 w-full py-3" onClick={run} disabled={busy}>
          {busy ? "Downloading…" : "Download"}
        </button>
        {result && (
          <div className="surface2 mt-4 rounded-xl p-4 text-center">
            <p className="t-dim truncate text-sm">{result.title}</p>
            <a className="btn btn-primary mt-3 w-full py-2.5" href={`/api/assets/${result.assetId}`}>
              Save video (.mp4)
            </a>
          </div>
        )}
      </div>
      <p className="t-mute mt-4 text-xs">
        Note: YouTube and Instagram need a proxy or account cookies configured on the server;
        TikTok works out of the box.
      </p>
    </div>
  );
}

