"use client";

import { useState } from "react";
import { ToolHeader } from "@/components/tool-ui";

interface Result {
  id: string;
  title: string;
  url: string;
  channel: string;
  views: number;
  duration: number;
  thumbnail: string | null;
}

function fmtViews(n: number): string {
  if (n >= 1e6) return (n / 1e6).toFixed(1) + "M";
  if (n >= 1e3) return (n / 1e3).toFixed(1) + "K";
  return String(n);
}
function fmtDur(s: number): string {
  if (!s) return "";
  const m = Math.floor(s / 60);
  return `${m}:${String(s % 60).padStart(2, "0")}`;
}

export default function ResearchTool() {
  const [query, setQuery] = useState("");
  const [shorts, setShorts] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [results, setResults] = useState<Result[] | null>(null);
  const [copied, setCopied] = useState("");

  const run = async () => {
    if (!query.trim()) return setErr("Enter a niche or topic.");
    setErr("");
    setBusy(true);
    setResults(null);
    try {
      const res = await fetch("/api/research", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query, shorts }),
      });
      const d = await res.json();
      if (!res.ok) throw new Error(d.error || "search failed");
      setResults(d.results);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "search failed");
    }
    setBusy(false);
  };

  return (
    <div className="mx-auto max-w-3xl px-6 py-8">
      <ToolHeader
        icon="🔎"
        title="Content Research"
        desc="Find high-performing videos in any niche — ranked by views so the winning ideas surface first. Copy a URL straight into the Ranking or Commentary tools."
      />
      <div className="card mt-6 p-5">
        <div className="flex gap-2">
          <input
            className="field"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && run()}
            placeholder="e.g. snake attacks, gym fails, space facts…"
          />
          <button className="btn btn-primary whitespace-nowrap px-5" onClick={run} disabled={busy}>
            {busy ? "Searching…" : "Search"}
          </button>
        </div>
        <label className="t-dim mt-3 flex items-center gap-2 text-sm">
          <input type="checkbox" checked={shorts} onChange={(e) => setShorts(e.target.checked)} />
          Shorts only
        </label>
        {err && <p className="mt-3 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
      </div>

      {results && (
        <div className="mt-5 space-y-2">
          {results.length === 0 && <p className="t-dim text-sm">No results — try another query.</p>}
          {results.map((r, i) => (
            <div key={r.id || i} className="card flex items-center gap-3 p-3">
              <span className="t-accent font-display w-7 text-center font-bold">{i + 1}</span>
              {r.thumbnail && (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={r.thumbnail} alt="" className="h-14 w-24 rounded object-cover" />
              )}
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{r.title}</p>
                <p className="t-dim truncate text-xs">
                  {r.channel} · {fmtViews(r.views)} views{r.duration ? ` · ${fmtDur(r.duration)}` : ""}
                </p>
              </div>
              <button
                className="btn btn-ghost px-3 py-1.5 text-xs"
                onClick={() => {
                  navigator.clipboard?.writeText(r.url);
                  setCopied(r.id);
                  setTimeout(() => setCopied(""), 1200);
                }}
              >
                {copied === r.id ? "Copied ✓" : "Copy URL"}
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

