/** The tool catalog — mirrors Viblo's left sidebar. `ready` marks what's
    been built so the UI can show "coming soon" for the rest. */
export interface Tool {
  id: string;
  name: string;
  icon: string;
  desc: string;
  ready: boolean;
}

export const TOOLS: Tool[] = [
  { id: "text-story", name: "Text Story", icon: "💬", desc: "Fake chat conversations (iMessage, WhatsApp, Tinder…) over b-roll.", ready: false },
  { id: "video-story", name: "Video Story", icon: "📱", desc: "Narrated story with a social widget over gameplay footage.", ready: false },
  { id: "commentary", name: "Video Commentary", icon: "🎙️", desc: "Paste a URL or upload a clip → AI commentary + captions.", ready: false },
  { id: "ranking", name: "Video Ranking", icon: "🏆", desc: "Top-5 countdowns built from YouTube / TikTok / IG clips.", ready: true },
  { id: "split-screen", name: "Split Screen", icon: "🔲", desc: "Your content stacked over satisfying gameplay.", ready: false },
  { id: "auto-clip", name: "Auto Clipping", icon: "✂️", desc: "Turn a long video into multiple viral shorts.", ready: false },
  { id: "voiceover", name: "AI Voiceover", icon: "🔊", desc: "Natural neural voices with word-timed output.", ready: false },
  { id: "transcriber", name: "Video Transcriber", icon: "📝", desc: "Accurate transcripts and subtitles from any video.", ready: false },
  { id: "image-gen", name: "AI Image Generator", icon: "🖼️", desc: "Generate images for thumbnails and b-roll.", ready: false },
  { id: "video-gen", name: "AI Video Generator", icon: "🎬", desc: "Text-to-video and image-to-video clips.", ready: false },
  { id: "downloader", name: "Video Downloader", icon: "⬇️", desc: "Download from YouTube, TikTok, and Instagram.", ready: false },
  { id: "research", name: "Content Research", icon: "🔎", desc: "Find winning shorts channels and their best ideas.", ready: false },
