import { db } from "./db";
import { isAdmin } from "./auth";
import type { User } from "@prisma/client";

/* Credit costs per action. Admins bypass all of this. */
export const COSTS = {
  render: 1, // one rendered export
} as const;

export interface CreditCheck {
  ok: boolean;
  reason?: string;
}

/** Whether the user can afford an action (admins always can). */
export function canAfford(user: User, cost: number): CreditCheck {
  if (isAdmin(user)) return { ok: true };
  if (user.credits < cost) {
    return { ok: false, reason: `Not enough credits (need ${cost}, have ${user.credits}).` };
  }
  return { ok: true };
}

/** Deduct credits and record the ledger entry. No-op for admins. */
export async function spend(user: User, cost: number, reason: string): Promise<void> {
  if (isAdmin(user) || cost <= 0) return;
  await db.$transaction([
    db.user.update({ where: { id: user.id }, data: { credits: { decrement: cost } } }),
    db.creditLedger.create({ data: { userId: user.id, delta: -cost, reason } }),
  ]);
}

