import { createReadStream, statSync } from "fs";
import path from "path";
import { Readable } from "stream";
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";

const DATA_DIR = process.env.RENDER_DATA_DIR || "/data";

/** Stream a rendered asset (video/srt) to the owner. */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;

  const asset = await db.asset.findUnique({
    where: { id },
    include: { project: { select: { userId: true, title: true } } },
  });
  if (!asset || asset.project?.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const abs = path.resolve(DATA_DIR, asset.path);
  if (!abs.startsWith(path.resolve(DATA_DIR) + path.sep)) {
    return NextResponse.json({ error: "invalid path" }, { status: 400 });
  }

  let size: number;
  try {
    size = statSync(abs).size;
  } catch {
    return NextResponse.json({ error: "file missing" }, { status: 404 });
  }

  const slug = (asset.project?.title || "vidforge").replace(/\W+/g, "-").toLowerCase();
  const ext = asset.kind === "srt" ? "srt" : "mp4";
  const type = asset.kind === "srt" ? "text/plain; charset=utf-8" : "video/mp4";
  const stream = Readable.toWeb(createReadStream(abs)) as ReadableStream;
  return new NextResponse(stream, {
    headers: {
      "Content-Type": type,
      "Content-Length": String(size),
      "Content-Disposition": `attachment; filename="${slug}.${ext}"`,
    },
  });
}

