import { writeFile, mkdir } from "fs/promises";
import path from "path";
import { randomUUID } from "crypto";

/* Replicate adapter for AI image/video generation. Activates when
   REPLICATE_API_TOKEN is set (the box has no GPU, so generation is hosted).
   Downloads the output into the shared media volume and returns a relative
   path the asset route can serve. */

const TOKEN = process.env.REPLICATE_API_TOKEN || "";
const DATA_DIR = process.env.RENDER_DATA_DIR || "/data";

export const replicateReady = Boolean(TOKEN);

interface Prediction {
  id: string;
  status: "starting" | "processing" | "succeeded" | "failed" | "canceled";
  output: string | string[] | null;
  error: string | null;
  urls: { get: string };
}

async function poll(url: string): Promise<Prediction> {
  for (let i = 0; i < 120; i++) {
    const res = await fetch(url, { headers: { Authorization: `Bearer ${TOKEN}` }, cache: "no-store" });
    const p = (await res.json()) as Prediction;
    if (p.status === "succeeded" || p.status === "failed" || p.status === "canceled") return p;
    await new Promise((r) => setTimeout(r, 2000));
  }
  throw new Error("generation timed out");
}

/** Runs an official Replicate model and downloads the first output file.
    Returns { rel } path under RENDER_DATA_DIR. */
export async function runModel(
  model: string,
  input: Record<string, unknown>,
  kind: "image" | "video",
): Promise<{ rel: string }> {
  if (!TOKEN) throw new Error("REPLICATE_API_TOKEN not configured");
  const create = await fetch(`https://api.replicate.com/v1/models/${model}/predictions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ input }),
  });
  if (!create.ok) {
    const t = await create.text();
    throw new Error(`Replicate error (${create.status}): ${t.slice(0, 200)}`);
  }
  const created = (await create.json()) as Prediction;
  const done = await poll(created.urls.get);
  if (done.status !== "succeeded" || !done.output) {
    throw new Error(done.error || "generation failed");
  }
  const outUrl = Array.isArray(done.output) ? done.output[0] : done.output;
  const bin = await fetch(outUrl);
  const buf = Buffer.from(await bin.arrayBuffer());
  const ext = kind === "image" ? "png" : "mp4";
  const rel = path.join("generated", `${randomUUID()}.${ext}`);
  const abs = path.join(DATA_DIR, rel);
  await mkdir(path.dirname(abs), { recursive: true });
  await writeFile(abs, buf);
  return { rel };
}

