import { NextResponse } from "next/server";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";
import { canAfford, COSTS, spend } from "@/lib/credits";
import { replicateReady, runModel } from "@/lib/replicate";

const IMAGE_MODEL = process.env.REPLICATE_IMAGE_MODEL || "black-forest-labs/flux-schnell";
const VIDEO_MODEL = process.env.REPLICATE_VIDEO_MODEL || "minimax/video-01";

/** AI image/video generation via a hosted provider (Replicate). Gated on a
    provider key — this box has no GPU. */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  if (!replicateReady) {
    return NextResponse.json(
      {
        error:
          "AI generation isn't connected yet. Add a REPLICATE_API_TOKEN on the server to enable image/video generation.",
        needsKey: true,
      },
      { status: 503 },
    );
  }

  let body: { kind?: "image" | "video"; prompt?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const prompt = (body.prompt || "").trim();
  const kind = body.kind === "video" ? "video" : "image";
  if (!prompt) return NextResponse.json({ error: "prompt required" }, { status: 400 });

  const afford = canAfford(user, COSTS.generate);
  if (!afford.ok) return NextResponse.json({ error: afford.reason }, { status: 403 });

  try {
    const { rel } = await runModel(
      kind === "video" ? VIDEO_MODEL : IMAGE_MODEL,
      { prompt },
      kind,
    );
    const project = await db.project.create({
      data: {
        userId: user.id,
        type: kind === "video" ? "video_gen" : "image_gen",
        title: prompt.slice(0, 60),
        config: { prompt } as Prisma.InputJsonValue,
        status: "done",
      },
    });
    const asset = await db.asset.create({
      data: { projectId: project.id, kind, path: rel },
    });
    await spend(user, COSTS.generate, `generate:${kind}`);
    return NextResponse.json({ assetId: asset.id, kind });
  } catch (e) {
    return NextResponse.json(
      { error: e instanceof Error ? e.message : "generation failed" },
      { status: 502 },
    );
  }
}

