"use client";

import { useState } from "react";
import { RenderResult, useRender } from "@/lib/useRender";
import { CaptionPicker, SourceInput, ToolHeader, type Source } from "@/components/tool-ui";

export default function AutoClipTool() {
  const { job, busy, err, setErr, start } = useRender();
  const [source, setSource] = useState<Source>(null);
  const [count, setCount] = useState(3);
  const [clipLen, setClipLen] = useState(30);
  const [caption, setCaption] = useState("pop");

  const run = () => {
    if (!source) return setErr("Add a long video (URL or upload).");
    start("auto_clip", "Auto clips", {
      source: source.type === "url" ? { type: "url", url: source.url } : { type: "upload", path: source.path },
      count,
      clipLen,
      caption,
    });
  };

  return (
    <div className="mx-auto max-w-2xl px-6 py-8">
      <ToolHeader
        icon="✂️"
        title="Auto Clipping"
        desc="Turn a long video into several vertical shorts, each auto-captioned."
      />
      <div className="card mt-6 space-y-5 p-5">
        <SourceInput value={source} onChange={setSource} placeholder="Long-form video URL" />
        <div className="grid gap-4 sm:grid-cols-3">
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">Clips</label>
            <input className="field mt-2" type="number" min={1} max={6} value={count} onChange={(e) => setCount(Number(e.target.value) || 3)} />
          </div>
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">Each (sec)</label>
            <input className="field mt-2" type="number" min={10} max={60} value={clipLen} onChange={(e) => setClipLen(Number(e.target.value) || 30)} />
          </div>
          <CaptionPicker value={caption} onChange={setCaption} />
        </div>
      </div>
      {err && <p className="mt-4 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
      <button className="btn btn-primary mt-5 w-full py-3" onClick={run} disabled={busy}>
        {busy ? "Clipping…" : "Generate clips"}
      </button>
      <RenderResult job={job} />
    </div>
  );
}

