"use client";

import { useState } from "react";
import { ToolHeader } from "@/components/tool-ui";

export default function ImageGenTool() {
  const [prompt, setPrompt] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [needsKey, setNeedsKey] = useState(false);
  const [assetId, setAssetId] = useState("");

  const run = async () => {
    if (!prompt.trim()) return setErr("Describe the image you want.");
    setErr("");
    setNeedsKey(false);
    setBusy(true);
    setAssetId("");
    try {
      const res = await fetch("/api/generate-media", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ kind: "image", prompt }),
      });
      const d = await res.json();
      if (!res.ok) {
        if (d.needsKey) setNeedsKey(true);
        throw new Error(d.error || "generation failed");
      }
      setAssetId(d.assetId);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "generation failed");
    }
    setBusy(false);
  };

  return (
    <div className="mx-auto max-w-2xl px-6 py-8">
      <ToolHeader
        icon="🖼️"
        title="AI Image Generator"
        desc="Generate images for thumbnails and b-roll from a text prompt."
      />
      <div className="card mt-6 p-5">
        <textarea
          className="field"
          rows={3}
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="A dramatic cinematic thumbnail of a cobra mid-strike, neon lighting…"
        />
        {err && !needsKey && <p className="mt-3 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
        <button className="btn btn-primary mt-4 w-full py-3" onClick={run} disabled={busy}>
          {busy ? "Generating…" : "Generate image"}
        </button>
        {needsKey && (
          <div className="surface2 mt-4 rounded-xl p-4 text-sm">
            <p className="font-semibold">Generation provider not connected</p>
            <p className="t-dim mt-1">
              This server has no GPU, so image/video generation runs through a hosted provider. Add
              a <code>REPLICATE_API_TOKEN</code> to the server&apos;s environment to enable it.
            </p>
          </div>
        )}
        {assetId && (
          <div className="mt-4">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={`/api/assets/${assetId}`} alt={prompt} className="w-full rounded-xl" />
            <a className="btn btn-ghost mt-3 w-full py-2.5" href={`/api/assets/${assetId}`}>
              Download image
            </a>
          </div>
        )}
      </div>
    </div>
  );
}

