.vf-phone {
  aspect-ratio: 9 / 16;
  border-radius: 1.4rem;
  border: 6px solid #2b2344;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  position: relative;
  background: #0a0a12;
}
