export function LivePreview({ segments, width = 250 }: { segments: PreviewSegment[]; width?: number }) {
  const [playing, setPlaying] = useState(false);
  const [idx, setIdx] = useState(0);
  const [hot, setHot] = useState(-1);
  const stopped = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const stop = useCallback(() => {
    stopped.current = true;
    if (timer.current) clearTimeout(timer.current);
    try {
      window.speechSynthesis.cancel();
    } catch {
      /* no speech */
    }
    setPlaying(false);
    setHot(-1);
  }, []);

  useEffect(() => () => stop(), [stop]);
  // Reset to the first frame whenever the edit changes the segment count.
  useEffect(() => {
    if (!playing) setIdx(0);
  }, [segments.length, playing]);

  const speakSeg = useCallback(
    (i: number) => {
      if (stopped.current || i >= segments.length) {
        setPlaying(false);
        setHot(-1);
        return;
      }
      setIdx(i);
      setHot(-1);
      const seg = segments[i];
      const speakText = seg.chat ? seg.chat.messages[seg.chat.upto]?.text : seg.narration;
      const hasSpeech = typeof window !== "undefined" && "speechSynthesis" in window;

      if (speakText && hasSpeech) {
        const u = new SpeechSynthesisUtterance(speakText);
        u.rate = seg.rate ?? 1;
        u.pitch = seg.pitch ?? 1;
        if (seg.narration) {
          u.onboundary = (e) => {
            if (e.charIndex !== undefined) {
              setHot(Math.max(0, wordsOf(seg.narration!.slice(0, e.charIndex)).length));
            }
          };
        }
        u.onend = () => speakSeg(i + 1);
        u.onerror = () => speakSeg(i + 1);
        window.speechSynthesis.speak(u);
      } else {
        const secs = seg.estSeconds ?? (speakText ? wordsOf(speakText).length / 2.4 : 2);
        timer.current = setTimeout(() => speakSeg(i + 1), Math.max(700, secs * 1000));
      }
    },
    [segments],
  );

  const play = () => {
    if (playing) {
      stop();
      return;
    }
    stop();
    stopped.current = false;
    setPlaying(true);
    speakSeg(0);
  };

  const seg = segments[Math.min(idx, segments.length - 1)] || segments[0];

