"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/* In-browser approximation of the rendered video: plays each segment with the
   browser speech engine, highlighting caption words karaoke-style and
   revealing chat messages. Clip backgrounds (server-downloaded) show a
   labelled placeholder — the real footage appears in the final render. */

export interface ChatMsg {
  from: "me" | "them";
  text: string;
}

export interface PreviewSegment {
  gradIdx: number;
  clipLabel?: string; // when the background is a downloaded clip
  captionStyle?: string; // pop | clean | neon | mono
  narration?: string; // spoken + shown as karaoke captions
  title?: string; // persistent top overlay (ranking)
  rank?: number; // big rank number (ranking)
  chat?: { contact: string; dark: boolean; messages: ChatMsg[]; upto: number };
  rate?: number;
  pitch?: number;
  estSeconds?: number; // duration when there's nothing to speak
}

/** Browser voice character per narrator preset (matches the engine's intent). */
export const VOICE_FX: Record<string, { rate: number; pitch: number }> = {
  atlas: { rate: 0.85, pitch: 0.7 },
  nova: { rate: 1.12, pitch: 1.3 },
  ash: { rate: 0.98, pitch: 1.0 },
  rumor: { rate: 1.2, pitch: 0.85 },
  ivy: { rate: 1.0, pitch: 1.15 },
};

const wordsOf = (t: string) => t.trim().split(/\s+/).filter(Boolean);

function CaptionLine({ text, hot, style }: { text: string; hot: number; style: string }) {
  const words = wordsOf(text);
  return (
    <div
      className={`cap-${style || "pop"}`}
      style={{ position: "absolute", bottom: "16%", left: 0, right: 0, textAlign: "center", fontSize: ".82rem", lineHeight: 1.25, padding: "0 .6rem" }}
    >
      {words.map((w, i) => (
        <span key={i} className={i === hot ? "hot" : ""}>
          {w}
          {i < words.length - 1 ? " " : ""}
        </span>
      ))}
    </div>
  );
}

export function LivePreview({ segments, width = 250 }: { segments: PreviewSegment[]; width?: number }) {
  const [playing, setPlaying] = useState(false);
  const [idx, setIdx] = useState(0);
  const [hot, setHot] = useState(-1);
  const stopped = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const stop = useCallback(() => {
    stopped.current = true;
    if (timer.current) clearTimeout(timer.current);
    try {
      window.speechSynthesis.cancel();
    } catch {
      /* no speech */
    }
    setPlaying(false);
    setHot(-1);
  }, []);

  useEffect(() => () => stop(), [stop]);

  const play = () => {
    if (playing) {
      stop();
      return;
    }
    stop();
    stopped.current = false;
    setPlaying(true);
    const segs = segments;
    // Local declaration so the recursion can reference itself safely.
    const step = (i: number) => {
      if (stopped.current || i >= segs.length) {
        setPlaying(false);
        setHot(-1);
        return;
      }
      setIdx(i);
      setHot(-1);
      const s = segs[i];
      const speakText = s.chat ? s.chat.messages[s.chat.upto]?.text : s.narration;
      const hasSpeech = typeof window !== "undefined" && "speechSynthesis" in window;
      if (speakText && hasSpeech) {
        const u = new SpeechSynthesisUtterance(speakText);
        u.rate = s.rate ?? 1;
        u.pitch = s.pitch ?? 1;
        if (s.narration) {
          u.onboundary = (e) => {
            if (e.charIndex !== undefined) {
              setHot(Math.max(0, wordsOf(s.narration!.slice(0, e.charIndex)).length));
            }
          };
        }
        u.onend = () => step(i + 1);
        u.onerror = () => step(i + 1);
        window.speechSynthesis.speak(u);
      } else {
        const secs = s.estSeconds ?? (speakText ? wordsOf(speakText).length / 2.4 : 2);
        timer.current = setTimeout(() => step(i + 1), Math.max(700, secs * 1000));
      }
    };
    step(0);
  };

  // When idle, always show the first frame; while playing, follow the engine.
  const seg = segments[Math.min(playing ? idx : 0, segments.length - 1)] || segments[0];
  if (!seg) {
    return (
      <div className="vf-phone" style={{ width }}>
        <div className="vf-cliplabel">Add content to preview</div>
      </div>
    );
  }

  return (
    <div style={{ width }}>
      <div className={`vf-phone ${seg.clipLabel ? "" : `vf-grad-${seg.gradIdx % 6}`}`}>
        {seg.clipLabel && <div className="vf-cliplabel">🎬 {seg.clipLabel}</div>}
        {seg.title && <div className="vf-title">{seg.title}</div>}
        {seg.rank !== undefined && <div className="vf-rank">#{seg.rank}</div>}

        {seg.chat && (
          <div className={`vf-chat ${seg.chat.dark ? "dark" : ""}`}>
            <div className="vf-chat-head">
              <span className="vf-chat-av">{(seg.chat.contact[0] || "?").toUpperCase()}</span>
              <span className="vf-chat-name">{seg.chat.contact}</span>
            </div>
            {seg.chat.messages.slice(0, seg.chat.upto + 1).map((m, i) => (
              <div key={i} className={`vf-msg ${m.from}`}>
                <span className="vf-bubble">{m.text}</span>
              </div>
            ))}
          </div>
        )}

        {seg.narration && <CaptionLine text={seg.narration} hot={hot} style={seg.captionStyle || "pop"} />}

        <div style={{ position: "absolute", bottom: ".5rem", left: 0, right: 0, display: "flex", justifyContent: "center" }}>
          <button
            onClick={play}
            aria-label={playing ? "Stop preview" : "Play preview"}
            style={{
              width: 40, height: 40, borderRadius: 999, border: "none", cursor: "pointer",
              background: "linear-gradient(135deg,var(--accent),var(--accent-2))", color: "#fff", fontSize: 16,
            }}
          >
            {playing ? "■" : "▶"}
          </button>
        </div>
      </div>
      <p className="t-mute mt-2 text-center text-xs">
        Preview {segments.length > 1 ? `· scene ${Math.min(idx + 1, segments.length)}/${segments.length}` : ""} · approximate
      </p>
    </div>
  );
}

