@import "tailwindcss";

:root {
  --bg: #0b0b12;
  --surface: #14141f;
  --surface2: #1c1c2b;
  --line: #2a2a3d;
  --text: #ecebf5;
  --text-dim: #a09fc0;
  --text-mute: #6f6e8f;
  --accent: #6d5cf5;
  --accent-2: #8b7bff;
  --good: #35c98b;
  --warn: #ffb020;
}

html,
body {
  background: var(--bg);
  color: var(--text);
}

body {
  font-family: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.font-display {
  font-family: var(--font-display), var(--font-sans), sans-serif;
  letter-spacing: -0.02em;
}

.surface { background: var(--surface); }
.surface2 { background: var(--surface2); }
.b-line { border-color: var(--line); }
.t-dim { color: var(--text-dim); }
.t-mute { color: var(--text-mute); }
.t-accent { color: var(--accent-2); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  border-radius: 0.7rem;
  cursor: pointer;
  border: none;
  transition: transform 0.1s ease, opacity 0.1s ease, background 0.1s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn:disabled { opacity: 0.5; cursor: default; transform: none; }
.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #fff;
  box-shadow: 0 8px 24px rgba(109, 92, 245, 0.32);
}
.btn-ghost {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--line);
}

.field {
  background: var(--surface2);
  border: 1px solid var(--line);
  color: var(--text);
  border-radius: 0.6rem;
  padding: 0.7rem 0.9rem;
  width: 100%;
  outline: none;
}
.field:focus { border-color: var(--accent); }
.field::placeholder { color: var(--text-mute); }

.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1rem;
}

/* ============================================================
   Live preview — a 9:16 phone that plays an approximation of the
   video in-browser while editing. Caption styles mirror the render
   engine (services/worker/engine/captions.py).
   ============================================================ */
.vf-phone {
  aspect-ratio: 9 / 16;
  border-radius: 1.4rem;
  border: 6px solid #2b2344;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  position: relative;
  background: #0a0a12;
}
.vf-grad-0 { background: linear-gradient(160deg, #3b2d7a, #12102a); }
.vf-grad-1 { background: linear-gradient(160deg, #7a2d55, #1c0f22); }
.vf-grad-2 { background: linear-gradient(160deg, #2d5f7a, #0f1622); }
.vf-grad-3 { background: linear-gradient(160deg, #7a5a2d, #221a0f); }
.vf-grad-4 { background: linear-gradient(160deg, #2d7a52, #0f2218); }
.vf-grad-5 { background: linear-gradient(160deg, #5a2d7a, #180f22); }

.vf-cliplabel {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.2rem;
  text-align: center;
  color: #cbd0ff;
  font-size: 0.72rem;
  opacity: 0.85;
  background: repeating-linear-gradient(45deg, #1a1730, #1a1730 12px, #201c38 12px, #201c38 24px);
}

/* Caption styles (karaoke: .hot = the word currently spoken) */
.cap-pop { font-family: var(--font-display), sans-serif; font-weight: 800; color: #fff; text-shadow: 0 2px 0 #000, 0 0 12px rgba(0,0,0,.6); }
.cap-pop .hot { color: #ffd23f; }
.cap-clean { font-weight: 700; color: #fff; background: rgba(0,0,0,.5); border-radius: .4rem; padding: .1em .35em; }
.cap-clean .hot { text-decoration: underline; text-decoration-color: #8b7bff; text-decoration-thickness: 3px; }
.cap-neon { font-family: var(--font-display), sans-serif; font-weight: 800; color: #ffe9fd; text-shadow: 0 0 8px #ff4fd8, 0 0 18px #ff4fd8; }
.cap-neon .hot { color: #fff; }
.cap-mono { font-family: ui-monospace, Menlo, monospace; font-weight: 700; color: #d6ffe1; background: rgba(6,20,10,.7); padding: .1em .35em; border-radius: .25rem; }
.cap-mono .hot { color: #ffd23f; }

.vf-title {
  position: absolute; top: 5%; left: 0; right: 0; text-align: center;
  font-family: var(--font-display), sans-serif; font-weight: 800; color: #fff;
  text-shadow: 0 2px 0 #000; font-size: 1.05rem; padding: 0 .5rem;
}
.vf-rank {
  position: absolute; top: 16%; left: 0; right: 0; text-align: center;
  font-family: var(--font-display), sans-serif; font-weight: 800; color: #ffd23f;
  text-shadow: 0 2px 4px #000; font-size: 2.6rem;
}

/* Chat card (text story) */
.vf-chat { position: absolute; left: 6%; right: 6%; top: 50%; transform: translateY(-50%);
  border-radius: 1rem; padding: .7rem .7rem 1rem; background: rgba(255,255,255,.94); }
.vf-chat.dark { background: rgba(28,28,34,.94); }
.vf-chat-head { display: flex; align-items: center; gap: .4rem; padding-bottom: .5rem; margin-bottom: .5rem; border-bottom: 1px solid rgba(0,0,0,.1); }
.vf-chat.dark .vf-chat-head { border-color: rgba(255,255,255,.12); }
.vf-chat-av { width: 1.5rem; height: 1.5rem; border-radius: 999px; background: #0b93f6; color: #fff; display: flex; align-items: center; justify-content: center; font-size: .7rem; font-weight: 700; }
.vf-chat-name { font-weight: 700; font-size: .8rem; color: #16161a; }
.vf-chat.dark .vf-chat-name { color: #f0f0f5; }
.vf-msg { display: flex; margin-top: .35rem; }
.vf-msg.me { justify-content: flex-end; }
.vf-bubble { max-width: 78%; padding: .35rem .55rem; border-radius: .9rem; font-size: .72rem; line-height: 1.25; }
.vf-msg.them .vf-bubble { background: #e9e9eb; color: #141416; }
.vf-chat.dark .vf-msg.them .vf-bubble { background: #3a3a40; color: #ebebf0; }
.vf-msg.me .vf-bubble { background: #0b93f6; color: #fff; }

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/* In-browser approximation of the rendered video: plays each segment with the
   browser speech engine, highlighting caption words karaoke-style and
   revealing chat messages. Clip backgrounds (server-downloaded) show a
   labelled placeholder — the real footage appears in the final render. */

export interface ChatMsg {
  from: "me" | "them";
  text: string;
}

export interface PreviewSegment {
  gradIdx: number;
  clipLabel?: string; // when the background is a downloaded clip
  captionStyle?: string; // pop | clean | neon | mono
  narration?: string; // spoken + shown as karaoke captions
  title?: string; // persistent top overlay (ranking)
  rank?: number; // big rank number (ranking)
  chat?: { contact: string; dark: boolean; messages: ChatMsg[]; upto: number; style?: string };
  rate?: number;
  pitch?: number;
  estSeconds?: number; // duration when there's nothing to speak
}

/** me-bubble background + accent per chat skin (preview approximation). */
export const CHAT_STYLE: Record<string, { me: string; accent: string; meText: string }> = {
  imessage: { me: "#0a84ff", accent: "#0a84ff", meText: "#fff" },
  whatsapp: { me: "#25d366", accent: "#075e54", meText: "#0b140f" },
  instagram: { me: "linear-gradient(160deg,#ff814f,#d62976,#962fbf)", accent: "#d62976", meText: "#fff" },
  tinder: { me: "#fd3c6a", accent: "#fd297b", meText: "#fff" },
  messenger: { me: "#0084ff", accent: "#0084ff", meText: "#fff" },
};

/** Browser voice character per narrator preset (matches the engine's intent). */
export const VOICE_FX: Record<string, { rate: number; pitch: number }> = {
  atlas: { rate: 0.92, pitch: 0.9 },
  nova: { rate: 1.08, pitch: 1.08 },
  ash: { rate: 1.0, pitch: 1.0 },
  rumor: { rate: 1.12, pitch: 0.98 },
  ivy: { rate: 1.0, pitch: 1.05 },
};

const wordsOf = (t: string) => t.trim().split(/\s+/).filter(Boolean);

function CaptionLine({ text, hot, style }: { text: string; hot: number; style: string }) {
  const words = wordsOf(text);
  return (
    <div
      className={`cap-${style || "pop"}`}
      style={{ position: "absolute", bottom: "16%", left: 0, right: 0, textAlign: "center", fontSize: ".82rem", lineHeight: 1.25, padding: "0 .6rem" }}
    >
      {words.map((w, i) => (
        <span key={i} className={i === hot ? "hot" : ""}>
          {w}
          {i < words.length - 1 ? " " : ""}
        </span>
      ))}
    </div>
  );
}

export function LivePreview({ segments, width = 250 }: { segments: PreviewSegment[]; width?: number }) {
  const [playing, setPlaying] = useState(false);
  const [idx, setIdx] = useState(0);
  const [hot, setHot] = useState(-1);
  const stopped = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const stop = useCallback(() => {
    stopped.current = true;
    if (timer.current) clearTimeout(timer.current);
    try {
      window.speechSynthesis.cancel();
    } catch {
      /* no speech */
    }
    setPlaying(false);
    setHot(-1);
  }, []);

  useEffect(() => () => stop(), [stop]);

  const play = () => {
    if (playing) {
      stop();
      return;
    }
    stop();
    stopped.current = false;
    setPlaying(true);
    const segs = segments;
    // Local declaration so the recursion can reference itself safely.
    const step = (i: number) => {
      if (stopped.current || i >= segs.length) {
        setPlaying(false);
        setHot(-1);
        return;
      }
      setIdx(i);
      setHot(-1);
      const s = segs[i];
      const speakText = s.chat ? s.chat.messages[s.chat.upto]?.text : s.narration;
      const hasSpeech = typeof window !== "undefined" && "speechSynthesis" in window;
      if (speakText && hasSpeech) {
        const u = new SpeechSynthesisUtterance(speakText);
        u.rate = s.rate ?? 1;
        u.pitch = s.pitch ?? 1;
        if (s.narration) {
          u.onboundary = (e) => {
            if (e.charIndex !== undefined) {
              setHot(Math.max(0, wordsOf(s.narration!.slice(0, e.charIndex)).length));
            }
          };
        }
        u.onend = () => step(i + 1);
        u.onerror = () => step(i + 1);
        window.speechSynthesis.speak(u);
      } else {
        const secs = s.estSeconds ?? (speakText ? wordsOf(speakText).length / 2.4 : 2);
        timer.current = setTimeout(() => step(i + 1), Math.max(700, secs * 1000));
      }
    };
    step(0);
  };

  // When idle, always show the first frame; while playing, follow the engine.
  const seg = segments[Math.min(playing ? idx : 0, segments.length - 1)] || segments[0];
  if (!seg) {
    return (
      <div className="vf-phone" style={{ width }}>
        <div className="vf-cliplabel">Add content to preview</div>
      </div>
    );
  }

  return (
    <div style={{ width }}>
      <div className={`vf-phone ${seg.clipLabel ? "" : `vf-grad-${seg.gradIdx % 6}`}`}>
        {seg.clipLabel && <div className="vf-cliplabel">🎬 {seg.clipLabel}</div>}
        {seg.title && <div className="vf-title">{seg.title}</div>}
        {seg.rank !== undefined && <div className="vf-rank">#{seg.rank}</div>}

        {seg.chat && (
          <div className={`vf-chat ${seg.chat.dark ? "dark" : ""}`}>
            <div className="vf-chat-head">
              <span
                className="vf-chat-av"
                style={{ background: CHAT_STYLE[seg.chat.style || "imessage"]?.accent }}
              >
                {(seg.chat.contact[0] || "?").toUpperCase()}
              </span>
              <span className="vf-chat-name">{seg.chat.contact}</span>
            </div>
            {seg.chat.messages.slice(0, seg.chat.upto + 1).map((m, i) => {
              const cs = CHAT_STYLE[seg.chat!.style || "imessage"];
              return (
                <div key={i} className={`vf-msg ${m.from}`}>
                  <span
                    className="vf-bubble"
                    style={m.from === "me" ? { background: cs.me, color: cs.meText } : undefined}
                  >
                    {m.text}
                  </span>
                </div>
              );
            })}
          </div>
        )}

        {seg.narration && <CaptionLine text={seg.narration} hot={hot} style={seg.captionStyle || "pop"} />}

        <div style={{ position: "absolute", bottom: ".5rem", left: 0, right: 0, display: "flex", justifyContent: "center" }}>
          <button
            onClick={play}
            aria-label={playing ? "Stop preview" : "Play preview"}
            style={{
              width: 40, height: 40, borderRadius: 999, border: "none", cursor: "pointer",
              background: "linear-gradient(135deg,var(--accent),var(--accent-2))", color: "#fff", fontSize: 16,
            }}
          >
            {playing ? "■" : "▶"}
          </button>
        </div>
      </div>
      <p className="t-mute mt-2 text-center text-xs">
        Preview {segments.length > 1 ? `· scene ${Math.min(idx + 1, segments.length)}/${segments.length}` : ""} · approximate
      </p>
    </div>
  );
}

