import { NextResponse } from "next/server";
import { getSessionUser } from "@/lib/auth";

const PEXELS_KEY = process.env.PEXELS_API_KEY || "";

/** Stock background video search (Pexels, free key). Portrait clips for use
    as tool backgrounds. Gated on PEXELS_API_KEY. */
export async function GET(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!PEXELS_KEY) return NextResponse.json({ enabled: false, results: [] });

  const q = new URL(request.url).searchParams.get("q") || "satisfying";
  try {
    const res = await fetch(
      `https://api.pexels.com/videos/search?query=${encodeURIComponent(q)}&per_page=16&orientation=portrait&size=medium`,
      { headers: { Authorization: PEXELS_KEY }, cache: "no-store" },
    );
    if (!res.ok) return NextResponse.json({ enabled: true, results: [] });
    const data = await res.json();
    const results = (data.videos || [])
      .map((v: { image: string; video_files: { link: string; width: number; height: number }[] }) => {
        const portrait = v.video_files
          .filter((f) => f.height >= f.width && f.height >= 960)
          .sort((a, b) => a.height - b.height)[0];
        return portrait ? { thumbnail: v.image, url: portrait.link } : null;
      })
      .filter(Boolean);
    return NextResponse.json({ enabled: true, results });
  } catch {
    return NextResponse.json({ enabled: true, results: [] });
  }
}

