"use client";

import { useState } from "react";
import { RenderResult, useRender } from "@/lib/useRender";
import { LivePreview, VOICE_FX, type PreviewSegment } from "@/components/live-preview";
import { BackgroundPicker, type Background } from "@/components/background-picker";
import { ToolHeader, VoicePicker, generate } from "@/components/tool-ui";

interface Msg {
  from: "them" | "me";
  text: string;
}

const STYLES = [
  { id: "imessage", name: "iMessage" },
  { id: "whatsapp", name: "WhatsApp" },
  { id: "instagram", name: "Instagram" },
  { id: "tinder", name: "Tinder" },
  { id: "messenger", name: "Messenger" },
];

export default function TextStoryBuilder() {
  const { job, busy, err, setErr, start } = useRender();
  const [contact, setContact] = useState("Grace");
  const [style, setStyle] = useState("imessage");
  const [dark, setDark] = useState(false);
  const [voiceThem, setVoiceThem] = useState("ash");
  const [voiceMe, setVoiceMe] = useState("nova");
  const [bg, setBg] = useState<Background>({ type: "gradient", idx: 0 });
  const [topic, setTopic] = useState("");
  const [gen, setGen] = useState(false);
  const [messages, setMessages] = useState<Msg[]>([
    { from: "them", text: "you'll never guess what just happened" },
    { from: "me", text: "what?? tell me" },
  ]);

  const setMsg = (i: number, patch: Partial<Msg>) =>
    setMessages((ms) => ms.map((m, idx) => (idx === i ? { ...m, ...patch } : m)));

  const writeStory = async () => {
    if (!topic.trim()) return setErr("Add a topic for the AI to write a conversation about.");
    setGen(true);
    setErr("");
    try {
      const { result } = await generate("text-story", topic, "dramatic");
      setMessages(result as Msg[]);
    } catch {
      setErr("Couldn't generate the conversation.");
    }
    setGen(false);
  };

  const run = () => {
    const msgs = messages.filter((m) => m.text.trim());
    if (msgs.length < 2) return setErr("Add at least two messages.");
    const background = bg;
    start("text_story", contact ? `${contact} — text story` : "Text story", {
      contact,
      style,
      dark,
      voiceThem,
      voiceMe,
      background,
      messages: msgs,
    });
  };

  const shown = messages.filter((m) => m.text.trim());
  const bgLabel =
    bg.type === "clip" ? bg.label || "clip" : bg.type === "upload" ? bg.name : undefined;
  const bgIdx = bg.type === "gradient" ? bg.idx : 0;
  const previewSegments: PreviewSegment[] = shown.map((m, i) => ({
    gradIdx: bgIdx,
    clipLabel: bgLabel,
    chat: { contact, dark, messages: shown, upto: i, style },
    ...(m.from === "me" ? VOICE_FX[voiceMe] : VOICE_FX[voiceThem]),
  }));

  return (
    <div className="mx-auto max-w-5xl px-6 py-8">
      <ToolHeader
        icon="💬"
        title="Text Story"
        desc="A fake chat conversation that plays out message-by-message over gameplay, fully voiced."
      />
      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_270px]">
        <div>
      <div className="card space-y-5 p-5">
        <div className="grid gap-4 sm:grid-cols-2">
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">Contact name</label>
            <input className="field mt-2" value={contact} onChange={(e) => setContact(e.target.value)} />
          </div>
          <label className="flex items-end gap-2 pb-2 text-sm">
            <input type="checkbox" checked={dark} onChange={(e) => setDark(e.target.checked)} />
            Dark mode bubbles
          </label>
        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">Chat style</label>
          <div className="mt-2 flex flex-wrap gap-2">
            {STYLES.map((s) => (
              <button
                key={s.id}
                onClick={() => setStyle(s.id)}
                className="rounded-full border px-3 py-1.5 text-sm"
                style={
                  style === s.id
                    ? { borderColor: "var(--accent)", background: "var(--surface2)", color: "var(--text)" }
                    : { borderColor: "var(--line)", color: "var(--text-dim)" }
                }
              >
                {s.name}
              </button>
            ))}
          </div>
        </div>
        <div className="grid gap-4 sm:grid-cols-2">
          <VoicePicker value={voiceThem} onChange={setVoiceThem} label="Their voice" />
          <VoicePicker value={voiceMe} onChange={setVoiceMe} label="Your voice" />
        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">
            Background (optional — gameplay clip, else a gradient)
          </label>
          <div className="mt-2">
            <SourceInput value={bg} onChange={setBg} placeholder="Gameplay / b-roll URL (optional)" />
          </div>
        </div>
      </div>

      <div className="mt-5 flex gap-2">
        <input
          className="field"
          value={topic}
          onChange={(e) => setTopic(e.target.value)}
          placeholder="Topic for AI to write a conversation about"
        />
        <button className="btn btn-ghost whitespace-nowrap px-3 text-sm" onClick={writeStory} disabled={gen}>
          {gen ? "Writing…" : "✨ AI write"}
        </button>
      </div>

      <div className="mt-4 space-y-2">
        {messages.map((m, i) => (
          <div key={i} className="flex items-center gap-2">
            <button
              className="btn btn-ghost px-2 py-1 text-xs"
              onClick={() => setMsg(i, { from: m.from === "me" ? "them" : "me" })}
              title="Toggle sender"
            >
              {m.from === "me" ? "me →" : "← them"}
            </button>
            <input
              className="field text-sm"
              value={m.text}
              onChange={(e) => setMsg(i, { text: e.target.value })}
              placeholder="Message text"
            />
            {messages.length > 2 && (
              <button
                className="btn btn-ghost px-2 py-1 text-xs"
                style={{ color: "#ff6b6b" }}
                onClick={() => setMessages((ms) => ms.filter((_, idx) => idx !== i))}
              >
                ✕
              </button>
            )}
          </div>
        ))}
        <button
          className="btn btn-ghost w-full py-2 text-sm"
          onClick={() =>
            setMessages((ms) => [
              ...ms,
              { from: ms[ms.length - 1]?.from === "me" ? "them" : "me", text: "" },
            ])
          }
        >
          + Add message
        </button>
      </div>

      {err && <p className="mt-4 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
      <button className="btn btn-primary mt-5 w-full py-3" onClick={run} disabled={busy}>
        {busy ? "Rendering…" : "Generate text story"}
      </button>
      <RenderResult job={job} />
        </div>
        <div className="justify-self-center lg:sticky lg:top-6 lg:self-start">
          <LivePreview segments={previewSegments} />
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { BACKGROUNDS } from "@/lib/backgrounds";

export type Background =
  | { type: "gradient"; idx: number }
  | { type: "upload"; path: string; name: string }
  | { type: "clip"; url: string; label?: string };

type Tab = "library" | "stock" | "upload" | "url";

export function BackgroundPicker({
  value,
  onChange,
}: {
  value: Background;
  onChange: (b: Background) => void;
}) {
  const [tab, setTab] = useState<Tab>("library");
  const [uploading, setUploading] = useState(false);
  const [url, setUrl] = useState("");
  const [stock, setStock] = useState<{ thumbnail: string; url: string }[] | null>(null);
  const [stockEnabled, setStockEnabled] = useState(true);
  const [q, setQ] = useState("satisfying");
  const [loading, setLoading] = useState(false);

  const searchStock = async (query: string) => {
    setLoading(true);
    try {
      const res = await fetch(`/api/library/stock?q=${encodeURIComponent(query)}`);
      const d = await res.json();
      setStockEnabled(d.enabled);
      setStock(d.results);
    } catch {
      setStock([]);
    }
    setLoading(false);
  };

  useEffect(() => {
    if (tab === "stock" && stock === null) void searchStock(q);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab]);

  const upload = async (file: File) => {
    setUploading(true);
    const fd = new FormData();
    fd.append("file", file);
    const res = await fetch("/api/upload", { method: "POST", body: fd });
    if (res.ok) {
      const { path } = await res.json();
      onChange({ type: "upload", path, name: file.name });
    }
    setUploading(false);
  };

  const TABS: [Tab, string][] = [
    ["library", "Animated"],
    ["stock", "Stock"],
    ["upload", "Upload"],
    ["url", "Paste URL"],
  ];

  return (
    <div>
      <div className="mb-3 flex gap-2 text-sm">
        {TABS.map(([t, label]) => (
          <button
            key={t}
            onClick={() => setTab(t)}
            className="rounded-full border px-3 py-1"
            style={
              tab === t
                ? { borderColor: "var(--accent)", background: "var(--surface2)", color: "var(--text)" }
                : { borderColor: "var(--line)", color: "var(--text-dim)" }
            }
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "library" && (
        <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
          {BACKGROUNDS.map((b) => {
            const sel = value.type === "gradient" && value.idx === b.idx;
            return (
              <button
                key={b.idx}
                title={b.name}
                onClick={() => onChange({ type: "gradient", idx: b.idx })}
                className="rounded-lg"
                style={{
                  background: b.css,
                  aspectRatio: "9 / 16",
                  border: sel ? "2px solid var(--accent)" : "2px solid transparent",
                }}
              />
            );
          })}
        </div>
      )}

      {tab === "stock" &&
        (!stockEnabled ? (
          <p className="t-mute text-xs">
            Stock backgrounds need a <code>PEXELS_API_KEY</code> (free) on the server. Meanwhile,
            use the Animated tab, an upload, or a URL.
          </p>
        ) : (
          <div>
            <div className="mb-2 flex gap-2">
              <input
                className="field"
                value={q}
                onChange={(e) => setQ(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && searchStock(q)}
                placeholder="e.g. satisfying, city, nature…"
              />
              <button className="btn btn-ghost px-3 text-sm" onClick={() => searchStock(q)}>
                {loading ? "…" : "Search"}
              </button>
            </div>
            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
              {(stock || []).map((s, i) => {
                const sel = value.type === "clip" && value.url === s.url;
                return (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    key={i}
                    src={s.thumbnail}
                    alt=""
                    onClick={() => onChange({ type: "clip", url: s.url, label: "stock clip" })}
                    className="cursor-pointer rounded-lg object-cover"
                    style={{ aspectRatio: "9 / 16", border: sel ? "2px solid var(--accent)" : "2px solid transparent" }}
                  />
                );
              })}
            </div>
          </div>
        ))}

      {tab === "upload" && (
        <label className="btn btn-ghost cursor-pointer px-4 py-2 text-sm">
          {uploading
            ? "Uploading…"
            : value.type === "upload"
              ? `📎 ${value.name}`
              : "Choose a video file"}
          <input
            type="file"
            accept="video/*"
            className="hidden"
            onChange={(e) => e.target.files?.[0] && upload(e.target.files[0])}
          />
        </label>
      )}

      {tab === "url" && (
        <input
          className="field"
          value={value.type === "clip" ? value.url : url}
          onChange={(e) => {
            setUrl(e.target.value);
            onChange(e.target.value ? { type: "clip", url: e.target.value } : { type: "gradient", idx: 0 });
          }}
          placeholder="YouTube / TikTok / direct video URL"
        />
      )}
    </div>
  );
}

