"use client";

import { useState } from "react";
import { RenderResult, useRender } from "@/lib/useRender";
import { LivePreview, VOICE_FX, type PreviewSegment } from "@/components/live-preview";
import { CaptionPicker, SourceInput, ToolHeader, VoicePicker, type Source } from "@/components/tool-ui";

export default function VideoStoryBuilder() {
  const { job, busy, err, setErr, start } = useRender();
  const [script, setScript] = useState("");
  const [voice, setVoice] = useState("ash");
  const [caption, setCaption] = useState("pop");
  const [bg, setBg] = useState<Source>(null);

  const run = () => {
    const lines = script
      .split(/\n+/)
      .map((l) => l.trim())
      .filter(Boolean);
    if (lines.length === 0) return setErr("Write a script — each line becomes a scene.");
    const background = bg?.type === "url" ? { type: "clip", url: bg.url } : { type: "gradient" };
    start("video_story", lines[0].slice(0, 40), {
      voice,
      caption,
      scenes: lines.map((narration) => ({ narration, background })),
    });
  };

  const vbgLabel = bg?.type === "url" ? "background clip" : bg?.type === "upload" ? bg.name : undefined;
  const previewSegments: PreviewSegment[] = script
    .split(/\n+/)
    .map((l) => l.trim())
    .filter(Boolean)
    .map((narration, i) => ({
      gradIdx: i,
      clipLabel: vbgLabel,
      narration,
      captionStyle: caption,
      ...VOICE_FX[voice],
    }));

  return (
    <div className="mx-auto max-w-5xl px-6 py-8">
      <ToolHeader
        icon="📱"
        title="Video Story"
        desc="A narrated story over gameplay or gradients, with word-timed captions. Each line becomes a scene."
      />
      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_270px]">
        <div>
      <div className="card space-y-5 p-5">
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">Script</label>
          <textarea
            className="field mt-2"
            rows={7}
            value={script}
            onChange={(e) => setScript(e.target.value)}
            placeholder={"One line per scene…\nThe hook goes first.\nThen the build-up.\nThen the payoff."}
          />
        </div>
        <div className="grid gap-4 sm:grid-cols-2">
          <VoicePicker value={voice} onChange={setVoice} />
          <CaptionPicker value={caption} onChange={setCaption} />
        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">
            Background clip (optional)
          </label>
          <div className="mt-2">
            <SourceInput value={bg} onChange={setBg} placeholder="Gameplay / b-roll URL (optional)" />
          </div>
        </div>
      </div>
      {err && <p className="mt-4 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
      <button className="btn btn-primary mt-5 w-full py-3" onClick={run} disabled={busy}>
        {busy ? "Rendering…" : "Generate video story"}
      </button>
      <RenderResult job={job} />
        </div>
        <div className="justify-self-center lg:sticky lg:top-6 lg:self-start">
          <LivePreview segments={previewSegments} />
        </div>
      </div>
    </div>
  );
}

