"use client";

import { useRef, useState } from "react";
import Link from "next/link";
import { api, type Job } from "@/lib/api";
import { CAPTIONS, VOICES } from "@/lib/presets";
import { LivePreview, VOICE_FX, type PreviewSegment } from "@/components/live-preview";

interface Rank {
  url: string;
  narration: string;
}

export default function RankingBuilder() {
  const [title, setTitle] = useState("Top 5 Snake Attacks");
  const [voice, setVoice] = useState("atlas");
  const [caption, setCaption] = useState("pop");
  const [clipSeconds, setClipSeconds] = useState(6);
  const [ranks, setRanks] = useState<Rank[]>([
    { url: "", narration: "" },
    { url: "", narration: "" },
  ]);
  const [err, setErr] = useState("");
  const [job, setJob] = useState<Job | null>(null);
  const [busy, setBusy] = useState(false);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const setRank = (i: number, patch: Partial<Rank>) =>
    setRanks((rs) => rs.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  const move = (i: number, d: number) => {
    const j = i + d;
    if (j < 0 || j >= ranks.length) return;
    const rs = [...ranks];
    [rs[i], rs[j]] = [rs[j], rs[i]];
    setRanks(rs);
  };

  const generate = async () => {
    const filled = ranks.filter((r) => r.url.trim());
    if (filled.length < 2) return setErr("Add at least two clip URLs.");
    setErr("");
    setBusy(true);
    try {
      const config = {
        title,
        voice,
        caption,
        clipSeconds,
        // First slot shown is the highest rank number (countdown to #1).
        ranks: filled.map((r, i) => ({
          rank: filled.length - i,
          url: r.url.trim(),
          narration: r.narration.trim(),
        })),
      };
      const { project } = await api.createProject("ranking", title, config);
      const { job: j } = await api.render(project.id);
      setJob(j);
      pollRef.current = setInterval(async () => {
        try {
          const { job: cur } = await api.getJob(j.id);
          setJob(cur);
          if (cur.status === "done" || cur.status === "error") {
            if (pollRef.current) clearInterval(pollRef.current);
            setBusy(false);
          }
        } catch {
          if (pollRef.current) clearInterval(pollRef.current);
          setBusy(false);
        }
      }, 2000);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Failed to start render.");
      setBusy(false);
    }
  };

  const videoAsset = job?.assets.find((a) => a.kind === "video");
  const srtAsset = job?.assets.find((a) => a.kind === "srt");

  const filledRanks = ranks.filter((r) => r.url.trim());
  const previewSegments: PreviewSegment[] = filledRanks.map((r, i) => ({
    gradIdx: i,
    clipLabel: `clip ${i + 1}`,
    title,
    rank: filledRanks.length - i,
    narration: r.narration.trim() || undefined,
    captionStyle: caption,
    estSeconds: clipSeconds,
    ...VOICE_FX[voice],
  }));

  return (
    <div className="mx-auto max-w-5xl px-6 py-8">
      <Link href="/app" className="t-dim text-sm">
        ← Studio
      </Link>
      <h1 className="font-display mt-3 text-3xl font-bold">🏆 Video Ranking</h1>
      <p className="t-dim mt-1">
        Paste YouTube, TikTok, or Instagram clips — VidForge downloads them and builds a Top-N
