"use client";

import { useRef, useState } from "react";
import Link from "next/link";
import { api, type Job } from "@/lib/api";
import { CAPTIONS, VOICES } from "@/lib/presets";
import { LivePreview, VOICE_FX, type PreviewSegment } from "@/components/live-preview";

interface Rank {
  url: string;
  narration: string;
  trimStart?: number;
  trimEnd?: number;
}

export default function RankingBuilder() {
  const [title, setTitle] = useState("Top 5 Snake Attacks");
  const [voice, setVoice] = useState("atlas");
  const [caption, setCaption] = useState("pop");
  const [clipSeconds, setClipSeconds] = useState(6);
  const [ranks, setRanks] = useState<Rank[]>([
    { url: "", narration: "" },
    { url: "", narration: "" },
  ]);
  const [err, setErr] = useState("");
  const [job, setJob] = useState<Job | null>(null);
  const [busy, setBusy] = useState(false);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const setRank = (i: number, patch: Partial<Rank>) =>
    setRanks((rs) => rs.map((r, idx) => (idx === i ? { ...r, ...patch } : r)));
  const move = (i: number, d: number) => {
    const j = i + d;
    if (j < 0 || j >= ranks.length) return;
    const rs = [...ranks];
    [rs[i], rs[j]] = [rs[j], rs[i]];
    setRanks(rs);
  };

  const generate = async () => {
    const filled = ranks.filter((r) => r.url.trim());
    if (filled.length < 2) return setErr("Add at least two clip URLs.");
    setErr("");
    setBusy(true);
    try {
      const config = {
        title,
        voice,
        caption,
        clipSeconds,
        // First slot shown is the highest rank number (countdown to #1).
        ranks: filled.map((r, i) => ({
          rank: filled.length - i,
          url: r.url.trim(),
          narration: r.narration.trim(),
        })),
      };
      const { project } = await api.createProject("ranking", title, config);
      const { job: j } = await api.render(project.id);
      setJob(j);
      pollRef.current = setInterval(async () => {
        try {
          const { job: cur } = await api.getJob(j.id);
          setJob(cur);
          if (cur.status === "done" || cur.status === "error") {
            if (pollRef.current) clearInterval(pollRef.current);
            setBusy(false);
          }
        } catch {
          if (pollRef.current) clearInterval(pollRef.current);
          setBusy(false);
        }
      }, 2000);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Failed to start render.");
      setBusy(false);
    }
  };

  const videoAsset = job?.assets.find((a) => a.kind === "video");
  const srtAsset = job?.assets.find((a) => a.kind === "srt");

  const filledRanks = ranks.filter((r) => r.url.trim());
  const previewSegments: PreviewSegment[] = filledRanks.map((r, i) => ({
    gradIdx: i,
    clipLabel: `clip ${i + 1}`,
    title,
    rank: filledRanks.length - i,
    narration: r.narration.trim() || undefined,
    captionStyle: caption,
    estSeconds: clipSeconds,
    ...VOICE_FX[voice],
  }));

  return (
    <div className="mx-auto max-w-5xl px-6 py-8">
      <Link href="/app" className="t-dim text-sm">
        ← Studio
      </Link>
      <h1 className="font-display mt-3 text-3xl font-bold">🏆 Video Ranking</h1>
      <p className="t-dim mt-1">
        Paste YouTube, TikTok, or Instagram clips — VidForge downloads them and builds a Top-N
        countdown with titles, rank numbers, voiceover, and captions.
      </p>

      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_270px]">
        <div>
      <div className="card space-y-5 p-5">
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">Title</label>
          <input
            className="field mt-2"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Top 5 …"
          />
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">Voice</label>
            <select className="field mt-2" value={voice} onChange={(e) => setVoice(e.target.value)}>
              {VOICES.map((v) => (
                <option key={v.id} value={v.id}>
                  {v.name} — {v.tag}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">Captions</label>
            <select
              className="field mt-2"
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
            >
              {CAPTIONS.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">
            Clip length (seconds, when no voiceover)
          </label>
          <input
            className="field mt-2"
            type="number"
            min={2}
            max={20}
            value={clipSeconds}
            onChange={(e) => setClipSeconds(Number(e.target.value) || 6)}
          />
        </div>
      </div>

      <div className="mt-5 space-y-3">
        {ranks.map((r, i) => (
          <div key={i} className="card p-4">
            <div className="flex items-center justify-between">
              <span className="font-display font-bold">
                #{ranks.length - i} ·{" "}
                {i === 0 ? "plays first" : i === ranks.length - 1 ? "plays last" : "countdown"}
              </span>
              <div className="flex gap-1.5">
                <button className="btn btn-ghost px-2 py-1 text-xs" onClick={() => move(i, -1)}>
                  ↑
                </button>
                <button className="btn btn-ghost px-2 py-1 text-xs" onClick={() => move(i, 1)}>
                  ↓
                </button>
                {ranks.length > 2 && (
                  <button
                    className="btn btn-ghost px-2 py-1 text-xs"
                    style={{ color: "#ff6b6b" }}
                    onClick={() => setRanks((rs) => rs.filter((_, idx) => idx !== i))}
                  >
                    ✕
                  </button>
                )}
              </div>
            </div>
            <input
              className="field mt-3"
              value={r.url}
              onChange={(e) => setRank(i, { url: e.target.value })}
              placeholder="YouTube / TikTok / Instagram URL"
            />
            <input
              className="field mt-2 text-sm"
              value={r.narration}
              onChange={(e) => setRank(i, { narration: e.target.value })}
              placeholder="Optional voiceover for this rank (leave blank to use the clip's own audio)"
            />
          </div>
        ))}
        <button
          className="btn btn-ghost w-full py-2.5 text-sm"
          onClick={() => setRanks((rs) => [...rs, { url: "", narration: "" }])}
        >
          + Add clip
        </button>
      </div>

      {err && <p className="mt-4 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}

      <button className="btn btn-primary mt-5 w-full py-3" onClick={generate} disabled={busy}>
        {busy ? "Rendering…" : "Generate ranking video"}
      </button>

      {job && (
        <div className="card mt-5 p-5 text-center">
          {job.status === "done" && videoAsset ? (
            <>
              <p className="font-display text-lg font-bold">✅ Your ranking is ready</p>
              <div className="mt-4 grid gap-2">
                <a className="btn btn-primary py-2.5" href={`/api/assets/${videoAsset.id}`}>
                  Download video (.mp4)
                </a>
                {srtAsset && (
                  <a className="btn btn-ghost py-2.5" href={`/api/assets/${srtAsset.id}`}>
                    Download captions (.srt)
                  </a>
