input.content:
"use client";

/** Numbered step header (Viblo-style wizard). Steps are clickable. */
export function Stepper({
  steps,
  step,
  onStep,
}: {
  steps: string[];
  step: number;
  onStep: (n: number) => void;
}) {
  return (
    <div className="mb-5 flex flex-wrap items-center gap-x-2 gap-y-2">
      {steps.map((label, i) => {
        const active = i === step;
        const done = i < step;
        return (
          <button
            key={label}
            onClick={() => onStep(i)}
            className="flex items-center gap-2 text-sm"
            style={{ color: active ? "var(--text)" : "var(--text-dim)" }}
          >
            <span
              className="flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold"
              style={{
                background: active || done ? "var(--accent)" : "var(--surface2)",
                color: active || done ? "#fff" : "var(--text-mute)",
              }}
            >
              {done ? "✓" : i + 1}
            </span>
            <span className={active ? "font-semibold" : ""}>{label}</span>
            {i < steps.length - 1 && <span className="t-mute mx-1">›</span>}
          </button>
        );
      })}
    </div>
  );
}

