  { id: "messenger", name: "Messenger" },
];

const STEPS = ["Template", "Script", "Voices", "Background"];

export default function TextStoryBuilder() {
  const { job, busy, err, setErr, start } = useRender();
  const [step, setStep] = useState(0);
  const [contact, setContact] = useState("Grace");
  const [style, setStyle] = useState("imessage");
  const [dark, setDark] = useState(false);
