import { createReadStream, statSync } from "fs";
import path from "path";
import { Readable } from "stream";
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";

const DATA_DIR = process.env.RENDER_DATA_DIR || "/data";

const EXT: Record<string, string> = { srt: "srt", txt: "txt", audio: "mp3", video: "mp4", image: "png", source: "mp4" };
const TYPE: Record<string, string> = {
  srt: "text/plain; charset=utf-8",
  txt: "text/plain; charset=utf-8",
  audio: "audio/mpeg",
  video: "video/mp4",
  image: "image/png",
  source: "video/mp4",
};

/** Stream an asset to its owner. `?inline=1` serves inline (for <video>/<img>
    preview); otherwise it downloads. Supports HTTP range so video playback
    and seeking work. */
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  const { id } = await params;

  const asset = await db.asset.findUnique({
    where: { id },
    include: { project: { select: { userId: true, title: true } } },
  });
  if (!asset || asset.project?.userId !== user.id) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  const abs = path.resolve(DATA_DIR, asset.path);
  if (!abs.startsWith(path.resolve(DATA_DIR) + path.sep)) {
    return NextResponse.json({ error: "invalid path" }, { status: 400 });
  }

  let size: number;
  try {
    size = statSync(abs).size;
  } catch {
    return NextResponse.json({ error: "file missing" }, { status: 404 });
  }

  const url = new URL(req.url);
  const inline = url.searchParams.get("inline") === "1";
  const type = TYPE[asset.kind] || "application/octet-stream";
  const ext = EXT[asset.kind] || "mp4";
  const slug = (asset.project?.title || "vidforge").replace(/\W+/g, "-").toLowerCase();

  const disposition = inline
    ? "inline"
    : `attachment; filename="${slug}.${ext}"`;

  // Range request (video seeking / progressive playback)
  const range = req.headers.get("range");
  if (range && type.startsWith("video")) {
    const m = /bytes=(\d+)-(\d*)/.exec(range);
    if (m) {
      const start = Number(m[1]);
      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
      const chunk = end - start + 1;
      const stream = Readable.toWeb(createReadStream(abs, { start, end })) as ReadableStream;
      return new NextResponse(stream, {
        status: 206,
        headers: {
          "Content-Type": type,
          "Content-Length": String(chunk),
          "Content-Range": `bytes ${start}-${end}/${size}`,
          "Accept-Ranges": "bytes",
          "Content-Disposition": disposition,
        },
      });
    }
  }

  const stream = Readable.toWeb(createReadStream(abs)) as ReadableStream;
  return new NextResponse(stream, {
    headers: {
      "Content-Type": type,
      "Content-Length": String(size),
      "Accept-Ranges": "bytes",
      "Content-Disposition": disposition,
    },
  });
}

