import { NextResponse } from "next/server";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getSessionUser } from "@/lib/auth";

const DOWNLOADER_URL = process.env.DOWNLOADER_URL || "http://downloader:8000";

/** Downloads a pasted clip URL server-side and returns a playable inline URL,
    so the builder preview can show the actual video (not a placeholder).
    Free — no credit charge; this is a preview helper. Re-uses the download
    for the render. */
export async function POST(request: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: { url?: string };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "invalid JSON body" }, { status: 400 });
  }
  const url = (body.url || "").trim();
  if (!url) return NextResponse.json({ error: "url required" }, { status: 400 });

  let dl: { path: string; title?: string; width?: number; height?: number };
  try {
    const res = await fetch(`${DOWNLOADER_URL}/download`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ url }),
    });
    const data = await res.json();
    if (!res.ok) {
      return NextResponse.json({ error: data.detail || "couldn't load that clip" }, { status: 502 });
    }
    dl = data;
  } catch {
    return NextResponse.json({ error: "downloader unreachable" }, { status: 502 });
  }

  const project = await db.project.create({
    data: {
      userId: user.id,
      type: "source",
      title: dl.title || url,
      config: { url } as Prisma.InputJsonValue,
      status: "done",
    },
  });
  const asset = await db.asset.create({
    data: { projectId: project.id, kind: "source", path: `downloads/${dl.path}` },
  });

  return NextResponse.json({
    assetId: asset.id,
    playUrl: `/api/assets/${asset.id}?inline=1`,
    width: dl.width,
    height: dl.height,
  });
}

