    ["url", "Paste URL"],
  ];

  return (
    <div>
      <div className="mb-3 flex gap-2 text-sm">
        {TABS.map(([t, label]) => (
          <button
            key={t}
            onClick={() => selectTab(t)}
            className="rounded-full border px-3 py-1"
            style={
              tab === t
                ? { borderColor: "var(--accent)", background: "var(--surface2)", color: "var(--text)" }
                : { borderColor: "var(--line)", color: "var(--text-dim)" }
            }
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "library" && (
        <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
          {BACKGROUNDS.map((b) => {
            const sel = value.type === "gradient" && value.idx === b.idx;
            return (
              <button
                key={b.idx}
                title={b.name}
                onClick={() => onChange({ type: "gradient", idx: b.idx })}
                className="rounded-lg"
                style={{
                  background: b.css,
                  aspectRatio: "9 / 16",
                  border: sel ? "2px solid var(--accent)" : "2px solid transparent",
                }}
              />
            );
          })}
        </div>
      )}

      {tab === "stock" &&
        (!stockEnabled ? (
          <p className="t-mute text-xs">
            Stock backgrounds need a <code>PEXELS_API_KEY</code> (free) on the server. Meanwhile,
            use the Animated tab, an upload, or a URL.
          </p>
        ) : (
          <div>
            <div className="mb-2 flex gap-2">
              <input
                className="field"
                value={q}
                onChange={(e) => setQ(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && searchStock(q)}
                placeholder="e.g. satisfying, city, nature…"
              />
              <button className="btn btn-ghost px-3 text-sm" onClick={() => searchStock(q)}>
                {loading ? "…" : "Search"}
              </button>
            </div>
            <div className="grid grid-cols-4 gap-2 sm:grid-cols-6">
              {(stock || []).map((s, i) => {
                const sel = value.type === "clip" && value.url === s.url;
                return (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    key={i}
                    src={s.thumbnail}
                    alt=""
                    onClick={() => onChange({ type: "clip", url: s.url, label: "stock clip", previewUrl: s.url })}
                    className="cursor-pointer rounded-lg object-cover"
                    style={{ aspectRatio: "9 / 16", border: sel ? "2px solid var(--accent)" : "2px solid transparent" }}
                  />
                );
              })}
            </div>
          </div>
        ))}

      {tab === "upload" && (
        <label className="btn btn-ghost cursor-pointer px-4 py-2 text-sm">
          {uploading
            ? "Uploading…"
            : value.type === "upload"
              ? `📎 ${value.name}`
              : "Choose a video file"}
          <input
            type="file"
            accept="video/*"
            className="hidden"
            onChange={(e) => e.target.files?.[0] && upload(e.target.files[0])}
          />
        </label>
      )}

      {tab === "url" && (
        <div>
          <div className="flex gap-2">
            <input
              className="field"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && resolveUrl()}
              placeholder="YouTube / TikTok / Instagram / direct video URL"
            />
            <button className="btn btn-primary whitespace-nowrap px-4 text-sm" onClick={resolveUrl} disabled={resolving}>
              {resolving ? "Loading…" : "Load"}
            </button>
          </div>
          {resolveErr && <p className="mt-2 text-xs" style={{ color: "#ff6b6b" }}>{resolveErr}</p>}
          {value.type === "clip" && value.previewUrl && (
            <p className="mt-2 text-xs" style={{ color: "var(--good)" }}>✓ Clip loaded — see the preview.</p>
          )}
        </div>
      )}
    </div>
  );
}

