      const { path } = await res.json();
      onChange({ type: "upload", path, name: file.name, previewUrl: URL.createObjectURL(file) });
    } catch (e) {
      setErr(e instanceof Error ? e.message : "upload failed");
    }
    setUploading(false);
  };

