"use client";

import { useState } from "react";
import { RenderResult, useRender } from "@/lib/useRender";
import { LivePreview, VOICE_FX, type PreviewSegment } from "@/components/live-preview";
import {
  CaptionPicker,
  SourceInput,
  ToolHeader,
  VoicePicker,
  generate,
  type Source,
} from "@/components/tool-ui";

export default function CommentaryBuilder() {
  const { job, busy, err, setErr, start } = useRender();
  const [mode, setMode] = useState<"subtitle" | "voiceover">("subtitle");
  const [source, setSource] = useState<Source>(null);
  const [script, setScript] = useState("");
  const [topic, setTopic] = useState("");
  const [voice, setVoice] = useState("atlas");
  const [caption, setCaption] = useState("pop");
  const [gen, setGen] = useState(false);

  const writeScript = async () => {
    if (!topic.trim()) return setErr("Add a topic for the AI to write about.");
    setGen(true);
    setErr("");
    try {
      const { result } = await generate("commentary", topic, "dramatic");
      setScript((result as { script: string }).script);
    } catch {
      setErr("Couldn't generate a script.");
    }
    setGen(false);
  };

  const run = () => {
    if (!source) return setErr("Add a clip (URL or upload).");
    if (mode === "voiceover" && !script.trim())
      return setErr("Write or generate a commentary script.");
    const srcCfg =
      source.type === "url" ? { type: "url", url: source.url } : { type: "upload", path: source.path };
    start("commentary", topic || "Commentary", { mode, voice, caption, script, source: srcCfg });
  };

  const previewSegments: PreviewSegment[] = [
    {
      gradIdx: 0,
      clipLabel: source ? (source.type === "url" ? "your clip" : source.name) : "your clip",
      narration: mode === "voiceover" ? script.trim() || undefined : undefined,
      captionStyle: caption,
      ...VOICE_FX[voice],
    },
  ];

  return (
    <div className="mx-auto max-w-5xl px-6 py-8">
      <ToolHeader
        icon="🎙️"
        title="Video Commentary"
        desc="Drop a clip and VidForge lays an AI or your-own voiceover over it, with captions."
      />
      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_270px]">
        <div>
      <div className="card space-y-5 p-5">
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">Mode</label>
          <div className="mt-2 grid grid-cols-2 gap-2">
            <button
              className="rounded-lg border p-3 text-left text-sm"
              onClick={() => setMode("subtitle")}
              style={
                mode === "subtitle"
                  ? { borderColor: "var(--accent)", background: "var(--surface2)" }
                  : { borderColor: "var(--line)" }
              }
            >
              <div className="font-semibold">Subtitles</div>
              <div className="t-dim text-xs">Keep the clip &amp; its audio, auto-caption its speech.</div>
            </button>
            <button
              className="rounded-lg border p-3 text-left text-sm"
              onClick={() => setMode("voiceover")}
              style={
                mode === "voiceover"
                  ? { borderColor: "var(--accent)", background: "var(--surface2)" }
                  : { borderColor: "var(--line)" }
              }
            >
              <div className="font-semibold">Voiceover</div>
              <div className="t-dim text-xs">Add an AI/your voiceover over the clip.</div>
            </button>
          </div>
        </div>
        <div>
          <label className="t-dim text-xs font-bold uppercase tracking-widest">Clip</label>
          <div className="mt-2">
            <SourceInput value={source} onChange={setSource} />
          </div>
        </div>
        {mode === "voiceover" && (
          <div>
            <label className="t-dim text-xs font-bold uppercase tracking-widest">
              Commentary script
            </label>
            <div className="mt-2 flex gap-2">
              <input
                className="field"
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="Topic for AI to write about (optional)"
              />
              <button className="btn btn-ghost whitespace-nowrap px-3 text-sm" onClick={writeScript} disabled={gen}>
                {gen ? "Writing…" : "✨ AI write"}
              </button>
            </div>
            <textarea
              className="field mt-2"
              rows={4}
              value={script}
              onChange={(e) => setScript(e.target.value)}
              placeholder="Your spoken commentary…"
            />
          </div>
        )}
        {mode === "subtitle" && (
          <p className="t-mute text-xs">
            Captions are transcribed automatically from the clip&apos;s own audio.
          </p>
        )}
        <div className="grid gap-4 sm:grid-cols-2">
          {mode === "voiceover" && <VoicePicker value={voice} onChange={setVoice} />}
          <CaptionPicker value={caption} onChange={setCaption} />
        </div>
      </div>
      {err && <p className="mt-4 text-sm" style={{ color: "#ff6b6b" }}>{err}</p>}
      <button className="btn btn-primary mt-5 w-full py-3" onClick={run} disabled={busy}>
        {busy ? "Rendering…" : "Generate commentary video"}
      </button>
      <RenderResult job={job} />
        </div>
        <div className="justify-self-center lg:sticky lg:top-6 lg:self-start">
          <LivePreview segments={previewSegments} />
        </div>
      </div>
    </div>
  );
}

